import type { BankQuestion } from "@/lib/bank";

/** Permutations, Combinations and Probability (Placement) (Placement Aptitude): 570 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "apt-pnc-probability-1", "question": "In how many different ways can the letters of the word PLACE be arranged?", "options": ["24", "720", "60", "120"], "answer": 3, "explanation": "All 5 letters are different, so the arrangements are 5! = 5 × 4 × 3 × 2 × 1 = 120. 24 is 4!, which leaves out one letter.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-2", "question": "A team of 3 has to be picked from 7 trainees. In how many ways can this be done?", "options": ["210", "42", "35", "21"], "answer": 2, "explanation": "Order does not matter in a team, so it is 7C3 = (7 × 6 × 5)/(3 × 2 × 1) = 35. 210 is 7P3, which counts the same team 3! = 6 times.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-3", "question": "Two fair dice are thrown together. What is the probability that the total is 10 or more?", "options": ["1/6", "1/12", "1/4", "5/36"], "answer": 0, "explanation": "Totals of 10 or more: (4,6), (5,5), (6,4), (5,6), (6,5), (6,6) — 6 of the 36 outcomes, so 6/36 = 1/6. 1/12 counts only the totals of exactly 10.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-4", "question": "One card is drawn from a well-shuffled pack of 52 cards. What is the probability that it is a face card (jack, queen or king) or a spade?", "options": ["1/4", "3/13", "11/26", "25/52"], "answer": 2, "explanation": "Face cards 12 + spades 13 − face cards that are spades 3 = 22 cards, so 22/52 = 11/26. 25/52 counts the three spade face cards twice.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-5", "question": "Three fair coins are tossed. What is the probability of getting exactly two heads?", "options": ["3/4", "3/8", "1/2", "1/4"], "answer": 1, "explanation": "Of the 8 equally likely outcomes, HHT, HTH and THH have exactly two heads: 3/8.", "difficulty": "easy", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-6", "question": "At a meeting, each of 12 people shakes hands with every other person exactly once. How many handshakes take place?", "options": ["144", "132", "66", "78"], "answer": 2, "explanation": "Each handshake is a pair of people: 12C2 = (12 × 11)/2 = 66. 132 counts each handshake twice (once from each side).", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-7", "question": "How many distinct arrangements of the letters of the word BANANA are possible?", "options": ["720", "120", "36", "60"], "answer": 3, "explanation": "6 letters with A repeated 3 times and N twice: 6!/(3! × 2!) = 720/12 = 60.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-8", "question": "In how many ways can 7 people sit around a circular table if two particular people, Meena and Neha, must sit next to each other?", "options": ["720", "120", "1440", "240"], "answer": 3, "explanation": "Glue Meena and Neha into one unit: 6 units around a table give (6 − 1)! = 120 arrangements, and the pair can sit in 2 orders: 120 × 2 = 240. 1440 = 6! × 2 forgets that a circle has no fixed first seat.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id":"apt-pnc-probability-9","question":"A convex polygon has exactly 20 diagonals. How many sides does it have?","options":["8","5","23","10"],"answer":0,"explanation":"A polygon with n sides has n(n − 3)/2 diagonals, so n(n − 3) = 40, (n − 8)(n + 5) = 0 and n = 8. Factoring with the signs swapped, (n + 8)(n − 5), gives 5; using the n − 3 diagonals from one vertex gives 23; and a decagon has 35 diagonals, not 20.","difficulty":"easy","source":"Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-10", "question": "How many 4-digit numbers can be formed using the digits 0, 1, 2, 3, 4, 5 if no digit is repeated?", "options": ["300", "360", "240", "180"], "answer": 0, "explanation": "The first digit cannot be 0: 5 choices, then 5, 4 and 3 for the rest: 5 × 5 × 4 × 3 = 300. 360 = 6P4 forgets that a number cannot start with 0.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-11", "question": "Two cards are drawn one after another without replacement from a pack of 52. What is the probability that the first is a heart and the second is a spade?", "options": ["1/16", "13/204", "13/102", "1/17"], "answer": 1, "explanation": "(13/52) × (13/51) = 169/2652 = 13/204. 1/16 = (1/4)(1/4) assumes replacement; 13/102 counts both orders (heart–spade or spade–heart), which the question does not ask.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-12", "question": "A bag has 5 red and 3 blue balls. Two balls are drawn at random together. What is the probability that one is red and one is blue?", "options": ["15/56", "3/8", "15/64", "15/28"], "answer": 3, "explanation": "Favourable = 5C1 × 3C1 = 15; total = 8C2 = 28; probability 15/28. 15/56 counts only the order red-then-blue.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-13", "question": "From 5 men and 4 women, a committee of 4 is to be formed with exactly 2 women. In how many ways can it be done?", "options": ["72", "126", "60", "40"], "answer": 2, "explanation": "Choose 2 women from 4 (6 ways) and 2 men from 5 (10 ways): 6 × 10 = 60. 126 = 9C4 ignores the condition.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-14", "question": "In how many ways can the letters of the word MOBILE be arranged so that all the vowels come together?", "options": ["72", "144", "24", "720"], "answer": 1, "explanation": "Treat O, I, E as one block: M, B, L and the block give 4! = 24 orders, and the block can be arranged inside in 3! = 6 ways: 24 × 6 = 144. 24 alone forgets the internal order of the vowels.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-15", "question": "Two fair dice are thrown. What is the probability that the product of the two numbers is even?", "options": ["1/4", "3/4", "2/3", "1/2"], "answer": 1, "explanation": "The product is odd only when both numbers are odd: (1/2)(1/2) = 1/4. So P(even) = 1 − 1/4 = 3/4.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-16", "question": "In a game you roll a fair die once and win ₹ (number shown)². What is your expected winning, to the nearest paisa?", "options": ["₹15.17", "₹12.25", "₹3.50", "₹14.00"], "answer": 0, "explanation": "E = (1 + 4 + 9 + 16 + 25 + 36)/6 = 91/6 ≈ ₹15.17. ₹12.25 = 3.5² squares the average instead of averaging the squares.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-17", "question": "In how many ways can 8 identical chocolates be distributed among 3 children if a child may get none?", "options": ["56", "21", "36", "45"], "answer": 3, "explanation": "Stars and bars: the number of non-negative solutions of a + b + c = 8 is (8 + 2)C2 = 10C2 = 45. 21 = 7C2 would be the count when every child must get at least one.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "apt-pnc-probability-18", "question": "5 boys and 3 girls are to stand in a row so that no two girls are next to each other. How many arrangements are possible?", "options": ["14400", "720", "2880", "4320"], "answer": 0, "explanation": "Arrange the boys: 5! = 120. They create 6 gaps; choose and order 3 of them for the girls: 6P3 = 120. Total 120 × 120 = 14400.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-19", "question": "How many rectangles (including squares) can be found in a grid of 5 columns × 3 rows of unit squares?", "options": ["15", "120", "60", "90"], "answer": 3, "explanation": "A rectangle is fixed by choosing 2 of the 6 vertical lines and 2 of the 4 horizontal lines: 6C2 × 4C2 = 15 × 6 = 90.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-20", "question": "A number is picked at random from 1 to 50. What is the probability that it is divisible by 4 or by 6?", "options": ["7/25", "8/25", "2/5", "9/25"], "answer": 1, "explanation": "Multiples of 4: 12; of 6: 8; of both (multiples of 12): 4. 12 + 8 − 4 = 16, so 16/50 = 8/25. 2/5 = 20/50 forgets to remove 12, 24, 36, 48, which are counted twice.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-21", "question": "6 students come back to a classroom and sit down at random, one per seat. In how many ways can they sit so that exactly one student is in their own old seat?", "options": ["44", "264", "120", "265"], "answer": 1, "explanation": "Choose the one student who keeps the seat: 6 ways. The other 5 must all be away from their seats: D₅ = 44. 6 × 44 = 264. 265 = D₆ is the count where nobody keeps the seat.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-22", "question": "Five letters go at random into five addressed envelopes, one each. In how many ways do exactly two letters reach the correct envelope?", "options": ["10", "40", "20", "30"], "answer": 2, "explanation": "Choose the 2 correct letters: 5C2 = 10; the other 3 must all be wrong: D₃ = 2. Total 10 × 2 = 20. 10 forgets that the remaining three must all be misplaced.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-23", "question": "In how many ways can 3 distinct numbers be chosen from 1, 2, …, 20 so that their sum is even?", "options": ["570", "1140", "600", "450"], "answer": 0, "explanation": "There are 10 odd and 10 even numbers. Even sum: all three even (10C3 = 120) or two odd and one even (10C2 × 10 = 450). Total 120 + 450 = 570. 450 forgets the all-even case.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-24", "question": "In how many ways can 7 different beads be strung into a necklace (a necklace can be turned over)?", "options": ["2520", "720", "5040", "360"], "answer": 3, "explanation": "Circular arrangements: (7 − 1)! = 720. A necklace can be flipped, so each arrangement equals its mirror image: 720/2 = 360.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-25", "question": "Six friends sit around a round table. In how many arrangements do two particular friends, Amit and Bharat, NOT sit next to each other?", "options": ["72", "600", "96", "48"], "answer": 0, "explanation": "Total = 5! = 120. Amit and Bharat together: treat them as one unit, (5 − 1)! × 2 = 48. Not together = 120 − 48 = 72.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-26", "question": "How many solutions in integers does x + y + z = 12 have if each of x, y and z is at least 2?", "options": ["45", "91", "28", "55"], "answer": 2, "explanation": "Put x = a + 2 and so on: a + b + c = 6 with a, b, c ≥ 0, giving 8C2 = 28. 55 = 11C2 is the count for x, y, z ≥ 1.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "apt-pnc-probability-27", "question": "A family has two children. It is known that at least one of them is a boy. What is the probability that both are boys? (Boy and girl equally likely.)", "options": ["1/2", "1/4", "2/3", "1/3"], "answer": 3, "explanation": "Sample space BB, BG, GB, GG; 'at least one boy' leaves BB, BG, GB, so P = 1/3. 1/2 answers a different question: 'the elder child is a boy'.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-28", "question": "Machine A makes 60% of a factory's bolts and 2% of them are defective; machine B makes the remaining 40% and 3% of them are defective. A bolt picked at random is defective. What is the probability that it came from machine B?", "options": ["1/2", "3/100", "2/5", "3/5"], "answer": 0, "explanation": "P(defective) = 0.6 × 0.02 + 0.4 × 0.03 = 0.012 + 0.012 = 0.024. P(B | defective) = 0.012/0.024 = 1/2. 2/5 is just B's share of production, ignoring that B's defect rate is higher.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-29", "question": "All arrangements of the letters of MOTHER are written in dictionary order. What is the rank of the word MOTHER?", "options": ["289", "240", "309", "308"], "answer": 2, "explanation": "Letters in order: E, H, M, O, R, T. Words starting E or H: 2 × 5! = 240. M then E or H: 2 × 4! = 48. MO then E, H or R: 3 × 3! = 18. MOT then E: 1 × 2! = 2. Then MOTHER itself: 240 + 48 + 18 + 2 + 1 = 309. 308 forgets to count the word itself.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-30", "question": "In how many distinct ways can the letters of the word COMMITTEE be arranged?", "options": ["90720", "22680", "45360", "362880"], "answer": 2, "explanation": "9 letters with M, T and E each appearing twice: 9!/(2! × 2! × 2!) = 362880/8 = 45360.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-31", "question": "A fair die is thrown three times. What is the probability that the three numbers come out strictly increasing (first < second < third)?", "options": ["1/6", "5/54", "5/18", "5/9"], "answer": 1, "explanation": "Any 3 different numbers can appear in increasing order in exactly one way: 6C3 = 20 favourable outcomes out of 216, so 20/216 = 5/54. 5/9 = 120/216 is the chance that the three numbers are all different, in any order.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-32", "question": "On a city grid you walk from (0, 0) to (6, 4), moving one block east or one block north at a time. How many shortest routes pass through the junction (2, 2)?", "options": ["90", "210", "120", "60"], "answer": 0, "explanation": "(0,0) to (2,2): 4C2 = 6 routes; (2,2) to (6,4): 4 east + 2 north = 6C2 = 15 routes. 6 × 15 = 90. 210 = 10C4 is all shortest routes, ignoring the junction.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-33", "question": "12 points lie in a plane, and 5 of them are on one straight line; no other three points are collinear. How many different straight lines can be drawn through pairs of these points?", "options": ["56", "57", "66", "62"], "answer": 1, "explanation": "Pairs of points: 12C2 = 66. The 5 collinear points form 5C2 = 10 pairs that all give the same single line, so 66 − 10 + 1 = 57. 56 forgets to add back that one line.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-34", "question": "In how many ways can 9 different books be divided into 3 groups of 3 books each (the groups are not labelled)?", "options": ["1680", "84", "280", "560"], "answer": 2, "explanation": "Labelled groups: 9!/(3! 3! 3!) = 1680. The 3 groups are interchangeable, so divide by 3!: 1680/6 = 280.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "apt-pnc-probability-35", "question": "A shooter hits a target with probability 0.4 on each shot, independently. What is the least number of shots needed so that the probability of at least one hit is more than 0.9?", "options": ["4", "6", "3", "5"], "answer": 3, "explanation": "P(no hit in n shots) = 0.6ⁿ must be below 0.1. 0.6⁴ = 0.1296 is too big; 0.6⁵ = 0.07776 works, so n = 5. 3 comes from 0.4 × 3 > 0.9, wrongly adding probabilities.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-36", "question": "A fair die is rolled 3 times. What is the expected number of different faces that appear?", "options": ["91/36", "11/4", "3", "5/2"], "answer": 0, "explanation": "For each face, P(it appears at least once) = 1 − (5/6)³ = 91/216. By linearity of expectation, E = 6 × 91/216 = 91/36 ≈ 2.53. 3 ignores repeats.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-37", "question": "How many 5-digit numbers divisible by 4 can be formed using each of the digits 1, 2, 3, 4, 5 exactly once?", "options": ["48", "24", "20", "30"], "answer": 1, "explanation": "The last two digits must form a multiple of 4: 12, 24, 32 or 52 (4 options). The other 3 digits fill the first places in 3! = 6 ways: 4 × 6 = 24.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-38", "question": "In how many arrangements of the letters of SUCCESS do all three S's come together?", "options": ["30", "420", "120", "60"], "answer": 3, "explanation": "Glue SSS into one block. Units: SSS, U, C, C, E — 5 units with C twice: 5!/2! = 60. 420 = 7!/(3! 2!) is the count with no restriction.", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-39", "question": "10 identical balls are placed in 4 different boxes so that no box is empty. How many ways are there?", "options": ["210", "120", "84", "286"], "answer": 2, "explanation": "Give one ball to each box first, then distribute the remaining 6 freely: (6 + 3)C3 = 9C3 = 84. 286 = 13C3 allows empty boxes.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "apt-pnc-probability-40", "question": "A three-digit number (100 to 999) is chosen at random. What is the probability that all its digits are different?", "options": ["18/25", "3/4", "81/100", "4/5"], "answer": 0, "explanation": "Favourable: 9 × 9 × 8 = 648 (first digit 1–9, second any of the other 9 digits including 0, third 8). Total 900. 648/900 = 18/25.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-41", "question": "Two cards are drawn together from a pack of 52. Given that both cards are red, what is the probability that both are hearts?", "options": ["1/2", "6/25", "1/4", "1/16"], "answer": 1, "explanation": "Given both red, the pair is one of 26C2 = 325 red pairs; both hearts in 13C2 = 78 of them. 78/325 = 6/25. 1/4 = (1/2)(1/2) ignores that the second card is drawn without replacement.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-42", "question": "In how many ways can two squares be chosen on an 8 × 8 chessboard so that they are not in the same row and not in the same column?", "options": ["1764", "1568", "2016", "3136"], "answer": 1, "explanation": "First square: 64 choices; second: 64 − 15 = 49 squares outside its row and column; the pair is unordered: 64 × 49/2 = 1568. 3136 forgets to divide by 2.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-43", "question": "5 men and 5 women are to sit around a round table so that men and women alternate. How many seating arrangements are there?", "options": ["2880", "14400", "1440", "28800"], "answer": 0, "explanation": "Seat the men first: (5 − 1)! = 24 (circular). The 5 gaps between them are now fixed positions, so the women go in 5! = 120 ways. 24 × 120 = 2880. 14400 = 5! × 5! treats the men's circle as a row.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-44", "question": "5 men and 5 women sit around a round table with men and women alternating. In how many of these arrangements is a particular woman, Riya, NOT next to her brother Karan (one of the men)?", "options": ["2160", "2304", "1728", "1152"], "answer": 2, "explanation": "Total alternate arrangements = 4! × 5! = 2880. Once the men are seated, Riya can take any of the 5 gaps and exactly 2 of them touch Karan, so she avoids him in 3/5 of the cases: (3/5) × 2880 = 1728. 1152 is the count where they ARE together.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-45", "question": "How many arrangements of the letters of ENGINEERING have no two E's next to each other?", "options": ["277200", "1680", "141120", "120960"], "answer": 2, "explanation": "Arrange the other 8 letters (N×3, G×2, I×2, R): 8!/(3! 2! 2!) = 1680. They leave 9 gaps; choose 3 for the identical E's: 9C3 = 84. 1680 × 84 = 141120. 277200 is the total with no restriction.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-46", "question": "Six candidates leave their ID cards at a desk and each later picks up a card at random. What is the probability that nobody gets their own card?", "options": ["11/30", "53/144", "5/6", "1/e"], "answer": 1, "explanation": "Derangements of 6: D₆ = 265, out of 6! = 720 permutations: 265/720 = 53/144 ≈ 0.368. 1/e ≈ 0.3679 is only the limit as the number of people grows, not the exact value; 11/30 = 44/120 is the answer for 5 people.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-47", "question": "6 different tasks are shared among 3 interns, Ira, Jay and Kabir, so that every intern gets at least one task and Ira gets exactly 2. In how many ways can this be done?", "options": ["150", "240", "540", "210"], "answer": 3, "explanation": "Choose Ira's 2 tasks: 6C2 = 15. The other 4 tasks go to Jay and Kabir with neither left idle: 2⁴ − 2 = 14. 15 × 14 = 210. 240 = 15 × 16 forgets to remove the cases where Jay or Kabir gets nothing.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-48", "question": "7 different books are packed into 3 identical bags so that no bag is empty. In how many ways can this be done?", "options": ["35", "301", "1806", "210"], "answer": 1, "explanation": "With identical bags we only split the 7 books into 3 non-empty groups: the Stirling number S(7,3) = (3⁷ − 3 × 2⁷ + 3)/3! = (2187 − 384 + 3)/6 = 301. 1806 = 301 × 3! would be the answer for 3 different bags.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id": "apt-pnc-probability-49", "question": "There are 4 closed doors and a prize is behind one. You pick a door. The host, who knows where the prize is, opens one of the other doors that has no prize. You then switch to one of the two remaining unopened doors, chosen at random. What is your probability of winning?", "options": ["3/8", "1/4", "3/4", "1/2"], "answer": 0, "explanation": "Your first pick is wrong with probability 3/4; then the prize is behind one of the 2 doors you can switch to, and you pick it with probability 1/2: (3/4)(1/2) = 3/8. If your first pick was right (1/4), switching always loses. 3/8 still beats the 1/4 of staying.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-50", "question": "A screening test detects a disease in 99% of people who have it, but also wrongly shows positive for 2% of healthy people. 1% of the population has the disease. A person tests positive. What is the probability that the person has the disease?", "options": ["99/100", "1/2", "49/50", "1/3"], "answer": 3, "explanation": "P(+) = 0.01 × 0.99 + 0.99 × 0.02 = 0.0099 + 0.0198 = 0.0297. P(disease | +) = 0.0099/0.0297 = 1/3. 99% is P(+ | disease), the classic reversal trap.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-51", "question": "Four people are chosen at random. Assuming each is equally likely to be born on any day of the week, what is the probability that all four were born on different days of the week?", "options": ["1/7", "4/7", "35/2401", "120/343"], "answer": 3, "explanation": "Favourable = 7 × 6 × 5 × 4 = 840 out of 7⁴ = 2401: 840/2401 = 120/343 ≈ 0.35. 35/2401 = 7C4/7⁴ forgets that the four people are different (order matters).", "difficulty": "moderate", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-52", "question": "How many three-digit numbers have digits that add up to 10?", "options": ["55", "54", "45", "63"], "answer": 1, "explanation": "Write the number as abc with a ≥ 1: put a = a′ + 1 so a′ + b + c = 9, giving 11C2 = 55 non-negative solutions. Remove the one with a′ = 9 (that is a = 10, not a digit): 55 − 1 = 54. 55 is the trap of forgetting that cap.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-53", "question": "How many integers from 1 to 500 are divisible by 3 or by 7, but not by both?", "options": ["237", "214", "166", "191"], "answer": 3, "explanation": "Multiples of 3: 166; of 7: 71; of 21 (both): 23. 'Either but not both' = 166 + 71 − 2 × 23 = 191. 214 = 166 + 71 − 23 is 'at least one', which still includes the 23 numbers divisible by both.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-54", "question": "10 chairs are arranged in a circle. In how many ways can 3 chairs be chosen so that no two chosen chairs are next to each other?", "options": ["70", "56", "50", "120"], "answer": 2, "explanation": "In a row of 10 chairs the count is (10 − 3 + 1)C3 = 8C3 = 56. In a circle, chairs 1 and 10 are also neighbours; the row selections using both ends are those with chair 1, chair 10 and one chair from 3 to 8 not touching them: 6 such. 56 − 6 = 50. 56 is the row answer.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-55", "question": "Two cards are drawn without replacement from five cards numbered 1 to 5. What is the expected value of the larger number drawn?", "options": ["3", "4", "7/2", "9/2"], "answer": 1, "explanation": "There are 10 pairs, and the larger number is k in (k − 1) of them: E = (2×1 + 3×2 + 4×3 + 5×4)/10 = 40/10 = 4. 3 is the average of a single card.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-56", "question": "Two fair dice are thrown. Given that the sum is odd, what is the probability that the sum is a prime number?", "options": ["7/9", "2/3", "7/18", "5/12"], "answer": 0, "explanation": "Odd sums 3, 5, 7, 9, 11 occur 2 + 4 + 6 + 4 + 2 = 18 times. Prime among them (3, 5, 7, 11): 2 + 4 + 6 + 2 = 14. 14/18 = 7/9. 7/18 divides by 36 instead of 18; 5/12 = 15/36 is P(prime) without the condition.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-57", "question": "A and B take turns throwing a pair of dice, A first. A wins if A throws a total of 7 before B throws a total of 6; B wins if B throws a total of 6 first. What is the probability that A wins?", "options": ["30/61", "6/11", "36/61", "1/2"], "answer": 2, "explanation": "P(7) = 6/36 = 1/6 and P(6) = 5/36. A round passes with no winner with probability (5/6)(31/36) = 155/216. P(A wins) = (1/6)/(1 − 155/216) = (1/6)(216/61) = 36/61. 30/61 is B's chance, and 6/11 belongs to a game where both need the same 1/6 event.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-58", "question": "How many squares of all sizes are there in a 6 × 4 grid of unit squares?", "options": ["64", "40", "24", "50"], "answer": 3, "explanation": "k × k squares: (7 − k)(5 − k) for k = 1 to 4: 24 + 15 + 8 + 3 = 50. 24 counts only the unit squares.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-59", "question": "4 married couples stand in a row. In how many arrangements does no husband stand next to his own wife?", "options": ["13824", "40320", "384", "16128"], "answer": 0, "explanation": "Inclusion–exclusion over couples kept together: 8! − 4C1·2·7! + 4C2·2²·6! − 4C3·2³·5! + 4C4·2⁴·4! = 40320 − 40320 + 17280 − 3840 + 384 = 13824. 384 = 4! × 2⁴ is the count where every couple IS together.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-60", "question": "A password has 4 letters from A–Z (letters may repeat). How many passwords have at least one letter repeated?", "options": ["97500", "358800", "456976", "98176"], "answer": 3, "explanation": "All passwords: 26⁴ = 456976. All letters different: 26 × 25 × 24 × 23 = 358800. At least one repeat = 456976 − 358800 = 98176.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-61", "question": "A committee of 5 is chosen from 6 men and 5 women. It must have at least 2 women, and a particular man, Mohan, and a particular woman, Wasima, refuse to serve together. How many committees are possible?", "options": ["307", "381", "233", "74"], "answer": 0, "explanation": "Committees with at least 2 women: 11C5 − 6C5 − 6C4·5C1 = 462 − 6 − 75 = 381. With both Mohan and Wasima: pick 3 more from 5 men and 4 women with at least 1 more woman: 9C3 − 5C3 = 84 − 10 = 74. Answer 381 − 74 = 307.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id":"apt-pnc-probability-62","question":"In how many ways can exactly ₹10 be paid using any number of ₹1, ₹2 and ₹5 coins (the order of coins does not matter)?","options":["9","10","6","128"],"answer":1,"explanation":"Solve a + 2b + 5c = 10. c = 0: b = 0 to 5 (6 ways); c = 1: a + 2b = 5, b = 0 to 2 (3 ways); c = 2: 1 way. Total 10. Forgetting the two-₹5 way gives 9, using only ₹1 and ₹2 coins gives 6, and counting ordered sequences of coins gives 128.","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-63", "question": "Three cards are drawn together from a pack of 52. What is the probability that they are of three different suits?", "options": ["13/34", "39/50", "169/425", "1/4"], "answer": 2, "explanation": "Choose the 3 suits: 4C3 = 4; one card from each: 13³ = 2197. Favourable = 8788; total 52C3 = 22100. 8788/22100 = 169/425 ≈ 0.40.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-64", "question": "A bag has 5 red and 3 green balls. Balls are drawn one at a time without replacement until a green ball appears. What is the probability that exactly 3 draws are needed?", "options": ["5/28", "45/512", "5/14", "15/56"], "answer": 0, "explanation": "The first two must be red and the third green: (5/8) × (4/7) × (3/6) = 60/336 = 5/28. 45/512 = (5/8)²(3/8) wrongly puts the balls back.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-65", "question": "Urn 1 has 2 white and 3 black balls; urn 2 has 3 white and 2 black balls. One ball is moved at random from urn 1 to urn 2, and then a ball is drawn from urn 2. What is the probability that it is white?", "options": ["1/2", "3/5", "8/15", "17/30"], "answer": 3, "explanation": "Moved ball white (2/5): urn 2 has 4 white of 6 → 4/6. Moved ball black (3/5): 3 white of 6 → 3/6. P = (2/5)(4/6) + (3/5)(3/6) = 8/30 + 9/30 = 17/30.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-66", "question": "3 boys and 3 girls stand in a row with boys and girls alternating. In how many of these arrangements does a particular boy, Rohit, stand next to a particular girl, Sana?", "options": ["20", "32", "40", "72"], "answer": 2, "explanation": "Pattern BGBGBG: the (boy slot, girl slot) neighbouring pairs are (1,2), (3,2), (3,4), (5,4), (5,6) — 5 ways to put Rohit and Sana side by side, and 2! × 2! = 4 for the rest: 20. The pattern GBGBGB gives another 20. Total 40 out of 72.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-67", "question": "How many 6-digit numbers have digits that are strictly decreasing from left to right (for example 976410)?", "options": ["120", "720", "210", "84"], "answer": 2, "explanation": "Any 6 different digits from 0–9 can be written in decreasing order in exactly one way, and 0 can only come last, so the number never starts with 0: 10C6 = 210. 84 = 9C6 wrongly leaves out 0.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "apt-pnc-probability-68", "question": "How many of the positive divisors of 540 are multiples of 6?", "options": ["16", "8", "12", "6"], "answer": 2, "explanation": "A divisor of 540 that is a multiple of 6 is 6 × k where k divides 540/6 = 90 = 2 × 3² × 5. 90 has 2 × 3 × 2 = 12 divisors, so there are 12 such divisors. 16 is the number of even divisors, which includes 2, 4, 10, … that are not multiples of 3.", "difficulty": "moderate", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-69", "question": "A divisor of 360 is chosen at random. What is the probability that it is a perfect square?", "options": ["1/6", "1/8", "1/4", "1/12"], "answer": 0, "explanation": "360 = 2³ × 3² × 5 has 24 divisors. Square divisors use even powers only: 2⁰ or 2², 3⁰ or 3², 5⁰ → 2 × 2 × 1 = 4 (1, 4, 9, 36). 4/24 = 1/6.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-70", "question": "A fair coin is tossed until two heads come up in a row. What is the expected number of tosses?", "options": ["8", "4", "3", "6"], "answer": 3, "explanation": "Let E be the expected tosses from the start and E₁ the expected further tosses just after a head. E = 1 + ½E₁ + ½E and E₁ = 1 + ½(0) + ½E. Then E₁ = 1 + E/2 and E = 2 + E₁ = 3 + E/2, so E = 6. 4 is the trap of treating 'HH' as one event of probability 1/4.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-71", "question": "8 people sit around a round table. Two of them, Anil and Bina, must sit exactly opposite each other. How many arrangements are possible?", "options": ["360", "720", "1440", "5040"], "answer": 1, "explanation": "Seat Anil anywhere (this removes rotations); Bina's seat is then forced (the one opposite). The other 6 people fill 6 seats in 6! = 720 ways. 1440 wrongly doubles for 'Anil and Bina can swap', which is only a rotation of the same arrangement.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id":"apt-pnc-probability-72","question":"How many of the following statements are correct?\n(i) 5 different keys can be put on a key ring in 24 ways.\n(ii) 10C3 = 10C7.\n(iii) The letters of LEVEL can be arranged in 60 ways.\n(iv) The probability of a doublet (same number on both) when two dice are thrown is 1/36.","options":["Only one","Only two","Only three","All four"],"answer":0,"explanation":"Only (ii) is true, since nCr = nC(n − r). (i) is false: a ring can be flipped, so (5 − 1)!/2 = 12, not 24. (iii) is false: L and E both repeat, so 5!/(2! 2!) = 30, not 60. (iv) is false: there are 6 doublets, so 6/36 = 1/6.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "apt-pnc-probability-73", "question": "How many of the following statements are correct?\n(i) If A and B are independent with P(A) = 0.5 and P(B) = 0.4, then P(A or B) = 0.7.\n(ii) Two mutually exclusive events, each with non-zero probability, are always independent.\n(iii) If P(A) = P(B) > 0, then P(A | B) = P(B | A).\n(iv) When 3 coins are tossed, P(exactly one head) = 1/2.", "options": ["Only three", "Only two", "Only one", "All four"], "answer": 1, "explanation": "(i) True: 0.5 + 0.4 − 0.5 × 0.4 = 0.7. (ii) False: P(A and B) = 0 but P(A)P(B) > 0, so they are dependent. (iii) True: both equal P(A and B)/P(A). (iv) False: it is 3/8. Two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "apt-pnc-probability-74", "question": "There are 8 chairs in a row. In how many ways can 3 different people sit so that no two of them are in neighbouring chairs?", "options": ["336", "60", "120", "20"], "answer": 2, "explanation": "Choose 3 chairs with no two adjacent: (8 − 3 + 1)C3 = 6C3 = 20; the 3 people can be arranged in them in 3! = 6 ways: 20 × 6 = 120. 20 forgets that the people are different.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "apt-pnc-probability-75", "question": "12 identical apples are shared among 4 children so that each child gets at least 1 and at most 5 apples. In how many ways can this be done?", "options": ["81", "125", "165", "85"], "answer": 3, "explanation": "Give 1 to each: y₁ + … + y₄ = 8 with 0 ≤ yᵢ ≤ 4. Without the cap: 11C3 = 165. Remove the cases where some yᵢ ≥ 5: 4 × 6C3 = 80 (two children cannot both exceed 4). 165 − 80 = 85.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"apt-pnc-probability-76","question":"In how many different ways can the letters of the word APPLE be arranged?","options":["120","60","24","30"],"answer":1,"explanation":"5 letters with P repeated twice: 5!/2! = 60. 120 treats the two P’s as different letters.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-77","question":"Two fair dice are thrown. What is the probability that the sum of the numbers shown is exactly 7?","options":["7/36","1/12","1/6","5/36"],"answer":2,"explanation":"Favourable pairs: (1,6), (2,5), (3,4), (4,3), (5,2), (6,1) = 6 of 36, i.e. 1/6. 1/12 counts only unordered pairs (3 of 36); 5/36 is for a sum of 6 or 8.","difficulty":"easy","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-78","question":"A club of 10 members must elect a President and a Vice-President, and one person cannot hold both posts. In how many ways can this be done?","options":["45","100","20","90"],"answer":3,"explanation":"The posts are different, so order matters: 10 × 9 = 90. 45 = C(10, 2) treats the two posts as identical; 100 allows one person to hold both.","difficulty":"easy","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-79","question":"Two fair coins are tossed together. What is the probability of getting at least one head?","options":["3/4","1/2","1/4","2/3"],"answer":0,"explanation":"P(at least one head) = 1 − P(no head) = 1 − 1/4 = 3/4. 2/3 comes from treating HH, HT/TH and TT as three equally likely cases, which they are not.","difficulty":"easy","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-80","question":"How many three-digit numbers can be formed in which every digit is odd and no digit repeats?","options":["125","60","100","48"],"answer":1,"explanation":"Odd digits are 1, 3, 5, 7, 9 (none is 0, so the first place is unrestricted): 5 × 4 × 3 = 60. 125 = 5³ allows repetition.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-81","question":"In how many arrangements of the letters of the word LETTER do the two T’s come together?","options":["120","180","60","30"],"answer":2,"explanation":"Glue TT into one block: units L, E, E, R, [TT] = 5 units with E repeated, so 5!/2! = 60. 120 forgets that the two E’s are identical; 180 = 6!/(2! 2!) is the count with no condition at all.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-82","question":"A committee of 3 is to be chosen from 6 men and 4 women so that it has at least one woman. In how many ways can this be done?","options":["120","144","84","100"],"answer":3,"explanation":"Complement: all choices C(10, 3) = 120 minus all-men C(6, 3) = 20 gives 100. 144 = 4 × C(9, 2) “picks one woman first, then any two”, which counts a committee with two women twice; 120 ignores the condition.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-83","question":"One card is drawn at random from a standard pack of 52. What is the probability that it is a king or a heart?","options":["4/13","17/52","1/4","1/52"],"answer":0,"explanation":"P(K) + P(heart) − P(king of hearts) = 4/52 + 13/52 − 1/52 = 16/52 = 4/13. 17/52 counts the king of hearts twice; 1/52 is the “and” case.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-84","question":"A fair die is rolled twice. What is the probability that the second number is strictly greater than the first?","options":["1/2","5/12","7/12","1/3"],"answer":1,"explanation":"Of 36 outcomes, 6 are ties; the remaining 30 split equally between “second greater” and “first greater”: 15/36 = 5/12. 1/2 forgets the ties; 7/12 is “second greater or equal”.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-85","question":"In how many ways can 5 different rings be worn on the 4 fingers of one hand (any number of rings on a finger; the order of rings on the same finger is ignored)?","options":["625","20","1024","120"],"answer":2,"explanation":"Each ring independently chooses one of 4 fingers: 4⁵ = 1024. 625 = 5⁴ reverses the roles, letting each finger choose a ring.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-86","question":"A 3-digit PIN is made from the digits 0–9, and digits may repeat (000 is allowed). If a PIN is chosen at random, what is the probability that all three digits are different?","options":["3/10","81/100","7/10","18/25"],"answer":3,"explanation":"Distinct PINs = 10 × 9 × 8 = 720 out of 10³ = 1000, i.e. 18/25. 81/100 checks only that the second digit differs from the first.","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-87","question":"Two fair dice are thrown. Given that at least one die shows a 6, what is the probability that the sum is 10 or more?","options":["5/11","1/6","5/36","1/2"],"answer":0,"explanation":"At least one 6: 11 outcomes. Among them, sum ≥ 10: (6,4), (4,6), (6,5), (5,6), (6,6) = 5. So 5/11. 1/6 is the unconditional P(sum ≥ 10) and 5/36 is the joint probability, not divided by P(condition) = 11/36.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-88","question":"Box A has 3 red and 2 blue balls; box B has 1 red and 4 blue balls. A fair coin decides which box to draw from, and one ball is drawn. It is red. What is the probability that it came from box A?","options":["3/5","3/4","1/2","2/3"],"answer":1,"explanation":"Bayes: P(A and red) = 1/2 × 3/5 = 3/10, P(B and red) = 1/2 × 1/5 = 1/10. P(A | red) = (3/10)/(4/10) = 3/4. 3/5 is P(red | A), the reverse conditional.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-89","question":"In how many arrangements of the letters of the word ARRANGE are the two R’s NOT next to each other?","options":["1260","360","900","1080"],"answer":2,"explanation":"Total = 7!/(2! 2!) = 1260 (A and R each twice). With RR glued: 6 units with A twice = 6!/2! = 360. Apart = 1260 − 360 = 900. 1080 subtracts 180, forgetting that the RR block is a single unit among 6.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-90","question":"In how many ways can 5 different balls be put into 3 different boxes so that no box is empty?","options":["243","60","90","150"],"answer":3,"explanation":"Inclusion–exclusion: 3⁵ − 3 × 2⁵ + 3 × 1⁵ = 243 − 96 + 3 = 150. 243 allows empty boxes; 90 uses only the (3,1,1) split and misses the (2,2,1) split (60 + 90 = 150).","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-91","question":"How many four-digit numbers (1000 to 9999) have at least one digit repeated?","options":["4464","4536","5040","3024"],"answer":0,"explanation":"All-distinct four-digit numbers: 9 × 9 × 8 × 7 = 4536. Total 9000, so at least one repeat = 9000 − 4536 = 4464. 4536 is the complement itself; 5040 = 10 × 9 × 8 × 7 wrongly allows a leading 0.","difficulty":"moderate","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-92","question":"Four cards are drawn together from a standard pack of 52. What is the probability that they belong to four different suits?","options":["1/4","2197/20825","13/20825","3/32"],"answer":1,"explanation":"Choose one card from each suit: 13⁴ = 28,561 ways out of C(52, 4) = 2,70,725. Simplifying by 13: 2197/20825 (about 0.105). 3/32 is the “with replacement” value 4!/4⁴ applied to suits, which ignores that drawing removes cards.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-93","question":"A team of 11 is chosen from 7 batsmen and 5 bowlers, and it must include at least 4 bowlers. In how many ways can it be chosen?","options":["5","35","12","7"],"answer":2,"explanation":"Only 12 players exist, so the team leaves out exactly one. 4 bowlers + 7 batsmen: C(5, 4) × C(7, 7) = 5; 5 bowlers + 6 batsmen: C(5, 5) × C(7, 6) = 7. Total 12. 5 and 7 are each one case alone.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-94","question":"How many rectangles on an 8 × 8 chessboard (formed by its grid lines) are NOT squares?","options":["1296","204","1092","1080"],"answer":2,"explanation":"All rectangles: choose 2 of 9 vertical and 2 of 9 horizontal lines, C(9, 2)² = 36² = 1296. Squares: 1² + 2² + … + 8² = 204. Non-squares = 1296 − 204 = 1092.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-95","question":"A, B and C take turns to throw a fair die in that order (A, B, C, A, B, C, …). The first person to throw a 6 wins. What is the probability that C wins?","options":["1/3","25/216","30/91","25/91"],"answer":3,"explanation":"Each full round has no six with probability (5/6)³ = 125/216. C wins in round 1 with (5/6)²(1/6) = 25/216, and the game restarts otherwise: P = (25/216)/(1 − 125/216) = 25/91. 25/216 is only the first round; 30/91 is B’s chance; 1/3 ignores the order advantage.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-96","question":"A family has three children. Given that the eldest child is a girl, what is the probability that the family has at least two girls? (Boys and girls are equally likely and independent.)","options":["3/4","1/2","4/7","1/4"],"answer":0,"explanation":"Fixing the eldest as a girl leaves 4 equally likely cases for the other two (BB, BG, GB, GG). At least one more girl in 3 of them: 3/4. 4/7 is the answer to the different condition “at least one child is a girl”.","difficulty":"moderate","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-97","question":"In how many ways can 3 red, 3 blue and 1 green flag be arranged in a row so that no two red flags are next to each other? (Flags of the same colour are identical.)","options":["140","40","10","24"],"answer":1,"explanation":"Arrange the 4 non-red flags first: 4!/3! = 4 ways (B, B, B, G). They create 5 gaps, and the 3 red flags go into 3 different gaps: C(5, 3) = 10. Total 4 × 10 = 40. 140 = 7!/(3! 3!) is the count with no restriction.","difficulty":"moderate","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-98","question":"Ten tickets are numbered 1 to 10. Three are drawn together at random. What is the probability that the smallest number drawn is 3?","options":["1/10","3/10","7/40","21/40"],"answer":2,"explanation":"Ticket 3 must be drawn, and the other two must come from 4–10 (7 tickets): C(7, 2) = 21. Total C(10, 3) = 120, so 21/120 = 7/40. 3/10 is just P(3 is drawn).","difficulty":"moderate","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-99","question":"Six people A, B, C, D, E and F stand in a row. C must stand at one of the two ends, and A and B must not stand next to each other. How many arrangements are possible?","options":["240","96","192","144"],"answer":3,"explanation":"With C at an end: 2 × 5! = 240. Among these, A and B together: 2 (end for C) × 4! (AB block + 3 others) × 2 (AB or BA) = 96. Required = 240 − 96 = 144. 96 is the forbidden count itself.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-100","question":"How many solutions in non-negative integers does x + y + z = 10 have, if none of x, y, z may exceed 5?","options":["21","66","36","18"],"answer":0,"explanation":"Without the cap: C(12, 2) = 66. If x ≥ 6, set x = 6 + x′: x′ + y + z = 4 gives C(6, 2) = 15; same for y and z. Two variables cannot both be ≥ 6. Answer = 66 − 45 = 21. 66 ignores the cap; 36 subtracts only 30.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-101","question":"A bag has 6 red and 3 green balls. Balls are drawn one at a time without replacement until the first green ball appears. What is the expected number of draws?","options":["3","2.5","2","10/3"],"answer":1,"explanation":"The 3 green balls split the 6 red ones into 4 gaps, each holding 6/4 = 1.5 red balls on average. So the first green comes after 1.5 reds on average: 1.5 + 1 = 2.5 draws. 3 is 9/3, the “with replacement” style guess; 2 ignores the green draw itself.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-102","question":"Three fair dice are rolled. What is the probability that the sum of the three numbers is exactly 10?","options":["1/6","5/72","1/8","25/216"],"answer":2,"explanation":"Count ordered triples with sum 10: solutions of a + b + c = 10 with 1 ≤ each ≤ 6 = C(9, 2) − 3 × C(3, 2) = 36 − 9 = 27. P = 27/216 = 1/8. 25/216 is the count for a sum of 9.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-103","question":"From 5 married couples, 4 people are to be chosen so that no husband–wife pair is included. In how many ways can this be done?","options":["210","5","130","80"],"answer":3,"explanation":"Choose 4 of the 5 couples, C(5, 4) = 5, then one person from each chosen couple: 2⁴ = 16. Total 80. 210 = C(10, 4) ignores the condition; 130 = 210 − 80 is the count WITH at least one couple.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-104","question":"In how many arrangements of the letters of the word INFOSYS does the word begin with a vowel and the two S’s are not next to each other?","options":["480","720","240","600"],"answer":0,"explanation":"Begin with I or O: 2 choices, then the other 6 letters (S twice) in 6!/2! = 360 ways → 720. With SS together, the 6 letters become 5 units: 5! = 120 per vowel → 240. Required = 720 − 240 = 480.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-105","question":"You walk from (0, 0) to (4, 4) on a grid, one unit east or north at a time. The junctions (1, 1) and (3, 3) are closed. How many shortest routes avoid both closed junctions?","options":["30","14","38","46"],"answer":1,"explanation":"Total C(8, 4) = 70. Through (1, 1): 2 × C(6, 3) = 40. Through (3, 3): C(6, 3) × 2 = 40. Through both: 2 × C(4, 2) × 2 = 24. Avoiding both = 70 − 40 − 40 + 24 = 14. 30 avoids only one closed junction; 46 = 70 − 24 removes only the routes through both. Without adding back the 24, the count would even go negative.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-106","question":"A fair die is rolled repeatedly until a 6 appears. What is the probability that the first 6 appears on an odd-numbered roll (1st, 3rd, 5th, …)?","options":["1/2","5/11","6/11","1/6"],"answer":2,"explanation":"P(odd) = (1/6)[1 + (5/6)² + (5/6)⁴ + …] = (1/6)/(1 − 25/36) = (1/6)(36/11) = 6/11. 1/2 assumes symmetry, but the odd rolls come first and are favoured; 5/11 is the even case.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-107","question":"How many triangles can be formed using the vertices of a regular 12-sided polygon so that no side of the triangle is a side of the polygon?","options":["220","100","120","112"],"answer":3,"explanation":"All triangles C(12, 3) = 220. With exactly one polygon side: 12 sides × (12 − 4) third vertices = 96. With two polygon sides (three consecutive vertices): 12. Answer = 220 − 96 − 12 = 112 = n(n − 4)(n − 5)/6. 100 subtracts 12 × 10, counting the two-side triangles twice.","difficulty":"hard","source":"Product-company OA pattern"},
  {"id":"apt-pnc-probability-108","question":"In how many ways can three different numbers be chosen from 1, 2, …, 30 so that they form an arithmetic progression (order of choosing does not matter)?","options":["210","420","196","406"],"answer":0,"explanation":"Write the triple as a, a + d, a + 2d with d ≥ 1. For each d, a runs from 1 to 30 − 2d, giving 30 − 2d triples; d goes 1 to 14. Sum = 14 × 30 − 2(1 + … + 14) = 420 − 210 = 210. 420 counts each triple in both increasing and decreasing order.","difficulty":"hard","source":"Wipro NLTH · Cognizant pattern"},
  {"id":"apt-pnc-probability-109","question":"12 identical pens are given to 3 students so that each student gets at least 2 and at most 6 pens. In how many ways can this be done?","options":["28","19","91","10"],"answer":1,"explanation":"Give 2 each first; then x + y + z = 6 with each ≤ 4. Unrestricted: C(8, 2) = 28. If one gets ≥ 5 more: x′ + y + z = 1 gives 3 ways, × 3 students = 9. Answer 28 − 9 = 19. 28 ignores the upper limit.","difficulty":"hard","source":"Infosys · Capgemini pattern"},
  {"id":"apt-pnc-probability-110","question":"In a 4-option MCQ test, a student knows the answer to 60% of the questions and guesses at random on the rest. Given that a question was answered correctly, what is the probability that the student actually knew the answer?","options":["3/5","7/10","6/7","4/5"],"answer":2,"explanation":"P(correct) = 0.6 × 1 + 0.4 × 1/4 = 0.7. P(knew | correct) = 0.6/0.7 = 6/7. 3/5 is the prior P(knew); 7/10 is P(correct), not the conditional.","difficulty":"hard","source":"TCS NQT · Accenture pattern"},
  {"id":"apt-pnc-probability-111","question":"In how many arrangements of the numbers 1, 2, 3, 4, 5, 6, 7 in a row does no number k appear immediately before k + 1? (For example, '3 4' side by side in that order is not allowed, but '4 3' is.)","options":["2119","1854","1625","2520"],"answer":0,"explanation":"Inclusion–exclusion on the 6 forbidden adjacencies 12, 23, …, 67. Forcing any k of them glues numbers into blocks, leaving 7 − k objects, so the count is Σ (−1)ᵏ C(6, k)(7 − k)! = 5040 − 4320 + 1800 − 480 + 90 − 12 + 1 = 2119. 1854 is the number of derangements of 7 (nobody in their own place), a different restriction.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-112","question":"Seven tiles — two red, two blue, two green and one yellow, identical apart from colour — are laid in a row. In how many distinguishable rows are no two tiles of the same colour next to each other?","options":["270","246","222","384"],"answer":1,"explanation":"Total rows: 7!/(2!·2!·2!) = 630. Glue one same-colour pair: 6!/(2!·2!) = 180, for 3 colours: 540. Glue two pairs: 5!/2! = 60, for 3 choices: 180. Glue all three: 4! = 24. No adjacent pair: 630 − 540 + 180 − 24 = 246. 270 = 630 − 540 + 180 stops before the last correction; 222 adds the 24 to the wrong side.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-113","question":"Six desks numbered 1 to 6 stand in a circle, and student i normally sits at desk i. After a break the six students sit down again, one per desk, so that nobody sits at their own desk or at the next desk clockwise (desk i + 1, with desk 1 following desk 6). How many seatings are possible?","options":["265","96","80","120"],"answer":2,"explanation":"The 12 forbidden (student, desk) pairs form a single cycle in which neighbouring pairs clash (share a student or a desk). The number of ways to choose k non-clashing forbidden pairs from a 12-cycle is 12/(12 − k) × C(12 − k, k): 1, 12, 54, 112, 105, 36, 2. Inclusion–exclusion: 720 − 12·120 + 54·24 − 112·6 + 105·2 − 36·1 + 2·1 = 80. 265 is the derangement count, which only bans the own desk.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-114","question":"In how many ways can 20 identical chocolates be shared among 4 children so that every child gets at least 1 and at most 8 chocolates?","options":["969","303","321","315"],"answer":3,"explanation":"Give each child 1 first: now share 16 with each child getting 0 to 7 more. Without the cap: C(19, 3) = 969. Subtract the cases with some child getting ≥ 8 more: 4 × C(11, 3) = 660. Add back two children with ≥ 8 each (16 exactly): 6 × C(3, 3) = 6. Answer 969 − 660 + 6 = 315. 303 subtracts the double-overflow cases instead of adding them back; 969 ignores the upper limit.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-115","question":"8 different balls are put into 3 different boxes A, B and C so that no box is empty and box A contains an even number of balls. In how many ways can this be done?","options":["2772","2898","3024","2716"],"answer":0,"explanation":"Choose A's balls (k = 2, 4 or 6; k = 0 would leave A empty and k = 8 would empty B and C), then put the remaining 8 − k into B and C with neither empty: 2^(8 − k) − 2 ways. k = 2: 28 × 62 = 1736; k = 4: 70 × 14 = 980; k = 6: 28 × 2 = 56. Total 2772. All onto distributions number 3⁸ − 3·2⁸ + 3 = 5796, so 3024 is the odd case and 2898 the guess 'exactly half'. 2716 forgets k = 6.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-116","question":"In how many ways can 3 identical rooks be placed on a 6 × 6 chessboard so that no two are in the same row or column and no rook stands on the main diagonal (the squares (1,1), (2,2), …, (6,6))?","options":["2400","1420","1440","1200"],"answer":1,"explanation":"Without the diagonal rule: choose 3 rows and 3 columns and match them: C(6,3)² × 3! = 2400. Inclusion–exclusion over diagonal squares used: subtract 6 × C(5,2)² × 2! = 1200, add 15 × C(4,1)² × 1! = 240, subtract 20 × 1 = 20. 2400 − 1200 + 240 − 20 = 1420. 1200 stops after one subtraction; 1440 stops before the last correction.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-117","question":"A box has three coins: a fair coin, a double-headed coin, and a biased coin that shows heads with probability 1/4. A coin is picked at random and tossed three times, showing heads every time. If the same coin is tossed once more, what is the probability that it shows heads?","options":["64/73","7/12","273/292","9/10"],"answer":2,"explanation":"Posterior weights are proportional to 1/3 × P(HHH): fair 1/8, double-headed 1, biased 1/64, i.e. 8 : 64 : 1 out of 73. The next toss is heads with probability (8/73)(1/2) + (64/73)(1) + (1/73)(1/4) = (16 + 256 + 1)/292 = 273/292 ≈ 0.935. 64/73 is just the chance the coin is double-headed and ignores heads from the other two; 7/12 is the prior average that ignores the evidence.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-118","question":"Arun and Bela each arrive at a café at a random time, uniformly and independently, between 5:00 and 6:00 pm. If Arun arrives first he waits 15 minutes for Bela; if Bela arrives first she waits only 10 minutes for Arun. Each leaves when the wait is over (or at 6:00). What is the probability that they meet?","options":["7/16","11/36","5/12","107/288"],"answer":3,"explanation":"Plot Arun's time a and Bela's time b in a 60 × 60 square (area 3600). They miss each other if b − a > 15 (a triangle with legs 45, area 1012.5) or a − b > 10 (a triangle with legs 50, area 1250). So P(meet) = (3600 − 2262.5)/3600 = 1337.5/3600 = 107/288 ≈ 0.372. 7/16 is the answer if both waited 15 minutes; 11/36 if both waited 10 minutes.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-119","question":"Two numbers x and y are chosen independently and uniformly at random from the interval [0, 1]. What is the probability that x + y < 1 and xy < 2/9? (ln is the natural logarithm.)","options":["1/3 + (2/9) ln 2","1/6 − (2/9) ln 2","1/2 − (2/9) ln 2","1/3 + (1/9) ln 2"],"answer":0,"explanation":"The region x + y < 1 has area 1/2. Inside it, the hyperbola xy = 2/9 meets the line x + y = 1 where x(1 − x) = 2/9, i.e. x = 1/3 and x = 2/3. The part with xy ≥ 2/9 lies between them: ∫ from 1/3 to 2/3 of (1 − x − 2/(9x)) dx = [x − x²/2 − (2/9) ln x] = 1/3 − 1/6 − (2/9) ln 2 = 1/6 − (2/9) ln 2. So the probability is 1/2 − 1/6 + (2/9) ln 2 = 1/3 + (2/9) ln 2 ≈ 0.487. 1/6 − (2/9) ln 2 is the excluded piece, not the answer.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-120","question":"A 6-character code is made from the letters A, B, C and D (letters may repeat). How many codes contain each of A, B and C at least once? (D may or may not appear.)","options":["1560","2100","2160","1920"],"answer":1,"explanation":"Inclusion–exclusion over the letters that are missing among A, B, C: 4⁶ − 3·3⁶ + 3·2⁶ − 1⁶ = 4096 − 2187 + 192 − 1 = 2100. 1560 counts codes using all four letters (D forced too).","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-121","question":"Four married couples sit around a round table so that men and women alternate and nobody sits next to their own spouse. Seatings that differ only by a rotation are the same. How many seatings are possible?","options":["24","6","12","36"],"answer":2,"explanation":"Seat the men first: up to rotation there are 3! = 6 orders. Label the gaps between consecutive men g₁, …, g₄ (gᵢ between Mᵢ and Mᵢ₊₁). Wife Wᵢ may not use the two gaps beside her husband, so W₁ ∈ {g₂, g₃}, W₂ ∈ {g₃, g₄}, W₃ ∈ {g₄, g₁}, W₄ ∈ {g₁, g₂}. These choices form a cycle: once W₁ is placed everything else is forced, giving exactly 2 ways. Total 6 × 2 = 12. 24 counts the women's order as free (a 'reflection' that does not exist); 36 uses 3! × 3!.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-122","question":"A bag has 5 red and 3 blue balls. They are drawn one at a time without replacement until the bag is empty. What is the probability that at no stage have more blue balls than red balls been drawn?","options":["1/4","3/8","5/8","1/2"],"answer":3,"explanation":"This is the weak ballot problem: for a red and b blue (a ≥ b), the probability that blue never leads is (a + 1 − b)/(a + 1) = 3/6 = 1/2. (Reflection: a bad sequence first reaches 'blue ahead by 1'; reflecting the part before that turns it into a sequence of 6 blue and 2 red, so bad sequences number C(8, 2) = 28 out of C(8, 3) = 56.) 1/4 = (a − b)/(a + b) is the strict version, where red must stay strictly ahead all the time.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-123","question":"Six candidates with different skill levels are interviewed in a random order. After each interview the manager updates her 'best so far' if the current candidate is better than everyone seen earlier (the first candidate always counts as an update). What is the expected number of updates?","options":["2.45","3.5","2","2.28"],"answer":0,"explanation":"By linearity of expectation, add up the probabilities that the k-th candidate is the best of the first k. In a random order this probability is 1/k. Expected updates = 1 + 1/2 + 1/3 + 1/4 + 1/5 + 1/6 = 49/20 = 2.45. 3.5 is the average position, which has nothing to do with records; 2.28 forgets the first candidate's update (H₆ − 1 is 1.45).","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-124","question":"A fair coin is tossed repeatedly until the pattern T, H, H (tail, head, head on three consecutive tosses) first appears. What is the expected number of tosses?","options":["6","8","10","14"],"answer":1,"explanation":"Track the longest useful suffix: states ∅, T, TH. From ∅: H keeps you at ∅, T moves to T. From T: T stays at T, H moves to TH. From TH: H finishes, T goes back to T (never to ∅). Solving E∅ = 1 + ½E∅ + ½E_T, E_T = 1 + ½E_T + ½E_TH, E_TH = 1 + ½E_T gives E_T = 6 and E∅ = 8. (A pattern with no self-overlap of length 3 always takes 2³ = 8.) 10 is the value for HTH, which overlaps itself; 14 is for HHH.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-125","question":"A fair coin is tossed until either H, T, H or H, H, T appears as three consecutive tosses. What is the probability that H, T, H appears first?","options":["1/2","2/3","1/3","3/8"],"answer":2,"explanation":"Both patterns start with H, so wait for the first H. From there, if the next toss is H, we have HH, and HHT is now certain to win (further H's keep us at HH, and the first T completes HHT). If the next toss is T, we have HT: then H completes HTH, while T sends us back to the start (and we wait for an H again). With x = P(HTH wins | just saw H): x = ½·0 + ½(½·1 + ½·x), so x = 1/4 + x/4, x = 1/3. 1/2 assumes patterns of equal length are equally likely to come first.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-126","question":"Asha has ₹3 and Bharat has ₹5. They play rounds in which Asha wins ₹1 from Bharat with probability 2/3 and loses ₹1 to him with probability 1/3, until one of them has no money. What is the probability that Asha ends up with all ₹8?","options":["3/8","7/8","8/9","224/255"],"answer":3,"explanation":"Gambler's ruin with p = 2/3, q = 1/3 and r = q/p = 1/2: the chance of reaching 8 from 3 is (1 − r³)/(1 − r⁸) = (7/8)/(255/256) = 224/255 ≈ 0.878. 3/8 is the fair-game answer; 7/8 = 1 − r³ is the chance against an opponent with unlimited money, slightly below the true value since Bharat can also run out.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-127","question":"In how many ways can 4 numbers be chosen from 1, 2, …, 15 so that any two chosen numbers differ by at least 3?","options":["126","495","210","70"],"answer":0,"explanation":"Write the chosen numbers as a < b < c < d with gaps of at least 3. Subtract 0, 2, 4, 6 from them: a, b − 2, c − 4, d − 6 are strictly increasing numbers in 1 … 9, and every such choice comes from exactly one valid set. So the count is C(9, 4) = 126. 495 = C(12, 4) is the count for a minimum gap of 2 (non-consecutive numbers).","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-128","question":"A robot walks on a grid from (0, 0) to (6, 4), each step one unit east or one unit north. It is never allowed to be at a point where its y-coordinate exceeds its x-coordinate. How many routes are possible?","options":["210","90","84","120"],"answer":1,"explanation":"All routes: C(10, 4) = 210. A bad route first touches the line y = x + 1; reflecting the part before that touch in this line maps it to a route from (−1, 1) to (6, 4), i.e. 7 east and 3 north steps: C(10, 3) = 120 bad routes. Good routes: 210 − 120 = 90. 120 is the number of bad routes; 84 = C(9, 3) uses the wrong reflection point.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-129","question":"How many ordered pairs (a, b) of positive integers have lcm(a, b) = 720?","options":["68","105","135","225"],"answer":2,"explanation":"720 = 2⁴ × 3² × 5. For each prime with exponent e in 720, the exponents of that prime in a and b must have maximum exactly e: (e + 1)² − e² = 2e + 1 choices. So the count is (2·4 + 1)(2·2 + 1)(2·1 + 1) = 9 × 5 × 3 = 135. 68 is the number of unordered pairs ((135 + 1)/2); 225 = 15² counts all pairs of divisors.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-130","question":"6 different gifts are given to 4 children so that every child gets at least one gift and a particular child, Kavya, gets exactly two. In how many ways can this be done?","options":["360","1560","600","540"],"answer":3,"explanation":"Choose Kavya's two gifts: C(6, 2) = 15. The other 4 gifts go onto the other 3 children with nobody left out: 3⁴ − 3·2⁴ + 3 = 81 − 48 + 3 = 36. Total 15 × 36 = 540. 1560 is the count of all onto distributions with no condition on Kavya; 360 uses 4!/… = 24 (one gift each, as if only 3 gifts remained) instead of 36 for the second stage.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-131","question":"A standard pack of 52 cards is shuffled and cards are turned over one by one. What is the expected position of the first ace?","options":["10.6","13","9.6","12"],"answer":0,"explanation":"The 4 aces cut the 48 other cards into 5 gaps (before the first ace, between aces, after the last). By symmetry each gap has the same expected size, 48/5 = 9.6. The first ace comes right after the first gap, at expected position 9.6 + 1 = 10.6. 9.6 forgets to count the ace itself; 13 = 52/4 is the spacing argument applied to 4 gaps instead of 5.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-132","question":"2% of a population has a certain condition. A test detects it in 90% of people who have it and gives a false positive for 10% of people who do not. A person is tested twice (the results are independent given the person's true status) and both results are positive. What is the probability that the person has the condition?","options":["9/58","81/130","81/100","2/3"],"answer":1,"explanation":"P(two positives and condition) = 0.02 × 0.9² = 0.0162. P(two positives and no condition) = 0.98 × 0.1² = 0.0098. Bayes: 0.0162/(0.0162 + 0.0098) = 162/260 = 81/130 ≈ 62%. 9/58 ≈ 16% is the answer after a single positive test; 81/100 confuses P(two positives | condition) with the reverse.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-133","question":"Three fair dice are rolled. Given that the largest of the three numbers is exactly 5, what is the probability that their sum is at least 12?","options":["19/216","15/61","19/61","1/3"],"answer":2,"explanation":"Outcomes with maximum exactly 5: 5³ − 4³ = 61. Among them, sum ≥ 12: (5, 5, 5) — 1 ordering; (5, 5, x) with x = 2, 3, 4 — 3 orderings each, 9; (5, 4, 4) — 3; (5, 4, 3) — 6. Total 19, so the probability is 19/61. 19/216 forgets to condition (divides by all outcomes); 15/61 misses the (5, 5, 2) case.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-134","question":"Three identical red, three identical blue and three identical green balls are arranged in a row. In how many arrangements are no two balls of the same colour next to each other?","options":["168","216","180","174"],"answer":3,"explanation":"First arrange the 3 blue and 3 green balls (20 ways), then drop the 3 reds into 3 of the 7 gaps (including the ends), one red per gap. If the blue–green row has m equal neighbouring pairs, a red must go into each of those m gaps and the other 3 − m reds into any of the remaining 7 − m gaps: C(7 − m, 3 − m) ways. Rows with m = 0, 1, 2, 3, 4 equal pairs number 2, 4, 8, 4, 2 (m = 4 is BBBGGG or GGGBBB, which would need 4 reds). Total 2·C(7,3) + 4·C(6,2) + 8·C(5,1) + 4·C(4,0) = 70 + 60 + 40 + 4 = 174. 216 = 6³ ignores the identical balls.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-135","question":"Six beads are placed at equal spacing on a circular ring; each bead is black or white. Two rings are considered the same if one can be rotated into the other (flipping the ring over is not allowed). How many different rings are there?","options":["14","13","10","11"],"answer":0,"explanation":"Burnside's lemma: average the number of colourings fixed by each of the 6 rotations. Rotation by 0: 2⁶ = 64; by 1 or 5 positions: 2 each; by 2 or 4: 2² = 4 each; by 3: 2³ = 8. Average = (64 + 2 + 2 + 4 + 4 + 8)/6 = 84/6 = 14. 13 is the count when flips are also allowed (the pair 'BBWBWW' and its mirror merge); 64/6 is not an integer, a sign that fixed colourings must be counted.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-136","question":"Three vertices of a regular 12-sided polygon are chosen at random. What is the probability that the triangle they form contains the centre of the polygon strictly inside it?","options":["1/4","2/11","3/11","1/5"],"answer":1,"explanation":"There are C(12, 3) = 220 triangles. The centre is strictly inside exactly when the triangle is acute, i.e. no arc between consecutive chosen vertices is 6 or more steps. Obtuse triangles: take the 'first' vertex clockwise and choose the other two among the next 5 vertices: 12 × C(5, 2) = 120. Right triangles (one side a diameter): 6 diameters × 10 other vertices = 60. Acute: 220 − 120 − 60 = 40, probability 40/220 = 2/11. 1/4 is the answer for three random points on a continuous circle; on a 12-gon right triangles occur and must be excluded.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-137","question":"Four identical H cards and four identical T cards are shuffled and laid in a row. A 'run' is a maximal block of consecutive identical cards (for example HHTHTTTH has 5 runs). What is the expected number of runs?","options":["4.5","4","5","5.5"],"answer":2,"explanation":"Runs = 1 + (number of neighbouring positions where the card changes). There are 7 neighbouring pairs, and each is a change with probability 2 × (4/8)(4/7) = 4/7. Expected runs = 1 + 7 × 4/7 = 5. 4.5 halves 9, mixing up 'pairs' and 'positions'; 4 forgets the leading 1.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-138","question":"A bag has 3 white and 7 black balls. Two players take turns drawing one ball at a time without replacement, Priya first. The first player to draw a white ball wins. What is the probability that Priya wins?","options":["1/2","3/5","5/8","7/12"],"answer":3,"explanation":"Priya wins if the first white ball is at an odd position (1st, 3rd, 5th, 7th). P(first white at position k) = C(10 − k, 2)/C(10, 3): k = 1: 36/120, k = 3: 21/120, k = 5: 10/120, k = 7: 3/120. Sum = 70/120 = 7/12. 1/2 assumes going first gives no edge; 5/8 and 3/5 come from treating the draws as independent with p = 0.3, which ignores that the bag changes.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-139","question":"How many six-digit numbers (100000 to 999999) have digits that add up to 27?","options":["50412","55252","49852","45760"],"answer":0,"explanation":"Count digit strings (leading zeros allowed) with each digit 0–9. Six digits summing to 27: C(32,5) − 6·C(22,5) + 15·C(12,5) = 201376 − 158004 + 11880 = 55252. Strings starting with 0 are five-digit strings summing to 27: C(31,4) − 5·C(21,4) + 10·C(11,4) = 31465 − 29925 + 3300 = 4840. Six-digit numbers: 55252 − 4840 = 50412. 55252 forgets that the first digit cannot be 0.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-140","question":"Eight books standing in positions 1 to 8 on a shelf are taken down and put back so that every book ends up either in its original position or in a position next to it. In how many ways can they be put back (including the original order)?","options":["21","34","55","64"],"answer":1,"explanation":"Look at book 1: either it stays (then the remaining 7 books form the same problem) or it swaps with book 2 (the only way book 2 can then be placed is position 1, so the two simply swap), leaving 6 books. So aₙ = aₙ₋₁ + aₙ₋₂ with a₁ = 1, a₂ = 2: 1, 2, 3, 5, 8, 13, 21, 34. a₈ = 34. 21 is a₇; 64 = 2⁶ treats each neighbouring pair as an independent swap, but overlapping swaps conflict.","difficulty":"very-hard","source":"Product company OA · CAT level"},
  {"id":"apt-pnc-probability-141","question":"How many 5-digit numbers divisible by 3 can be formed from the digits 0, 1, 2, 3, 4, 5 if no digit is repeated?","options":["240","120","312","216"],"answer":3,"explanation":"The digits total 15, so the left-out digit must itself be a multiple of 3: leave out 0 (5! = 120 numbers) or 3 (digits 0, 1, 2, 4, 5: 4 × 4! = 96). Total 216; 240 forgets that 0 cannot lead.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-142","question":"In how many arrangements of the letters of BALLOON are neither the two L's together nor the two O's together?","options":["540","900","780","660"],"answer":3,"explanation":"Total 7!/(2! 2!) = 1260. LL together: 6!/2! = 360; OO together: 360; both together: 5! = 120. Inclusion–exclusion: 1260 − 720 + 120 = 660. Forgetting to add back the 120 gives 540.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-143","question":"Three fair dice are rolled. What is the probability that the product of the three numbers is divisible by 4?","options":["5/8","7/8","3/4","1/2"],"answer":0,"explanation":"The product fails only if all three are odd (27 ways) or exactly one die shows 2 or 6 (an even number with a single factor 2) and the others are odd (3 × 2 × 9 = 54). So P = 1 − 81/216 = 5/8. 7/8 is just the chance of an even product.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-144","question":"How many solutions does x + y + z + w = 20 have in positive ODD integers x, y, z, w?","options":["1771","120","165","286"],"answer":2,"explanation":"Write each as 2a + 1 with a ≥ 0: 2(a + b + c + d) + 4 = 20, so a + b + c + d = 8, which has C(11, 3) = 165 non-negative solutions.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-145","question":"6 men and 4 women sit around a round table. In how many ways can they sit so that no two women are next to each other? (Rotations of a seating count as the same.)","options":["14400","43200","86400","604800"],"answer":1,"explanation":"Seat the men first: (6 − 1)! = 120 circular ways. That leaves 6 gaps between men, and the 4 women take 4 of them in order: 6P4 = 360. Total 120 × 360 = 43200.","difficulty":"hard","source":"TCS NQT · Infosys SP"},
  {"id":"apt-pnc-probability-146","question":"How many ordered triples (a, b, c) of positive integers satisfy a × b × c = 360?","options":["24","180","60","120"],"answer":1,"explanation":"360 = 2³ × 3² × 5. Share each prime's exponent among a, b, c: C(5, 2) = 10 ways for 2³, C(4, 2) = 6 for 3², C(3, 2) = 3 for 5. Total 10 × 6 × 3 = 180.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-147","question":"How many divisors of 10! are perfect squares?","options":["30","270","15","60"],"answer":0,"explanation":"10! = 2⁸ × 3⁴ × 5² × 7. A square divisor uses even exponents: 2 has 0, 2, 4, 6, 8 (5 choices), 3 has 3 choices, 5 has 2, and 7 only 0. So 5 × 3 × 2 = 30. 270 is the total number of divisors.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-148","question":"How many solutions in non-negative integers does x + 2y + 3z = 12 have?","options":["19","91","12","25"],"answer":0,"explanation":"Go through z = 0, 1, 2, 3, 4: then x + 2y = 12, 9, 6, 3, 0, which has 7, 5, 4, 2, 1 solutions. Total 19. 91 = C(14, 2) wrongly treats it as x + y + z = 12.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-149","question":"Three vertices of a regular 12-sided polygon are joined to form a triangle. How many of these triangles are isosceles (equilateral ones included)?","options":["60","56","52","48"],"answer":2,"explanation":"Each vertex is the apex of 5 isosceles triangles (equal sides reaching 1 to 5 steps either way), giving 12 × 5 = 60. The 4 equilateral triangles are each counted 3 times instead of once, so subtract 2 × 4: 52.","difficulty":"very-hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-150","question":"A and B play a match of fair games (each game is equally likely to be won by either). A needs 2 more wins to take the match and B needs 3 more. What is the probability that A takes the match?","options":["11/16","2/3","3/5","5/8"],"answer":0,"explanation":"At most 4 more games settle it, and A wins exactly when A wins at least 2 of those 4 imagined games: (6 + 4 + 1)/16 = 11/16. 3/5 wrongly uses the ratio of games needed.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-151","question":"Two teams play a best-of-7 series (first to 4 wins). Team A wins any game with probability 2/3, independently. What is the probability that the series lasts exactly 6 games?","options":["160/729","200/729","80/243","64/243"],"answer":1,"explanation":"The series ends in game 6 if the winner has exactly 3 wins in the first 5 and wins game 6. A: C(5, 3)(2/3)⁴(1/3)² = 160/729; B: C(5, 3)(1/3)⁴(2/3)² = 40/729. Total 200/729. Counting only A gives 160/729.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-152","question":"The numbers b and c are obtained by rolling a fair die twice. What is the probability that x² + bx + c = 0 has real roots?","options":["17/36","1/2","5/12","19/36"],"answer":3,"explanation":"Real roots need b² ≥ 4c. Count pairs: b = 2 → 1, b = 3 → 2, b = 4 → 4, b = 5 → 6, b = 6 → 6 (b = 1 gives none). Total 19, so 19/36. Using b² > 4c (missing the equal-root cases) gives 17/36.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-153","question":"How many functions f from {1, 2, 3, 4, 5} to itself satisfy f(f(x)) = x for every x?","options":["26","11","25","31"],"answer":0,"explanation":"Such an f is a permutation made of fixed points and swaps: no swap (1), one swap (C(5, 2) = 10), or two swaps (C(5, 2) × C(3, 2)/2 = 15). Total 26. Stopping at one swap gives 11.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-154","question":"How many functions f from {1, 2, 3, 4} to {1, 2, …, 6} satisfy f(1) ≤ f(2) ≤ f(3) ≤ f(4)?","options":["15","126","210","84"],"answer":1,"explanation":"A non-decreasing function is a choice of 4 values from 6 with repetition allowed: C(6 + 4 − 1, 4) = C(9, 4) = 126. 15 = C(6, 4) counts only strictly increasing ones.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-155","question":"How many subsets of {1, 2, …, 10}, including the empty set, contain no two consecutive numbers?","options":["89","143","55","144"],"answer":3,"explanation":"If a(n) counts such subsets of {1, …, n}, then a(n) = a(n − 1) + a(n − 2) (n left out, or n in and n − 1 out), with a(1) = 2 and a(2) = 3. This gives 5, 8, 13, …, a(10) = 144. 143 leaves out the empty set.","difficulty":"very-hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-156","question":"In how many ways can a 2 × 8 strip be completely covered with eight 1 × 2 tiles (each tile placed horizontally or vertically)?","options":["21","55","34","28"],"answer":2,"explanation":"The left end is either one vertical tile (leaving 2 × 7) or two stacked horizontal tiles (leaving 2 × 6), so T(n) = T(n − 1) + T(n − 2) with T(1) = 1, T(2) = 2. T(8) = 34.","difficulty":"hard","source":"Amazon OA · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-157","question":"In an election, Asha gets 7 votes and Bimal gets 4. The 11 ballots are counted one by one in a random order. What is the probability that Asha is strictly ahead throughout the count?","options":["3/11","7/11","4/11","1/3"],"answer":0,"explanation":"By the ballot theorem the probability is (a − b)/(a + b) = (7 − 4)/11 = 3/11. 7/11 is only the chance that the first ballot is for Asha.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-158","question":"Two different squares are chosen at random on an 8 × 8 chessboard. What is the probability that they share a side?","options":["1/16","1/9","7/72","1/18"],"answer":3,"explanation":"There are 7 adjacent pairs in each of 8 rows and in each of 8 columns: 112 pairs, out of C(64, 2) = 2016. 112/2016 = 1/18.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-159","question":"Two queens are placed on two different squares of an 8 × 8 chessboard at random. What is the probability that they attack each other (same row, column or diagonal)?","options":["2/9","7/24","13/18","13/36"],"answer":3,"explanation":"Same row: 8 × C(8, 2) = 224; same column: 224; same diagonal: in each direction 2(1 + 3 + 6 + 10 + 15 + 21) + 28 = 140, so 280. Total 728/2016 = 13/36. Ignoring diagonals gives 2/9.","difficulty":"very-hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-160","question":"Five people get into a lift on the ground floor of a building with 7 upper floors. Each gets off at one of the 7 floors at random, independently. What is the probability that they all get off at different floors?","options":["1/22","360/2401","3/2401","1296/2401"],"answer":1,"explanation":"Favourable: 7 × 6 × 5 × 4 × 3 = 2520 of 7⁵ = 16807 equally likely choices, i.e. (6/7)(5/7)(4/7)(3/7) = 360/2401. 1/22 wrongly treats the people as identical.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-161","question":"A fair coin is tossed repeatedly. What is the probability that the third head comes on exactly the fifth toss?","options":["3/16","5/16","1/4","3/32"],"answer":0,"explanation":"Toss 5 must be a head, and the first 4 tosses must hold exactly 2 heads: C(4, 2) = 6 of 32 sequences, so 3/16. 5/16 = C(5, 3)/32 forgets that the 5th toss must be the third head.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-162","question":"A fair die is rolled until every face 1 to 6 has appeared at least once. What is the expected number of rolls?","options":["21","14.7","36","12"],"answer":1,"explanation":"After k faces have been seen, a new face appears with probability (6 − k)/6, so it takes 6/(6 − k) rolls on average. The total is 6(1 + 1/2 + 1/3 + 1/4 + 1/5 + 1/6) = 6 × 49/20 = 14.7.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-163","question":"Four married couples (8 people) sit at random around a round table. What is the expected number of couples who sit next to each other?","options":["1","4/7","8/7","2"],"answer":2,"explanation":"For a fixed couple, the husband's two neighbours are 2 of the other 7 people, so his wife is next to him with probability 2/7. By linearity of expectation the answer is 4 × 2/7 = 8/7.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-164","question":"What is the sum of all 3-digit numbers that can be formed with the digits 0, 1, 2, 3 if no digit is repeated?","options":["3996","4662","3864","3330"],"answer":2,"explanation":"There are 18 such numbers. Each of 1, 2, 3 leads 6 of them (hundreds total 6 × 6 × 100 = 3600), and each of 1, 2, 3 sits in the tens place 4 times and in the units place 4 times (6 × 4 × 10 + 6 × 4 = 264). Sum 3864.","difficulty":"hard","source":"TCS NQT · Infosys SP"},
  {"id":"apt-pnc-probability-165","question":"All distinct arrangements of the letters of SUCCESS are listed in dictionary order. What is the position (rank) of the word SUCCESS itself?","options":["330","421","331","181"],"answer":2,"explanation":"Words before it: starting with C, 6!/3! = 120; with E, 6!/(3! 2!) = 60; starting SC, 5!/2! = 60; SE, 5!/(2! 2!) = 30; SS, 5!/2! = 60. After SU the letters C, C, E, S, S already stand in alphabetical order, so SUCCESS is the first SU-word: 330 words precede it and its rank is 331.","difficulty":"very-hard","source":"CAT · TCS Digital"},
  {"id":"apt-pnc-probability-166","question":"How many 4-letter arrangements (words, meaningful or not) can be made from the letters of the word MISSISSIPPI? (A letter cannot be used more times than it appears.)","options":["176","136","330","210"],"answer":0,"explanation":"Letters: I×4, S×4, P×2, M×1. By pattern: aaaa: 2 words; aaab: 2 × 3 × 4 = 24; aabb: 3 × 6 = 18; aabc: 3 × 3 × 12 = 108; abcd: 4! = 24. Total 176.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-167","question":"How many different selections (order does not matter) of 4 letters can be made from the letters of the word MISSISSIPPI?","options":["35","15","176","21"],"answer":3,"explanation":"By pattern: four alike (I or S): 2; three alike + one other: 2 × 3 = 6; two pairs from I, S, P: 3; a pair + two other different letters: 3 × 3 = 9; all four different: 1. Total 21. 35 = C(7, 4) ignores that P appears only twice and M once.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-168","question":"How many triangles with integer side lengths have a perimeter of 24? (Triangles with the same three side lengths count once.)","options":["12","19","10","16"],"answer":0,"explanation":"Take a ≤ b ≤ c. Then a + b > c means c < 12, and c ≥ 8. c = 8: (8, 8, 8); c = 9: 2; c = 10: (4,10), (5,9), (6,8), (7,7) = 4; c = 11: 5. Total 12.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-169","question":"A token moves from (0, 0) to (3, 3) on a grid. Each move is one unit right, one unit up, or one diagonal step up-right (from (x, y) to (x + 1, y + 1)). How many different paths are there?","options":["20","63","51","27"],"answer":1,"explanation":"Group by the number k of diagonal steps: k = 0: 6!/(3! 3!) = 20; k = 1: 5!/(2! 2! 1!) = 30; k = 2: 4!/(1! 1! 2!) = 12; k = 3: 1. Total 63. 20 counts only right/up paths.","difficulty":"hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-170","question":"All diagonals of a convex decagon are drawn, and no three of them meet at one interior point. How many points of intersection lie strictly inside the decagon?","options":["35","420","210","45"],"answer":2,"explanation":"Every interior crossing comes from exactly one set of 4 vertices (the two diagonals of that quadrilateral cross once), so the count is C(10, 4) = 210. 35 is the number of diagonals.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-171","question":"Five cards are dealt from a well-shuffled pack of 52. What is the probability of a 'full house' (three cards of one rank and two cards of another rank)?","options":["3/4165","6/4165","12/4165","1/649740"],"answer":1,"explanation":"Pick the rank of the three (13) and 3 of its 4 suits (4), then a different rank for the pair (12) and 2 of its suits (6): 3744 hands. 3744/C(52, 5) = 3744/2598960 = 6/4165. Using C(13, 2) for the two ranks halves it to 3/4165, because the ranks play different roles.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-172","question":"Three people are chosen at random. Assuming each is equally likely to be born in any of the 12 months, what is the probability that at least two of them were born in the same month?","options":["55/72","17/72","1/4","1/144"],"answer":1,"explanation":"P(all different) = (12 × 11 × 10)/12³ = 1320/1728 = 55/72, so P(at least two share) = 1 − 55/72 = 17/72. 55/72 is the complement itself.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-173","question":"How many 4-digit numbers have digits in non-decreasing order from left to right (for example 1123 or 4789)?","options":["126","210","495","715"],"answer":2,"explanation":"The first digit cannot be 0 and the digits never decrease, so 0 never appears. A number is then a choice of 4 digits from 1 to 9 with repetition: C(9 + 4 − 1, 4) = C(12, 4) = 495. 126 = C(9, 4) counts only strictly increasing numbers.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-174","question":"Two different numbers are chosen at random from 1, 2, …, 20. What is the probability that their product is divisible by 6?","options":["3/10","18/95","15/38","1/2"],"answer":2,"explanation":"Count the failures: product odd: C(10, 2) = 45; product not a multiple of 3: C(14, 2) = 91; both conditions (odd non-multiples of 3: 1, 5, 7, 11, 13, 17, 19): C(7, 2) = 21. Failures = 45 + 91 − 21 = 115, so successes = 190 − 115 = 75 and P = 75/190 = 15/38.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-175","question":"A fair coin is tossed 5 times. What is the probability that no two heads come up on consecutive tosses?","options":["11/32","1/2","8/32","13/32"],"answer":3,"explanation":"Strings of length n with no HH follow a(n) = a(n − 1) + a(n − 2): 2, 3, 5, 8, 13. So 13 of the 32 outcomes work: 13/32.","difficulty":"hard","source":"TCS NQT Advanced · Amazon OA"},
  {"id":"apt-pnc-probability-176","question":"Three people take seats in a row of 10 seats so that between any two of them there are at least 2 empty seats. In how many ways can they be seated (the people are different)?","options":["20","336","720","120"],"answer":3,"explanation":"Choosing seats: remove the 2 compulsory empty seats after each of the first two people; then any 3 of the remaining 10 − 4 = 6 positions work, C(6, 3) = 20. The 3 people can be arranged in 3! ways: 120. 20 forgets the arrangement.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-177","question":"Two fair dice are thrown. What is the expected value of the larger of the two numbers (if they are equal, that common number)?","options":["7/2","91/36","4","161/36"],"answer":3,"explanation":"P(max = k) = (2k − 1)/36, so E = Σ k(2k − 1)/36 = (1 + 6 + 15 + 28 + 45 + 66)/36 = 161/36 ≈ 4.47. 91/36 is the expected smaller number.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-178","question":"Four fair dice are thrown. What is the probability that the total is exactly 14?","options":["35/324","73/648","1/9","73/1296"],"answer":1,"explanation":"Let yᵢ = 6 − dieᵢ, so y₁ + … + y₄ = 10 with 0 ≤ yᵢ ≤ 5: C(13, 3) − 4 × C(7, 3) + C(4, 2)… = 286 − 140 = 146 (no term for two yᵢ ≥ 6 since 12 > 10). P = 146/1296 = 73/648.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-179","question":"In how many ways can 5 different balls be placed into 3 identical boxes if a box may be left empty?","options":["41","25","243","150"],"answer":0,"explanation":"Identical boxes mean we count splits of the 5 balls into at most 3 groups: S(5, 1) + S(5, 2) + S(5, 3) = 1 + 15 + 25 = 41. 25 forbids empty boxes; 243 = 3⁵ treats the boxes as different.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-180","question":"In how many ways can 3 different numbers be chosen from 1, 2, …, 30 so that their sum is divisible by 3?","options":["1360","1000","360","4060"],"answer":0,"explanation":"Each remainder class mod 3 has 10 numbers. The sum is a multiple of 3 when all three come from one class (3 × C(10, 3) = 360) or one from each class (10 × 10 × 10 = 1000). Total 1360.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-181","question":"Ravi tells the truth 3 out of 4 times. He throws a fair die and reports that it shows a six; whenever he lies about a non-six result, he claims it is a six. What is the probability that it really is a six?","options":["3/4","1/8","1/6","3/8"],"answer":3,"explanation":"P(six and true report) = (1/6)(3/4) = 3/24; P(not six and he falsely says six) = (5/6)(1/4) = 5/24. Bayes: (3/24)/(8/24) = 3/8.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-182","question":"A speaks the truth in 75% of cases and B in 80% of cases, independently. In what fraction of cases are they likely to contradict each other when stating the same fact?","options":["3/5","7/20","13/20","3/20"],"answer":1,"explanation":"They contradict when exactly one tells the truth: (3/4)(1/5) + (1/4)(4/5) = 3/20 + 4/20 = 7/20. 13/20 is the chance that they agree.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-183","question":"A bag has 4 white and 6 black balls. Three balls are drawn one after another without replacement. What is the probability that the third ball drawn is white?","options":["1/3","1/2","2/5","4/15"],"answer":2,"explanation":"Before anything is seen, the third ball is equally likely to be any of the 10 balls, so P = 4/10 = 2/5. Adding all cases for the first two draws gives the same answer.","difficulty":"hard","source":"Goldman Sachs OA · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-184","question":"How many 6-digit numbers (100000 to 999999) use exactly three different digits?","options":["64800","38880","72900","58320"],"answer":3,"explanation":"Choose the 3 digits: C(10, 3) = 120. Strings of length 6 using all three: 3⁶ − 3 × 2⁶ + 3 = 540, giving 64800 strings. By symmetry, 1/10 of them start with 0, so the 6-digit numbers are 9/10 × 64800 = 58320.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-185","question":"The numbers 1, 2, 3, 4, 5, 6 are arranged in a row. In how many arrangements is NO even number in its own position (2 not 2nd, 4 not 4th, 6 not 6th)?","options":["294","426","265","480"],"answer":1,"explanation":"Inclusion–exclusion over the 3 even numbers: 6! − C(3, 1) 5! + C(3, 2) 4! − C(3, 3) 3! = 720 − 360 + 72 − 6 = 426. 265 is the full derangement count of 6, which wrongly restricts the odd numbers too.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-186","question":"Five cards are drawn from a pack of 52. What is the probability that at least one of them is an ace?","options":["5/13","1/13","18472/54145","3243/10829"],"answer":2,"explanation":"P(no ace) = C(48, 5)/C(52, 5) = 35673/54145, so P(at least one ace) = 18472/54145 ≈ 0.341. 5/13 wrongly adds 5 × 4/52, counting hands with two or more aces repeatedly.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-187","question":"Two different numbers are picked at random from 1, 2, …, 9. What is the probability that their sum is even?","options":["1/2","5/9","4/9","5/18"],"answer":2,"explanation":"The sum is even when both are odd (C(5, 2) = 10) or both even (C(4, 2) = 6): 16 of C(9, 2) = 36 pairs, so 4/9. The tempting 1/2 holds only when numbers may repeat.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-188","question":"A number is chosen at random from 1 to 1000. What is the probability that it has no common factor (other than 1) with 1000?","options":["1/2","3/5","2/5","9/25"],"answer":2,"explanation":"1000 = 2³ × 5³, so the number must be odd and not a multiple of 5: 1000 × (1 − 1/2)(1 − 1/5) = 400 numbers. P = 400/1000 = 2/5. 3/5 wrongly adds the two fractions to remove.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-189","question":"A fair die is rolled repeatedly until two sixes come up on consecutive rolls. What is the expected number of rolls?","options":["36","42","12","72"],"answer":1,"explanation":"Let E be the expected rolls from scratch and E₁ after a single 6. E = 1 + (1/6)E₁ + (5/6)E and E₁ = 1 + (5/6)E. Solving: E = 6 + E₁ and E₁ = 1 + (5/6)E give E = 42. 36 = 6 × 6 is the common guess.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-190","question":"In how many ways can 2 identical rooks be placed on an 8 × 8 chessboard so that they do not attack each other (not in the same row or the same column)?","options":["3136","2016","1176","1568"],"answer":3,"explanation":"First rook: 64 squares; the second must avoid that row and column: 49 squares. The rooks are identical, so divide by 2: 64 × 49/2 = 1568. 3136 forgets to divide by 2.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-191","question":"The numbers 1 to 9 are written in a 3 × 3 grid, one per cell, so that every row increases from left to right AND every column increases from top to bottom. How many such grids are there?","options":["42","1680","48","36"],"answer":0,"explanation":"By the hook-length formula the count is 9!/(5 × 4 × 3 × 4 × 3 × 2 × 3 × 2 × 1) = 362880/8640 = 42. 1680 = 9!/(3!)³ only makes the rows increase.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-192","question":"The digits 1 to 9 are placed in a 3 × 3 grid, one per cell, at random. What is the probability that every row reads in increasing order from left to right?","options":["1/216","1/27","1/36","1/6"],"answer":0,"explanation":"Each row's three numbers are in increasing order with probability 1/3! = 1/6, independently of the other rows, so P = (1/6)³ = 1/216.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-193","question":"How many 4-letter arrangements can be made from the letters of the word EXAMINATION?","options":["2454","1680","2190","136"],"answer":0,"explanation":"EXAMINATION has 8 different letters, with A, I, N appearing twice. All different: 8P4 = 1680. One pair + two other letters: 3 × C(7, 2) × 4!/2! = 756. Two pairs: C(3, 2) × 4!/(2! 2!) = 18. Total 2454.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-194","question":"How many binary strings of length 10 contain exactly four 1's, with no two 1's next to each other?","options":["35","210","70","56"],"answer":0,"explanation":"Lay down the six 0's; they create 7 gaps (including both ends), and the four 1's must go into 4 different gaps: C(7, 4) = 35. 210 = C(10, 4) ignores the restriction.","difficulty":"hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-195","question":"Four vertices of a regular 12-sided polygon are chosen. In how many ways can they be chosen so that they form a rectangle?","options":["30","15","12","66"],"answer":1,"explanation":"A quadrilateral inscribed in a circle is a rectangle exactly when both diagonals are diameters. The 12-gon has 6 diameters, and any 2 of them give a rectangle: C(6, 2) = 15.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-196","question":"Three vertices of a regular 12-sided polygon are chosen to form a triangle. How many of these triangles are right-angled?","options":["30","60","120","66"],"answer":1,"explanation":"An inscribed triangle is right-angled exactly when one side is a diameter. There are 6 diameters and each can be completed by any of the other 10 vertices: 6 × 10 = 60.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-197","question":"A 5 × 5 array of dots (equally spaced, 4 units across) is drawn. How many squares have all four corners on these dots, counting tilted squares too?","options":["30","40","55","50"],"answer":3,"explanation":"Every square fits in an upright bounding square of side k (1 to 4), and each bounding square holds k squares (one upright, k − 1 tilted). There are (5 − k)² bounding squares of side k, so the total is 1·16 + 2·9 + 3·4 + 4·1 = 50. 30 counts only upright squares.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-198","question":"Three of the eight corners of a cube are chosen at random. What is the probability that they form an equilateral triangle?","options":["1/14","3/14","1/7","2/7"],"answer":2,"explanation":"Equilateral triangles have three face diagonals as sides; each one sits around a corner (its three neighbours along face diagonals), giving 8 triangles. P = 8/C(8, 3) = 8/56 = 1/7.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-199","question":"Three different numbers are chosen at random from 1, 2, …, 10. What is the probability that no two of them are consecutive?","options":["7/15","1/2","8/15","2/5"],"answer":0,"explanation":"Selections with no two consecutive: C(10 − 3 + 1, 3) = C(8, 3) = 56, out of C(10, 3) = 120. P = 56/120 = 7/15.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-200","question":"How many integers from 1 to 1000 are divisible by none of 2, 3 and 5?","options":["266","267","734","200"],"answer":0,"explanation":"Inclusion–exclusion: divisible by at least one = 500 + 333 + 200 − 166 − 100 − 66 + 33 = 734. So 1000 − 734 = 266. Using 1000 × (1/2)(2/3)(4/5) ≈ 266.7 and rounding up gives the trap 267.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-201","question":"A positive divisor of 10⁶ is chosen at random. What is the probability that it is a multiple of 10³?","options":["1/2","16/49","1/1000","9/49"],"answer":1,"explanation":"Divisors of 10⁶ = 2⁶ × 5⁶ are 2ᵃ5ᵇ with 0 ≤ a, b ≤ 6: 49 of them. Multiples of 10³ need a ≥ 3 and b ≥ 3: 4 × 4 = 16. P = 16/49. 9/49 uses a, b > 3.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-202","question":"Two fair dice are thrown and the sum is found to be even. What is the probability that both dice show the same number?","options":["1/3","1/6","1/2","1/9"],"answer":0,"explanation":"An even sum happens in 18 of the 36 outcomes (both odd or both even), and all 6 doublets are among them. P = 6/18 = 1/3. 1/6 ignores the given information.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-203","question":"A path from (0, 0) to (5, 5) uses unit steps right or up and must never go above the line y = x (it may touch it). How many such paths are there?","options":["252","126","42","132"],"answer":2,"explanation":"These are counted by the Catalan number C₅ = C(10, 5)/6 = 252/6 = 42 (equivalently 252 − C(10, 4) = 252 − 210 = 42 by the reflection trick). 252 counts all paths.","difficulty":"hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-204","question":"Six balls are thrown at random into 6 boxes, each ball independently and equally likely to land in any box. What is the expected number of boxes that stay empty?","options":["1","15625/7776","5/6","6/e"],"answer":1,"explanation":"A given box stays empty with probability (5/6)⁶, so by linearity the expected number of empty boxes is 6(5/6)⁶ = 15625/7776 ≈ 2.01. 6/e is only the large-n approximation.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-205","question":"A pack of 52 cards is shuffled thoroughly. What is the probability that the four aces end up in four consecutive positions?","options":["1/270725","4/5525","1/5525","1/13"],"answer":2,"explanation":"Treat the 4 aces as one block: 49 starting positions and 4! orders for the aces. P = 49 × 4! × 48!/52! = 49 × 24/(52 × 51 × 50 × 49) = 1/5525. 1/270725 = 1/C(52, 4) forgets the 49 positions and 4! orders.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-206","question":"In how many ways can 12 people be divided into 3 groups of 4 each (the groups have no names or order)?","options":["5775","34650","495","1925"],"answer":0,"explanation":"Labelled groups: 12!/(4! 4! 4!) = 34650. The 3 groups are interchangeable, so divide by 3!: 34650/6 = 5775.","difficulty":"moderate","source":"TCS NQT · Infosys SP"},
  {"id":"apt-pnc-probability-207","question":"A family has 4 children. Assuming boys and girls are equally likely and independent, what is the probability that it has at least 2 boys and at least 1 girl?","options":["11/16","5/8","3/8","1/2"],"answer":1,"explanation":"The cases are exactly 2 boys (C(4, 2) = 6) or exactly 3 boys (4) out of 16 outcomes: 10/16 = 5/8. 11/16 forgets to remove the all-boys case.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-208","question":"A box of 10 bulbs has exactly 2 defective ones. Bulbs are tested one at a time, without replacement, until both defective bulbs are found. What is the probability that the testing stops exactly at the 5th test?","options":["1/45","2/9","4/45","1/10"],"answer":2,"explanation":"The two defective positions are a random pair out of C(10, 2) = 45. Testing stops at the 5th test when one defective is 5th and the other is among the first 4: 4 pairs. P = 4/45.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-209","question":"How many 3-element subsets {a, b, c} of {1, 2, …, 20} with a < b < c form a geometric progression (the common ratio need not be a whole number)?","options":["8","9","15","11"],"answer":3,"explanation":"Ratio 2: 5 sets (1,2,4 up to 5,10,20); ratio 3: (1,3,9), (2,6,18); ratio 4: (1,4,16); ratio 3/2: (4,6,9), (8,12,18); ratio 4/3: (9,12,16). Total 11. Only whole-number ratios give 8.","difficulty":"very-hard","source":"CAT · TCS Digital"},
  {"id":"apt-pnc-probability-210","question":"How many 5-letter 'words' can be formed from the 26 English letters such that the letters are all different, appear in alphabetical order, and at least one of them is a vowel (A, E, I, O, U)?","options":["65780","20349","45431","5 × C(25, 4)"],"answer":2,"explanation":"Words in alphabetical order with different letters correspond to 5-letter selections: C(26, 5) = 65780. Remove those using only the 21 consonants, C(21, 5) = 20349: 45431. 5 × C(25, 4) counts words with several vowels more than once.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-211","question":"3 boys and 3 girls stand in a row so that no two boys are next to each other and no two girls are next to each other. How many arrangements are possible?","options":["36","72","144","720"],"answer":1,"explanation":"The row must alternate, BGBGBG or GBGBGB (2 patterns), and in each the boys and the girls can be ordered in 3! ways: 2 × 6 × 6 = 72. 36 forgets that the row can start with either.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-212","question":"In how many permutations of 1, 2, 3, 4, 5 are there exactly 2 inversions? (An inversion is a pair of positions i < j with the larger number first.)","options":["10","4","6","9"],"answer":3,"explanation":"Exactly 2 inversions come from either two separate adjacent swaps (2 non-overlapping pairs among the 4 adjacent positions: 3 ways, e.g. 21435) or one number jumping two places inside three consecutive positions (3 windows × 2 directions = 6, e.g. 31245 or 23145). Total 9.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-213","question":"A permutation of 1, 2, …, 8 is chosen at random. What is the probability that 1 and 2 lie in the same cycle of the permutation?","options":["1/2","1/4","1/7","1/8"],"answer":0,"explanation":"Follow 1 → p(1) → p(p(1)) → …. At every step the next number is equally likely to be any unvisited number or 1 itself (closing the cycle), so 'reach 2' and 'close the cycle' are equally likely to happen first. P = 1/2, for any n ≥ 2; 1/7 only counts p(1) = 2.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-214","question":"From 5 pairs of shoes, 4 shoes are picked at random. What is the probability that at least one complete pair is among them?","options":["8/21","1/2","2/3","13/21"],"answer":3,"explanation":"No pair means choosing 4 different pairs and one shoe from each: C(5, 4) × 2⁴ = 80 out of C(10, 4) = 210. P(at least one pair) = 1 − 80/210 = 13/21. 8/21 is the no-pair chance.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-215","question":"Three different numbers are chosen at random from 1, 2, …, 10. What is the probability that their sum is divisible by 3?","options":["7/20","1/3","3/10","2/5"],"answer":0,"explanation":"Remainders mod 3: class 0 has {3, 6, 9}, class 1 has {1, 4, 7, 10}, class 2 has {2, 5, 8}. Good selections: one class only, 1 + 4 + 1 = 6, or one from each, 3 × 4 × 3 = 36. 42/120 = 7/20, not the naive 1/3, because the classes are unequal.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-216","question":"A die is loaded so that the probability of showing k is proportional to k (k = 1, …, 6). Two such dice are thrown. What is the probability that the sum is 7?","options":["1/6","4/21","8/63","1/7"],"answer":2,"explanation":"P(k) = k/21. P(sum 7) = Σ k(7 − k)/21² = (6 + 10 + 12 + 12 + 10 + 6)/441 = 56/441 = 8/63. 1/6 is the fair-die answer.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-217","question":"Four fair dice are thrown. In how many of the 1296 outcomes is the total exactly 20?","options":["56","84","20","35"],"answer":3,"explanation":"Using 7 − x on each die maps a total of 20 to a total of 8, so count totals of 8: subtract 1 from each die, y₁ + … + y₄ = 4 with yᵢ ≤ 5 (never binding), C(7, 3) = 35.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-218","question":"Consider the statements: (i) A convex 15-sided polygon has 90 diagonals. (ii) 15 points lie in a plane, 5 of them on one line and no other three on a line; they form C(15, 3) − C(5, 3) = 445 triangles. (iii) 6 people can sit around a round table in 720 ways (rotations counted as the same). Which are correct?","options":["(i) and (iii) only","(ii) only","All three","(i) and (ii) only"],"answer":3,"explanation":"(i) 15 × 12/2 = 90, correct. (ii) 455 − 10 = 445, correct. (iii) Around a table it is (6 − 1)! = 120, not 6! = 720, so it is false.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-219","question":"A and B are events with 0 < P(A), P(B) < 1. Consider: (i) If P(A) = 0.6 and P(B) = 0.5, A and B cannot be mutually exclusive. (ii) If A and B are independent, then A and 'not B' are also independent. (iii) If P(A | B) = P(A), then P(B | A) = P(B). Which are correct?","options":["(i) and (ii) only","All three","(ii) and (iii) only","(ii) only"],"answer":1,"explanation":"(i) Mutually exclusive would need P(A or B) = 1.1 > 1, impossible. (ii) P(A ∩ B') = P(A) − P(A)P(B) = P(A)P(B'). (iii) P(A | B) = P(A) means P(A ∩ B) = P(A)P(B), which is symmetric. All three hold.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-220","question":"In a knockout tennis tournament 37 players take part; whenever a round has an odd number of players, one player gets a bye. How many matches are played in all to decide the champion?","options":["37","18","36","35"],"answer":2,"explanation":"Every match knocks out exactly one player, and 36 players must be knocked out to leave one champion, so 36 matches regardless of byes.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-221","question":"In how many arrangements of the letters of ALLAHABAD are the four A's NOT all together?","options":["7200","7560","360","6480"],"answer":0,"explanation":"Total arrangements: 9!/(4! 2!) = 7560 (A×4, L×2). With the four A's glued into one block there are 6 units (block, L, L, H, B, D): 6!/2! = 360. Answer 7560 − 360 = 7200.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-222","question":"How many 3-digit numbers (100 to 999) have exactly two equal digits (the third digit different)?","options":["252","270","243","216"],"answer":2,"explanation":"Complement: all 900 numbers − all digits different (9 × 9 × 8 = 648) − all three equal (9) = 243. Directly: the patterns AAB, ABA and BAA each give 9 × 9 = 81 numbers, and 3 × 81 = 243.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-223","question":"All the different 4-digit numbers that can be formed by arranging the digits 1, 2, 2, 3 are written down. What is their sum?","options":["26664","53328","21331","13332"],"answer":0,"explanation":"There are 4!/2! = 12 numbers. In each place, 1 appears 3 times, 2 appears 6 times and 3 appears 3 times, so each place's digits add to 3 + 12 + 9 = 24. Sum = 24 × 1111 = 26664. Treating the two 2's as different doubles it to 53328.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-224","question":"How many ordered triples (x, y, z) of positive integers satisfy x × y × z = 30?","options":["10","27","9","6"],"answer":1,"explanation":"30 = 2 × 3 × 5 with three different primes, and each prime can go to x, y or z independently: 3³ = 27 ordered triples.","difficulty":"moderate","source":"CAT · TCS NQT"},
  {"id":"apt-pnc-probability-225","question":"How many ordered pairs (x, y) of positive integers satisfy 1/x + 1/y = 1/6?","options":["5","8","18","9"],"answer":3,"explanation":"Clearing denominators: xy − 6x − 6y = 0, i.e. (x − 6)(y − 6) = 36. Both factors must be positive (negative ones would make x or y ≤ 0), so each of the 9 divisors of 36 gives one pair: 9. Unordered pairs number 5.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-226","question":"In how many ways can two different numbers be chosen from 1, 2, …, 100 so that their sum is divisible by 5?","options":["800","1000","950","990"],"answer":3,"explanation":"Each remainder mod 5 has 20 numbers. Good pairs: both remainder 0: C(20, 2) = 190; remainders 1 & 4: 20 × 20 = 400; remainders 2 & 3: 400. Total 990.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-227","question":"A leap year is chosen at random. What is the probability that it has 53 Sundays?","options":["1/7","53/366","2/7","3/7"],"answer":2,"explanation":"A leap year has 52 full weeks plus 2 extra days. Those 2 consecutive days are one of 7 equally likely pairs (Sun–Mon, …, Sat–Sun), and 2 of them include a Sunday: 2/7. 1/7 is the ordinary-year answer.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-228","question":"A number is chosen at random from 1 to 100. What is the probability that it is a perfect square or a perfect cube?","options":["7/50","3/25","1/10","13/100"],"answer":1,"explanation":"Squares: 10 (1 to 100). Cubes: 4 (1, 8, 27, 64). Both (sixth powers): 1 and 64. So 10 + 4 − 2 = 12, P = 12/100 = 3/25. 7/50 forgets to remove the overlap.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-229","question":"A committee of 5 is chosen from 6 men and 4 women. It must include a particular man, Kiran, and may have at most 2 women. In how many ways can it be formed?","options":["126","105","186","66"],"answer":1,"explanation":"Kiran is in, so choose 4 more from 5 men and 4 women with at most 2 women: 0 women C(5, 4) = 5; 1 woman 4 × C(5, 3) = 40; 2 women C(4, 2) × C(5, 2) = 60. Total 105.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-230","question":"8 players are to be paired off for the first round of a tournament (4 matches, the matches not ordered). In how many ways can the pairing be done?","options":["105","2520","420","70"],"answer":0,"explanation":"Pick the first player's partner (7 ways), then the next unpaired player's partner (5), then 3, then 1: 7 × 5 × 3 × 1 = 105. 2520 = 8!/2⁴ forgets that the 4 matches are not ordered.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-231","question":"Three married couples sit around a round table. In how many seatings does no husband sit next to his own wife? (Rotations count as the same seating.)","options":["32","16","40","48"],"answer":0,"explanation":"Inclusion–exclusion on couples sitting together: 5! − C(3, 1)·2·4! + C(3, 2)·2²·3! − C(3, 3)·2³·2! = 120 − 144 + 72 − 16 = 32.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-232","question":"A 4-digit PIN (0000 to 9999) is chosen at random. What is the probability that its digits are strictly increasing from left to right?","options":["21/1000","1/24","3/500","63/1000"],"answer":0,"explanation":"Each choice of 4 different digits gives exactly one increasing PIN: C(10, 4) = 210 of the 10⁴ PINs, so 210/10000 = 21/1000.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-233","question":"A drawer holds 10 black and 10 white socks. Socks are taken out in the dark. What is the least number that must be taken out to be sure of getting at least one matching black pair AND at least one matching white pair?","options":["3","4","12","21"],"answer":2,"explanation":"In the worst case all 10 socks of one colour come out first; then 2 more of the other colour are needed: 10 + 2 = 12. 3 only guarantees some pair; 4 is a common wrong guess.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-234","question":"What is the least number of people that must be in a group to be sure that at least 3 of them were born in the same month?","options":["24","37","13","25"],"answer":3,"explanation":"With 24 people it is possible to have exactly 2 per month. The 25th person forces some month to have 3 (pigeonhole: 2 × 12 + 1 = 25).","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-235","question":"A bag has 3 red, 4 blue and 5 green balls. Three balls are drawn together at random. What is the probability that they are of three different colours?","options":["1/6","3/11","1/22","1/3"],"answer":1,"explanation":"Favourable: 3 × 4 × 5 = 60 ways; total C(12, 3) = 220. P = 60/220 = 3/11.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-236","question":"A fair coin is tossed 10 times. What is the probability that the number of heads is greater than the number of tails?","options":["1/2","193/512","63/256","193/256"],"answer":1,"explanation":"P(exactly 5 heads) = C(10, 5)/2¹⁰ = 252/1024 = 63/256. By symmetry 'more heads' and 'more tails' share the rest equally: (1 − 63/256)/2 = 193/512. 1/2 forgets the ties.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-237","question":"Anil and Bina each toss 3 fair coins. What is the probability that they get the same number of heads?","options":["1/4","1/8","3/8","5/16"],"answer":3,"explanation":"P(k heads) = 1/8, 3/8, 3/8, 1/8 for k = 0 to 3. P(same) = (1 + 9 + 9 + 1)/64 = 20/64 = 5/16.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-238","question":"A tosses 4 fair coins and B tosses 3 fair coins. What is the probability that A gets more heads than B?","options":["11/32","1/2","4/7","15/32"],"answer":1,"explanation":"Set aside A's last coin. After 3 coins each, P(A ahead) = P(B ahead) = p and P(tie) = t, with 2p + t = 1. A ends ahead if A was ahead already or it was a tie and A's extra coin is a head: p + t/2 = 1/2.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-239","question":"Two numbers x and y are picked independently and uniformly at random from the interval [0, 2]. What is the probability that |x − y| < 1?","options":["1/2","1/4","2/3","3/4"],"answer":3,"explanation":"In the 2 × 2 square of area 4, the region |x − y| ≥ 1 is two corner triangles, each of area ½ × 1 × 1. So the favourable area is 4 − 1 = 3 and P = 3/4.","difficulty":"moderate","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-240","question":"In how many ways can 6 identical balls be put into 3 identical boxes (boxes may be empty)?","options":["28","10","7","3"],"answer":2,"explanation":"Identical balls and identical boxes: count partitions of 6 into at most 3 parts: 6, 5+1, 4+2, 3+3, 4+1+1, 3+2+1, 2+2+2. That is 7. 28 = C(8, 2) would be for different boxes.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-241","question":"In how many ways can 12 be written as an ordered sum of 1's and 2's (for example 2 + 1 + 1 + … counts differently from 1 + 2 + 1 + …)?","options":["144","377","78","233"],"answer":3,"explanation":"If w(n) is the count, the first part is 1 or 2, so w(n) = w(n − 1) + w(n − 2) with w(1) = 1, w(2) = 2. This gives 3, 5, 8, …, w(12) = 233.","difficulty":"hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-242","question":"In how many ways can 10 be written as an ordered sum of 3 positive integers, each at most 5 (for example 5 + 3 + 2 and 2 + 3 + 5 count as different)?","options":["36","18","21","15"],"answer":1,"explanation":"Without the limit there are C(9, 2) = 36. A part above 5 can be written 5 + t with t ≥ 1, and then t + a + b = 5 in positive integers has C(4, 2) = 6 solutions; this can happen in any of the 3 places (never two at once). So 36 − 3 × 6 = 18.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-243","question":"A convex polygon has 3 times as many diagonals as sides. How many sides does it have?","options":["9","6","7","12"],"answer":0,"explanation":"n(n − 3)/2 = 3n gives n − 3 = 6, so n = 9. Check: a 9-gon has 9 × 6/2 = 27 = 3 × 9 diagonals.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-244","question":"All arrangements of the letters of COMPUTER are listed in dictionary order. What is the rank (position) of the word COMPUTER?","options":["1606","1630","1607","1446"],"answer":2,"explanation":"Count the words before it. Fixing C: second letter E or M (smaller than O): 2 × 6! = 1440; then with CO fixed, E before M: 5! = 120; COM then E before P: 4! = 24; COMP then E, R, T before U: 3 × 3! = 18; COMPU then E, R before T: 2 × 2! = 4. Total 1606 before it, so rank 1607.","difficulty":"very-hard","source":"CAT · TCS Digital"},
  {"id":"apt-pnc-probability-245","question":"A 2-digit number (10 to 99) is chosen at random. What is the probability that it is divisible by the sum of its digits?","options":["1/5","1/9","23/90","11/45"],"answer":2,"explanation":"Checking each tens digit: 10, 12, 18, 20, 21, 24, 27, 30, 36, 40, 42, 45, 48, 50, 54, 60, 63, 70, 72, 80, 81, 84, 90 — 23 numbers. P = 23/90.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-246","question":"Three fair dice are rolled. What is the probability that the product of the three numbers is exactly 12?","options":["1/18","1/24","5/72","1/12"],"answer":2,"explanation":"Unordered triples with product 12: {1, 2, 6}, {1, 3, 4} (6 orders each) and {2, 2, 3} (3 orders): 15 outcomes. P = 15/216 = 5/72.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-247","question":"A biased coin shows heads with probability 1/3. It is tossed until the first head. What is the probability that an even number of tosses is needed?","options":["2/5","1/2","1/3","2/3"],"answer":0,"explanation":"P(first head on toss k) = (2/3)^(k−1)(1/3). Summing over even k: (1/3)(2/3)/(1 − 4/9) = (2/9)/(5/9) = 2/5.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-248","question":"A fair die is rolled until a 6 appears. Given that every roll (including the last) showed an even number, what is the expected number of rolls?","options":["3","3/2","6","2"],"answer":1,"explanation":"Conditioning on 'all even' favours short games: P(k rolls, all even) = (1/3)^(k−1)(1/6), whose total is 1/4. So P(k | all even) = (2/3)(1/3)^(k−1), a geometric law with success 2/3, and E = 3/2. The tempting 3 treats the rolls as a fair die on {2, 4, 6}.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-249","question":"A pack of 52 cards is shuffled and turned over one card at a time until the first ace appears. What is the probability that the very next card is the ace of spades? (If the first ace is itself the ace of spades, the event fails.)","options":["1/52","1/51","1/13","3/52"],"answer":0,"explanation":"Take the ace of spades out and shuffle the other 51 cards; it can be put back in 52 equally likely places, and exactly one place (right after the first of the other three aces) gives the event. P = 1/52 — the same as for any named card.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-250","question":"Three independent events have probabilities 0.5, 0.4 and 0.3. What is the probability that at least one of them happens?","options":["6/5","3/50","79/100","11/25"],"answer":2,"explanation":"P(none) = 0.5 × 0.6 × 0.7 = 0.21, so P(at least one) = 0.79 = 79/100. Adding the three probabilities gives 1.2 (6/5), which is impossible.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-251","question":"Three fair dice are rolled. What is the probability that the three numbers, in some order, form an arithmetic progression (a constant common difference, which may be 0)?","options":["1/9","5/36","7/36","1/6"],"answer":2,"explanation":"Difference 0: 6 outcomes (all equal). Difference 1: sets {1,2,3} to {4,5,6}, 4 sets × 3! = 24. Difference 2: {1,3,5}, {2,4,6}: 12. Total 42/216 = 7/36. Forgetting the constant case gives 36/216 = 1/6.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-252","question":"Two different squares are chosen on an 8 × 8 chessboard so that they are of different colours and not in the same row or column. In how many ways can this be done?","options":["768","1568","1024","896"],"answer":0,"explanation":"Pick the first square (64) and then a square of the other colour (32) that avoids its row (4 of them are opposite-coloured there) and column (4 more): 24 choices. Unordered: 64 × 24/2 = 768. 1024 = 32 × 32 ignores the row/column rule.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-253","question":"Five different books A, B, C, D, E are arranged on a shelf. Book C must be at one of the two ends, and books A and B must not be side by side. How many arrangements are possible?","options":["48","36","24","12"],"answer":2,"explanation":"Put C at an end (2 ways). The other four books fill four consecutive places: 4! = 24, of which 2 × 3! = 12 have A and B together. So 2 × 12 = 24.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-254","question":"In how many arrangements of the letters of PROBABILITY are the two I's NOT next to each other?","options":["8164800","9979200","1814400","7257600"],"answer":0,"explanation":"PROBABILITY has 11 letters with B and I each twice: 11!/(2! 2!) = 9979200 arrangements. Gluing the two I's gives 10 units with B twice: 10!/2! = 1814400. Not together: 9979200 − 1814400 = 8164800.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-255","question":"A student guesses every answer in a test of 10 true/false questions. What is the probability that at least 8 answers are right?","options":["7/128","45/1024","1/128","11/1024"],"answer":0,"explanation":"P(≥ 8) = [C(10, 8) + C(10, 9) + C(10, 10)]/2¹⁰ = (45 + 10 + 1)/1024 = 56/1024 = 7/128. 45/1024 is exactly 8 only.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-256","question":"Two cards are drawn together from a pack of 52. Given that at least one of them is an ace, what is the probability that both are aces?","options":["1/17","1/221","1/13","1/33"],"answer":3,"explanation":"Hands with at least one ace: C(52, 2) − C(48, 2) = 1326 − 1128 = 198. Both aces: C(4, 2) = 6. P = 6/198 = 1/33. Compare: if you are told one card is the ace of spades, the answer becomes 3/51 = 1/17.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-257","question":"Two cards are drawn together from a pack of 52. Given that one of them is the ace of spades, what is the probability that both are aces?","options":["1/17","1/33","1/221","3/52"],"answer":0,"explanation":"Knowing the ace of spades is in the hand, the other card is equally likely to be any of the remaining 51 cards, 3 of which are aces: 3/51 = 1/17. The weaker information 'at least one ace' gives the smaller 1/33.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-258","question":"A man has 5 keys, exactly one of which opens a lock. He tries them one by one at random, never trying a key twice. What is the expected number of tries needed to open the lock?","options":["5","5/2","3","4"],"answer":2,"explanation":"The right key is equally likely to be in any of the 5 positions of his random order, so the number of tries is uniform on 1 to 5: E = (1 + 2 + 3 + 4 + 5)/5 = 3. Trying with replacement would give 5.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-259","question":"A set of 5 parallel lines is crossed by another set of 4 parallel lines (not parallel to the first set). How many parallelograms are formed?","options":["20","120","12","60"],"answer":3,"explanation":"A parallelogram needs 2 lines from each family: C(5, 2) × C(4, 2) = 10 × 6 = 60. Counting only the 4 × 3 = 12 smallest cells misses the larger parallelograms.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-260","question":"Shortest grid paths go from (0, 0) to (4, 4) using unit steps right or up. How many of them pass through exactly one of the points (2, 2) and (1, 3)?","options":["70","36","56","52"],"answer":3,"explanation":"Through (2, 2): C(4, 2) × C(4, 2) = 36. Through (1, 3): C(4, 1) × C(4, 3) = 4 × 4 = 16. No path visits both (from (1, 3) you can never reach y = 2 again), so exactly one: 36 + 16 = 52.","difficulty":"hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-261","question":"The four corners of a square are each painted one of 3 colours so that corners joined by a side get different colours (the square is fixed in place, so rotations count as different). In how many ways can this be done?","options":["24","18","12","6"],"answer":1,"explanation":"For a cycle of 4 with k colours the count is (k − 1)⁴ + (k − 1) = 16 + 2 = 18. Treating it as a path (3 × 2 × 2 × 2 = 24) forgets that the last corner also touches the first.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-262","question":"A circular bracelet has 4 equally spaced beads, each black or white. Two bracelets are the same if one can be rotated into the other (flipping is not allowed). How many different bracelets are there?","options":["16","6","4","5"],"answer":1,"explanation":"By pattern: all black, all white, one white, one black, two whites adjacent, two whites opposite — 6. (Burnside: (16 + 2 + 4 + 2)/4 = 6.) 16 counts every colouring as different.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-263","question":"In how many ways can 4 cards be chosen from a pack of 52 so that there is one card of each suit and no two cards have the same rank?","options":["28561","17160","715","24024"],"answer":1,"explanation":"Go suit by suit: spades any of 13 ranks, hearts any of the other 12, diamonds 11, clubs 10: 13 × 12 × 11 × 10 = 17160. 28561 = 13⁴ allows repeated ranks.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-264","question":"Five cards are dealt from a well-shuffled pack. What is the probability of 'two pair' (two cards of one rank, two of another rank, and a fifth card of a third rank)?","options":["198/4165","396/4165","6/4165","1/21"],"answer":0,"explanation":"Choose the two pair ranks C(13, 2) = 78, two suits for each pair (6 × 6), and the fifth card from the 44 cards of other ranks: 78 × 36 × 44 = 123552. Divided by 2598960: 198/4165. Choosing the pair ranks in order (13 × 12) doubles it to 396/4165.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-265","question":"A 3-digit number (100 to 999) is chosen at random. What is the probability that its digits add up to 9?","options":["11/180","1/18","1/9","1/20"],"answer":3,"explanation":"Write the hundreds digit as 1 + a: then a + b + c = 8 with no digit limit binding, giving C(10, 2) = 45 numbers. P = 45/900 = 1/20. (1/9 is the chance of a multiple of 9.)","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-266","question":"A student must answer 7 of 10 questions, choosing at least 3 from the first 5. In how many ways can the 7 questions be chosen?","options":["120","100","110","50"],"answer":2,"explanation":"Split by how many come from the first 5: 3 + 4 gives 10 × 5 = 50, 4 + 3 gives 5 × 10 = 50, 5 + 2 gives 1 × 10 = 10. Total 110. Equivalently, C(10, 7) = 120 minus the 10 choices with only 2 from the first 5.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-267","question":"A token starts at 0 and makes 6 moves, each +1 or −1 with equal probability. What is the probability that it ends at 0 without ever going below 0?","options":["5/16","1/32","5/64","1/8"],"answer":2,"explanation":"Paths of 6 steps that end at 0 and never dip below it are counted by the Catalan number C₃ = 5, out of 2⁶ = 64. P = 5/64. Merely ending at 0 has probability C(6, 3)/64 = 5/16.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-268","question":"Two different numbers are chosen from 1, 2, …, 10. What is the probability that their sum is a prime number?","options":["17/45","2/5","1/3","4/9"],"answer":1,"explanation":"Possible prime sums 3, 5, 7, 11, 13, 17, 19 occur 1, 2, 3, 5, 4, 2, 1 times: 18 pairs out of C(10, 2) = 45. P = 18/45 = 2/5.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-269","question":"Four letters are placed at random in four addressed envelopes, one per envelope. What is the probability that exactly one letter goes into its correct envelope?","options":["3/8","1/4","1/24","1/3"],"answer":3,"explanation":"Choose the correct letter (4 ways); the other 3 must all be wrong: D₃ = 2 ways. 4 × 2 = 8 of the 24 arrangements: P = 1/3. 3/8 is the chance that none is correct (9/24).","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-270","question":"Two fair dice are thrown. What is the probability that the two numbers differ by exactly 2?","options":["1/9","1/6","5/18","2/9"],"answer":3,"explanation":"Unordered pairs with difference 2: (1,3), (2,4), (3,5), (4,6); each can appear in 2 orders: 8 of 36, P = 2/9. 1/9 forgets the order.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-271","question":"In how many ways can 3 squares be chosen on an 8 × 8 chessboard so that all three lie in the same row or all three in the same column?","options":["448","896","1344","3584"],"answer":1,"explanation":"Same row: 8 rows × C(8, 3) = 448; same column: another 448. Three squares cannot be in one row and one column at once, so the total is 896.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-272","question":"The letters of MATHEMATICS are arranged at random. What is the probability that the vowels appear in alphabetical order from left to right (A, A, E, I)?","options":["1/12","1/24","1/4","1/6"],"answer":0,"explanation":"Whatever the positions of the 4 vowels, the vowels A, A, E, I can fill them in 4!/2! = 12 distinguishable orders, all equally likely, and exactly one is alphabetical. P = 1/12. 1/24 forgets that the two A's are identical.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-273","question":"In how many arrangements of 1, 2, 3, 4, 5 in a row is every number (after the first) either larger than all the numbers before it or smaller than all of them?","options":["16","32","8","10"],"answer":0,"explanation":"Read the row backwards: the last number must be the current largest or smallest of all, i.e. 1 or 5; then the same for the remaining four, and so on until one number is left. That gives 2 choices at each of 4 steps: 2⁴ = 16.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-274","question":"How many 4-digit numbers have all their digits even and are divisible by 4?","options":["500","300","200","375"],"answer":1,"explanation":"Digits come from {0, 2, 4, 6, 8}, the first not 0: 4 × 5 × 5 × 5 = 500 numbers. With an even tens digit, the last two digits are divisible by 4 exactly when the units digit is 0, 4 or 8, so 3 of the 5 choices work: 4 × 5 × 5 × 3 = 300.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-275","question":"Cards are turned over one at a time from a well-shuffled pack of 52 until the first spade appears. What is the expected number of cards turned over (including the spade)?","options":["4","52/13","53/14","39/14"],"answer":2,"explanation":"The 13 spades split the 39 other cards into 14 gaps, each holding 39/14 cards on average. The first spade comes after the first gap: 39/14 + 1 = 53/14 ≈ 3.79. 4 = 52/13 is the with-replacement answer.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-276","question":"Five cards are dealt from a pack of 52. What is the expected number of aces among them?","options":["1/13","4/13","5/13","1/2"],"answer":2,"explanation":"Each of the 5 cards is an ace with probability 4/52 = 1/13, so by linearity E = 5/13 ≈ 0.38, even though the cards are not independent.","difficulty":"moderate","source":"Goldman Sachs OA · TCS NQT"},
  {"id":"apt-pnc-probability-277","question":"Three fair dice are rolled. What is the probability that the total is exactly 15?","options":["1/36","5/108","7/216","1/18"],"answer":1,"explanation":"Use 7 − x on each die: a total of 15 corresponds to a total of 6, which has C(5, 2) = 10 outcomes. P = 10/216 = 5/108.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-278","question":"Two fair dice are thrown. What is the probability that the sum of the two numbers is greater than their product?","options":["1/6","5/18","1/3","11/36"],"answer":3,"explanation":"a + b > ab is the same as (a − 1)(b − 1) < 1, which holds exactly when a = 1 or b = 1: 11 of the 36 outcomes. P = 11/36.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-279","question":"From a class of 20 students, a team of 5 is to be chosen and one of the 5 is to be made captain. In how many ways can this be done?","options":["15504","1860480","77520","3876"],"answer":2,"explanation":"Pick the captain (20 ways) and the other 4 members from the remaining 19: 20 × C(19, 4) = 20 × 3876 = 77520. Equivalently C(20, 5) × 5 = 15504 × 5.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-280","question":"10 different books are divided between two friends so that each gets at least 2 books. In how many ways can this be done?","options":["1002","1022","1012","1003"],"answer":0,"explanation":"Each book goes to one of the two friends: 2¹⁰ = 1024. Remove the cases where someone gets 0 books (2) or exactly 1 book (2 × 10 = 20): 1024 − 22 = 1002.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-281","question":"How many functions from a set of 6 elements onto a set of 3 elements are there (every element of the 3-element set is used)?","options":["729","90","537","540"],"answer":3,"explanation":"Inclusion–exclusion: 3⁶ − C(3, 1)2⁶ + C(3, 2)1⁶ = 729 − 192 + 3 = 540. 537 forgets to add back the 3.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-282","question":"5 different balls are put into 3 different boxes (any box may get any number). In how many ways does box 1 end up with exactly 2 balls?","options":["30","80","40","243"],"answer":1,"explanation":"Choose the 2 balls for box 1: C(5, 2) = 10. The other 3 balls each go to box 2 or box 3: 2³ = 8. Total 80.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-283","question":"A 5-letter string is formed by choosing each letter at random from A to Z (repetition allowed). What is the probability that it reads the same forwards and backwards?","options":["1/676","1/26","1/17576","1/325"],"answer":0,"explanation":"A palindrome is fixed by its first three letters (the 4th and 5th copy the 2nd and 1st): 26³ of the 26⁵ strings. P = 1/26² = 1/676.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-284","question":"How many 5-digit palindromes (numbers like 12321 that read the same both ways) are divisible by 3?","options":["30","270","330","300"],"answer":3,"explanation":"A palindrome abcba has digit sum 2a + 2b + c, so we need c ≡ a + b (mod 3). The 90 choices of (a, b) split evenly, 30 for each remainder of a + b, and c then has 4, 3 or 3 choices: 30 × (4 + 3 + 3) = 300.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-285","question":"Each of the four entries of a 2 × 2 matrix is chosen to be 0 or 1 at random (independently, equally likely). What is the probability that the determinant is non-zero?","options":["1/2","1/4","5/16","3/8"],"answer":3,"explanation":"det = ad − bc ≠ 0 needs exactly one of ad, bc to be 1. ad = 1 and bc = 0: 1 × 3 = 3 cases; bc = 1 and ad = 0: another 3. So 6 of 16: 3/8.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-286","question":"How many different selections of 3 letters can be made from the letters of the word ASSASSINATION?","options":["20","286","42","56"],"answer":2,"explanation":"Letters: A×3, S×4, I×2, N×2, T, O (6 types). Three alike: A or S (2). Two alike + one other: 4 types with a pair × 5 others = 20. All different: C(6, 3) = 20. Total 42.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-287","question":"10 people stand in a row in random order. What is the probability that Arjun and Bela have exactly 3 people standing between them?","options":["2/15","1/15","3/10","1/10"],"answer":0,"explanation":"Their positions must differ by 4: the pair of positions can be (1, 5), …, (6, 10), i.e. 6 pairs, with 2 orders each, out of 10 × 9 = 90 equally likely ordered positions. P = 12/90 = 2/15. 1/15 forgets the two orders.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-288","question":"There are three boxes: one with two gold coins, one with two silver coins, and one with a gold and a silver coin. A box is chosen at random and a coin taken from it at random turns out to be gold. What is the probability that the other coin in that box is also gold?","options":["1/2","1/3","2/3","3/4"],"answer":2,"explanation":"There are 3 equally likely gold coins you could have drawn; 2 of them are in the gold–gold box. So the other coin is gold with probability 2/3 — not 1/2, because the gold–gold box is twice as likely to produce a gold coin.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-289","question":"A family has two children. Each child is a boy or a girl with probability 1/2 and is born on any of the 7 weekdays with probability 1/7, all independently. Given that at least one of the children is a boy born on a Tuesday, what is the probability that both children are boys?","options":["1/3","13/27","1/2","7/13"],"answer":1,"explanation":"Each child has 14 equally likely (sex, day) types. Families with at least one Tuesday-boy: 14² − 13² = 27. Both boys among them: 7² − 6² = 13. P = 13/27 — close to 1/2, not the 1/3 of 'at least one boy'.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-290","question":"A whole number from 1 to 100 is chosen at random. What is the probability that it has an odd number of positive divisors?","options":["1/2","1/4","3/25","1/10"],"answer":3,"explanation":"Divisors pair up as d and n/d, so only perfect squares (where d = n/d once) have an odd count. There are 10 squares up to 100: P = 1/10.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-291","question":"A 5 × 5 grid of unit squares is drawn. How many rectangles (made of whole grid squares, squares included) contain the centre square of the grid?","options":["225","81","36","25"],"answer":1,"explanation":"A rectangle contains the centre cell when its left edge is one of the 3 grid lines on or left of it, its right edge one of the 3 on or right of it, and likewise 3 × 3 for top and bottom: 3⁴ = 81. 225 counts all rectangles.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-292","question":"How many terms does the expansion of (a + b + c)⁸ have after like terms are collected?","options":["45","24","36","9"],"answer":0,"explanation":"Each term is aᵖbᵠcʳ with p + q + r = 8, p, q, r ≥ 0: C(8 + 2, 2) = 45 terms.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-293","question":"In how many ways can 15 be written as the sum of three different positive integers, if the order of the parts does not matter (for example 1 + 2 + 12)?","options":["19","91","6","12"],"answer":3,"explanation":"List the smallest part x: x = 1 → (2, 12) … (6, 8): 5 ways; x = 2 → (3, 10) … (6, 7): 4; x = 3 → (4, 8), (5, 7): 2; x = 4 → (5, 6): 1. Total 12. 19 also allows equal parts.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-294","question":"Three fair dice are rolled. What is the expected value of the largest of the three numbers?","options":["7/2","119/24","161/36","5"],"answer":1,"explanation":"P(max ≤ k) = (k/6)³, so P(max = k) = (k³ − (k − 1)³)/216, and E = Σ P(max ≥ k) = Σ (1 − ((k − 1)/6)³) over k = 1..6 = 6 − (0 + 1 + 8 + 27 + 64 + 125)/216 = 6 − 225/216 = 119/24 ≈ 4.96. 161/36 is the answer for two dice.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-295","question":"Four digits are chosen independently at random from 0 to 9. What is the probability that exactly two of them are equal and the other two are different from them and from each other (pattern like 3, 7, 3, 1)?","options":["63/125","27/50","54/125","6/25"],"answer":2,"explanation":"Choose the repeated digit (10), its 2 positions (C(4, 2) = 6), and fill the other two positions with distinct new digits (9 × 8): 4320 of 10⁴. P = 4320/10000 = 54/125.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-296","question":"A point is chosen at random inside a circle. What is the probability that it is closer to the centre than to the circumference?","options":["1/4","1/2","1/3","3/4"],"answer":0,"explanation":"Being closer to the centre means being within half the radius of it. That inner disc has (1/2)² = 1/4 of the area. 1/2 compares radii instead of areas.","difficulty":"moderate","source":"CAT · TCS NQT"},
  {"id":"apt-pnc-probability-297","question":"A coin is tossed 8 times. In how many of the 256 possible sequences are there exactly 3 runs (a run is a maximal block of equal outcomes, as in HH TTT HHH)?","options":["42","21","56","28"],"answer":0,"explanation":"A sequence with 3 runs is fixed by its first face (2 ways) and the 2 places, out of the 7 gaps between tosses, where the face changes: 2 × C(7, 2) = 42. 21 forgets the choice of the starting face.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-298","question":"A fair coin is tossed 8 times. What is the expected number of runs (maximal blocks of equal outcomes)?","options":["4","5","9/2","8/3"],"answer":2,"explanation":"The number of runs is 1 plus the number of the 7 neighbouring pairs that differ, and each pair differs with probability 1/2. E = 1 + 7/2 = 9/2.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-299","question":"How many binary strings of length 7 contain three consecutive 1's somewhere?","options":["40","81","47","48"],"answer":2,"explanation":"Count the complement: strings with no 111 satisfy a(n) = a(n − 1) + a(n − 2) + a(n − 3) with a(1) = 2, a(2) = 4, a(3) = 7, giving 13, 24, 44, 81 for n = 4 to 7. So 128 − 81 = 47.","difficulty":"very-hard","source":"Amazon OA · CAT"},
  {"id":"apt-pnc-probability-300","question":"Three different numbers are chosen at random from 1, 2, …, 10. What is the probability that they can be the side lengths of a (non-degenerate) triangle?","options":["5/12","1/2","17/40","2/5"],"answer":0,"explanation":"With a < b < c, only a + b > c matters. Counting for each largest side c = 4, …, 10: 1, 2, 4, 6, 9, 12, 16 sets, total 50. P = 50/120 = 5/12.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-301","question":"Three vertices of a regular octagon are chosen at random. What is the probability that the triangle formed is acute-angled?","options":["3/7","1/4","1/2","1/7"],"answer":3,"explanation":"Right triangles need a diameter: 4 × 6 = 24. Obtuse ones have all three vertices within a half-circle without a diameter: 8 × C(3, 2) = 24. Acute: 56 − 24 − 24 = 8. P = 8/56 = 1/7.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-302","question":"How many points (x, y) with integer coordinates satisfy |x| + |y| ≤ 3?","options":["25","16","13","49"],"answer":0,"explanation":"For |x| = 0, 1, 2, 3 the number of y-values is 7, 5, 3, 1; with x = ±k counted twice for k > 0: 7 + 2(5 + 3 + 1) = 25. (In general 2n² + 2n + 1.)","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-303","question":"How many points (x, y) with integer coordinates lie strictly inside the circle x² + y² = 10?","options":["29","37","21","25"],"answer":0,"explanation":"x = 0: y from −3 to 3 (7 points); x = ±1: y² < 9, 5 each; x = ±2: y² < 6, 5 each; x = ±3: only y = 0. Total 7 + 10 + 10 + 2 = 29. Including the circle itself would add (±1, ±3) and (±3, ±1) to give 37.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-304","question":"Two different numbers are chosen at random from 1, 2, …, 100. What is the probability that their product ends in 0?","options":["1/10","9/50","269/990","37/100"],"answer":2,"explanation":"Count failures: no factor 2 (both odd): C(50, 2) = 1225; no factor 5: C(80, 2) = 3160; neither (both odd and not multiples of 5, 40 numbers): C(40, 2) = 780. Failures 1225 + 3160 − 780 = 3605 of 4950, so P = 1345/4950 = 269/990.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-305","question":"How many of the numbers from 1 to 1000 contain the digit 7 at least once?","options":["300","271","729","252"],"answer":1,"explanation":"Write 1 to 999 as 3-digit strings 001 to 999 and add 000 in place of 1000 (neither has a 7). Strings with no 7: 9³ = 729, so 1000 − 729 = 271 contain a 7. 300 counts 7 in each place separately and double-counts.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-306","question":"A fair die is rolled 4 times. What is the probability of getting exactly two sixes?","options":["1/36","25/1296","25/216","1/6"],"answer":2,"explanation":"C(4, 2) choices of which rolls are sixes × (1/6)² × (5/6)² = 6 × 25/1296 = 150/1296 = 25/216. 25/1296 forgets the 6 positions.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-307","question":"A bag holds two dice: a fair one and a loaded one that shows 6 with probability 1/2. One die is picked at random and rolled twice; both rolls are 6. What is the probability that the loaded die was picked?","options":["1/2","9/10","3/4","8/9"],"answer":1,"explanation":"P(two 6s | loaded) = 1/4 and P(two 6s | fair) = 1/36. With equal priors, P(loaded | data) = (1/4)/(1/4 + 1/36) = 9/10.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-308","question":"1% of people have a certain condition. A test is positive for 90% of those who have it and for 10% of those who do not. A person tests positive on two independent runs of the test. What is the probability that the person has the condition?","options":["1/12","81/100","9/20","1/2"],"answer":2,"explanation":"P(two positives and ill) = 0.01 × 0.9² = 0.0081; P(two positives and well) = 0.99 × 0.1² = 0.0099. P(ill | two positives) = 0.0081/0.0180 = 9/20. After one positive it would be only 1/12.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-309","question":"A fair coin is tossed 6 times. What is the probability that somewhere there are at least 4 heads in a row?","options":["3/64","11/64","1/8","1/16"],"answer":2,"explanation":"Let the first run of 4 heads start at position 1, 2 or 3. Start 1: HHHH?? → 4 sequences. Start 2: THHHH? → 2. Start 3: ?THHHH → 2. These are disjoint, giving 8/64 = 1/8.","difficulty":"hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-310","question":"Two fair dice are thrown. What is the probability that the product of the numbers is a perfect square?","options":["1/6","2/9","5/18","7/36"],"answer":1,"explanation":"Squares can come from equal numbers (6 doublets) or from {1, 4} in either order (2 more): 8 of 36, so 2/9. 1/6 counts only the doublets.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-311","question":"In how many permutations of 1, 2, 3, 4, 5, 6 is 1 not in the first place and 6 not in the last place?","options":["480","504","600","576"],"answer":1,"explanation":"Total 720. 1 first: 120; 6 last: 120; both: 24. So 720 − 240 + 24 = 504. 480 forgets to add back the 24.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-312","question":"A 4-letter code uses letters from A to Z (repetition allowed). How many codes contain exactly one vowel (A, E, I, O, U), in any position?","options":["46305","92610","194481","185220"],"answer":3,"explanation":"Choose the vowel's position (4), the vowel (5) and three consonants (21³ = 9261): 4 × 5 × 9261 = 185220. 46305 forgets the position.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-313","question":"Three different numbers are drawn from 1, 2, …, 9. What is the probability that their product is even?","options":["37/42","5/42","1/2","4/9"],"answer":0,"explanation":"The product is odd only if all three are odd: C(5, 3) = 10 of C(9, 3) = 84. P(even) = 1 − 10/84 = 37/42.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-314","question":"Five people A, B, C, D, E sit around a round table. In how many seatings are A and B not next to each other while C and D are next to each other? (Rotations count as the same.)","options":["8","12","6","4"],"answer":3,"explanation":"Fix A. B must take one of the 2 seats not beside A. Then the other three seats contain exactly one pair of neighbouring seats, which C and D must take (2 orders), and E gets the last seat: 2 × 2 = 4.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-315","question":"How many squares of all sizes on an 8 × 8 chessboard do not touch the outer border of the board (not even at a corner)?","options":["91","204","140","36"],"answer":0,"explanation":"Squares that avoid the border lie inside the central 6 × 6 block, which contains 1² + 2² + … + 6² = 91 squares. 204 counts every square on the board.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-316","question":"In how many ways can 3 boys and 3 girls sit around a round table so that boys and girls alternate and a particular boy, Ravi, has a particular girl, Sita, on his immediate right?","options":["12","4","2","8"],"answer":1,"explanation":"Fix Ravi; Sita's seat is then fixed. The other 2 boys take the remaining 2 boys' seats (2! ways) and the other 2 girls the remaining girls' seats (2!): 4. Without the Sita condition it would be 2! × 3! = 12.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-317","question":"Six identical chocolates are shared among 3 children A, B and C (a child may get none) so that A gets at least as many as B. In how many ways can this be done?","options":["28","14","10","16"],"answer":3,"explanation":"Go through b: b = 0 → a = 0..6 (7 ways); b = 1 → a = 1..5 (5); b = 2 → a = 2..4 (3); b = 3 → a = 3 (1). C gets the rest. Total 16. Halving the 28 unrestricted ways ignores the ties a = b.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-318","question":"Seven persons sit in a row at random. What is the probability that three particular persons sit together (in any order)?","options":["1/42","3/7","1/5","1/7"],"answer":3,"explanation":"Glue the three into a block: 5 units arranged in 5! ways, times 3! orders inside: 720 of 5040, P = 1/7.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-319","question":"A positive integer is chosen at random from 1 to 60. What is the probability that it is divisible by 4 or by 6 but NOT by 5?","options":["1/3","1/5","7/30","4/15"],"answer":3,"explanation":"Multiples of 4 or 6 up to 60: 15 + 10 − 5 = 20. Of these, the multiples of 5 are multiples of 20 or 30: 20, 40, 60, 30 — 4 numbers. So 16/60 = 4/15.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-320","question":"The digits 1 to 9 are arranged in a row at random. What is the probability that the odd digits occupy the odd positions (1st, 3rd, 5th, 7th, 9th)?","options":["1/63","1/126","1/9","5/9"],"answer":1,"explanation":"Favourable: the 5 odd digits fill the 5 odd places (5!) and the 4 even digits the even places (4!): 2880 of 9! = 362880, i.e. 1/C(9, 4) = 1/126.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-321","question":"In a group of 4 people, what is the probability that at least two share a birth month? (Assume all 12 months equally likely and independent.)","options":["41/96","55/96","1/3","11/96"],"answer":0,"explanation":"P(all different) = (12 × 11 × 10 × 9)/12⁴ = 11880/20736 = 55/96. So P(some match) = 41/96 ≈ 0.43.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-322","question":"How many different rectangles with whole-number side lengths have an area of 360? (An a × b and a b × a rectangle count as the same.)","options":["12","24","11","13"],"answer":0,"explanation":"360 = 2³ × 3² × 5 has (3 + 1)(2 + 1)(1 + 1) = 24 divisors. They pair up as a × b with a ≤ b, and 360 is not a perfect square, so there are 24/2 = 12 rectangles.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-323","question":"In how many ways can 2520 be written as a product a × b of two coprime positive integers, if a × b and b × a count as the same?","options":["8","16","24","4"],"answer":0,"explanation":"2520 = 2³ × 3² × 5 × 7 has 4 distinct primes. Coprime factors cannot share a prime, so each prime power goes wholly to a or to b: 2⁴ = 16 ordered ways, i.e. 8 unordered (1 × 2520 included).","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-324","question":"What is the sum of all the positive divisors of 360?","options":["1080","810","720","1170"],"answer":3,"explanation":"The divisor sum is multiplicative: (1 + 2 + 4 + 8)(1 + 3 + 9)(1 + 5) = 15 × 13 × 6 = 1170. Leaving out 360 itself would give 810.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-325","question":"A permutation of 1, 2, 3, 4, 5, 6 is chosen at random. What is the expected number of inversions (pairs of positions i < j where the larger number comes first)?","options":["15","15/2","6","5"],"answer":1,"explanation":"Each of the C(6, 2) = 15 pairs of positions is out of order with probability 1/2, so by linearity the expected number of inversions is 15/2 = 7.5.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-326","question":"Five runners with different speeds start a race in random order of position, and we scan them from first to last. A runner is a 'record' if faster than everyone before them (the first runner is always a record). What is the expected number of records?","options":["137/60","5/2","2","3"],"answer":0,"explanation":"The k-th runner is a record exactly when they are the fastest of the first k, which has probability 1/k. So E = 1 + 1/2 + 1/3 + 1/4 + 1/5 = 137/60 ≈ 2.28.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-327","question":"Five different numbers are drawn at random from 1, 2, …, 10. What is the probability that the largest of them is 8?","options":["1/10","1/6","7/36","5/36"],"answer":3,"explanation":"8 must be drawn and the other 4 must come from 1 to 7: C(7, 4) = 35 of C(10, 5) = 252. P = 35/252 = 5/36.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-328","question":"Three fair dice are rolled. What is the probability that the middle value (the median of the three numbers) is 4?","options":["13/54","1/6","1/4","7/36"],"answer":0,"explanation":"Median 4 happens with one 4, one smaller and one larger number (3 × 2 × 3! = 36), two 4's and any other number (3 × 5 = 15), or three 4's (1): 52 outcomes. P = 52/216 = 13/54.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-329","question":"10 people are to be seated at two round tables, 5 at each. In how many ways can this be done? (The two tables are identical, and rotations at a table do not count as different.)","options":["145152","3628800","72576","2880"],"answer":2,"explanation":"Split the 10 into two groups of 5: C(10, 5)/2 = 126 (the tables are alike). Each group sits round its table in 4! = 24 ways: 126 × 24 × 24 = 72576. Not halving gives 145152.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-330","question":"8 players are to be paired up and each pair sent to a different one of 4 numbered courts. In how many ways can this be done?","options":["105","2520","40320","1680"],"answer":1,"explanation":"Line the players up (8!) and give positions 1–2 to court 1, 3–4 to court 2, and so on; swapping the two players on a court gives the same assignment, so divide by 2⁴: 2520. 105 ignores the court numbers.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-331","question":"In how many arrangements of the letters of CALCULATE do the vowels occupy only odd-numbered positions (1st, 3rd, 5th, 7th, 9th)?","options":["45360","1800","2880","900"],"answer":1,"explanation":"Vowels A, A, U, E (4) must go into 4 of the 5 odd places: C(5, 4) × 4!/2! = 5 × 12 = 60. The consonants C, C, L, L, T fill the other 5 places: 5!/(2! 2!) = 30. Total 60 × 30 = 1800.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-332","question":"A bag has 5 red and 4 blue balls. Three balls are drawn one after another without replacement. What is the probability that the first two are red and the third is blue?","options":["5/42","10/21","20/81","10/63"],"answer":3,"explanation":"Multiply the step-by-step chances: (5/9)(4/8)(4/7) = 80/504 = 10/63. 5/42 = C(5, 2) × C(4, 1)/C(9, 3) ignores the required order.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-333","question":"An urn starts with 1 red and 1 blue ball. Each time, a ball is drawn at random and put back together with one more ball of the same colour. What is the probability that the first three draws are all red?","options":["1/8","1/3","1/4","3/8"],"answer":2,"explanation":"Red keeps getting more likely: P = (1/2)(2/3)(3/4) = 1/4. Treating the draws as independent fair draws gives 1/8.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-334","question":"Three fair dice are rolled and all three numbers turn out to be different. What is the probability that one of them is a 6?","options":["91/216","1/6","5/12","1/2"],"answer":3,"explanation":"Given the numbers are different, all C(6, 3) = 20 sets are equally likely, and 6 belongs to C(5, 2) = 10 of them: P = 1/2. 91/216 is the unconditional chance of at least one 6.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-335","question":"Two cards are drawn without replacement from ten cards numbered 1 to 10. What is the expected value of the sum of the two numbers?","options":["10","55/9","11","12"],"answer":2,"explanation":"Each card drawn has expected value 5.5, even without replacement, so the expected sum is 2 × 5.5 = 11 by linearity.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-336","question":"A fair die is rolled until a number greater than 4 appears. What is the expected number of rolls?","options":["2","3","6","3/2"],"answer":1,"explanation":"Each roll succeeds (5 or 6) with probability 1/3, so the number of rolls is geometric with mean 1/(1/3) = 3.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-337","question":"A 4-digit number (1000 to 9999) is chosen at random. What is the probability that the sum of its digits is even?","options":["4/9","1/2","5/9","9/20"],"answer":1,"explanation":"Whatever the first three digits are, the last digit (0 to 9) has 5 values that make the sum even and 5 that make it odd. So exactly half the numbers work: 1/2.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-338","question":"In how many ways can 7 identical balls be placed in 4 different boxes if no box may hold more than 3 balls?","options":["120","35","40","44"],"answer":2,"explanation":"Without the limit: C(10, 3) = 120. A box with 4 or more: give it 4 first, leaving 3 balls for 4 boxes: C(6, 3) = 20, for each of 4 boxes: 80. Two boxes can't both have 4 (8 > 7). So 120 − 80 = 40.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-339","question":"A player needs a total of exactly 10 with two dice. She may try twice (stopping if the first try succeeds). What is the probability that she succeeds?","options":["1/6","1/12","1/72","23/144"],"answer":3,"explanation":"P(10 in one throw) = 3/36 = 1/12. P(failing twice) = (11/12)² = 121/144, so success = 23/144. Adding 1/12 + 1/12 = 1/6 double-counts.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-340","question":"Anil wins any single game against Bimal with probability 0.6, independently. They play a best-of-3 match (first to 2 wins). What is the probability that Anil wins the match?","options":["3/5","9/25","18/25","81/125"],"answer":3,"explanation":"Anil wins 2–0 with probability 0.36, or 2–1 (losing exactly one of the first two, then winning the third) with 2 × 0.6 × 0.4 × 0.6 = 0.288. Total 0.648 = 81/125.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-341","question":"How many ordered pairs (A, B) of subsets of {1, 2, 3, 4, 5} satisfy A ⊆ B?","options":["32","1024","243","120"],"answer":2,"explanation":"Each element independently is in neither set, in B only, or in both (it cannot be in A without B): 3 choices, so 3⁵ = 243 pairs.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-342","question":"How many ordered pairs (A, B) of subsets of {1, 2, 3, 4, 5} have exactly one element in common (|A ∩ B| = 1)?","options":["243","405","80","160"],"answer":1,"explanation":"Choose the common element (5 ways). Every other element must not be in both sets: neither, A only or B only — 3 choices each, 3⁴ = 81. Total 405.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-343","question":"A test has 6 questions, each with 4 options and one correct answer. A student answers every question by guessing. What is the probability of getting at most one answer right?","options":["729/4096","1/2","2187/4096","1215/4096"],"answer":2,"explanation":"P(0 right) = (3/4)⁶ = 729/4096; P(exactly 1) = 6 × (1/4)(3/4)⁵ = 1458/4096. Together 2187/4096 ≈ 0.53.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-344","question":"How many 5-digit numbers contain each of the digits 1, 2 and 3 at least once, using only the digits 1, 2, 3?","options":["150","243","60","93"],"answer":0,"explanation":"Strings of length 5 over {1, 2, 3}: 3⁵ = 243. Remove those missing at least one digit by inclusion–exclusion: 3 × 2⁵ − 3 × 1 = 93. So 243 − 93 = 150.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-345","question":"A committee of 4 is chosen from 5 men and 5 women. What is the probability that it has more women than men, given that it has at least one woman?","options":["11/41","1/2","11/42","23/42"],"answer":0,"explanation":"More women: 3 women + 1 man (C(5, 3) × 5 = 50) or 4 women (5): 55. Committees with at least one woman: C(10, 4) − C(5, 4) = 210 − 5 = 205. P = 55/205 = 11/41. Dividing by all 210 committees gives the unconditional 11/42.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-346","question":"Three of the 8 corners of a cube are chosen. How many of the resulting triangles are right-angled?","options":["24","56","48","32"],"answer":2,"explanation":"No three corners are collinear, so there are C(8, 3) = 56 triangles. The only non-right ones are the 8 equilateral triangles made of three face diagonals; every other triangle has sides 1, 1, √2 or 1, √2, √3, which satisfy Pythagoras. 56 − 8 = 48.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-347","question":"In how many ways can 20 be written as a sum of three DIFFERENT positive integers, if the order does not matter?","options":["33","171","27","24"],"answer":3,"explanation":"Take x < y < z by the smallest part: x = 1 → y = 2..9 (8 ways), x = 2 → y = 3..8 (6), x = 3 → y = 4..8 (5), x = 4 → y = 5..7 (3), x = 5 → y = 6, 7 (2). Total 24. Allowing equal parts gives 33.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-348","question":"Two different cells of a 3 × 3 grid are chosen. In how many ways can they be chosen so that they do NOT share a side?","options":["12","24","36","20"],"answer":1,"explanation":"All pairs: C(9, 2) = 36. Pairs sharing a side: 2 per row × 3 rows + 2 per column × 3 columns = 12. So 36 − 12 = 24 (diagonal neighbours are allowed).","difficulty":"hard","source":"TCS NQT Advanced · Amazon OA"},
  {"id":"apt-pnc-probability-349","question":"A bug walks from one corner of a box-shaped grid to the opposite corner, moving one unit at a time in the +x, +y or +z direction, from (0, 0, 0) to (1, 2, 3). How many shortest routes are there?","options":["60","720","120","36"],"answer":0,"explanation":"Every shortest route is an arrangement of 1 x-step, 2 y-steps and 3 z-steps: 6!/(1! 2! 3!) = 60.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-350","question":"10 identical candies are shared among 3 children so that each child gets an EVEN number of candies (zero allowed). In how many ways can this be done?","options":["66","15","36","21"],"answer":3,"explanation":"Give each child 2a, 2b, 2c candies: a + b + c = 5 with a, b, c ≥ 0, which has C(7, 2) = 21 solutions. 66 = C(12, 2) ignores the evenness.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-351","question":"How many 3-digit numbers have digits that form an arithmetic progression when read from left to right (for example 135, 840 or 777)?","options":["36","54","45","40"],"answer":2,"explanation":"Fix the middle digit b; the outer digits are b − d and b + d with the first digit at least 1 and the last at most 9. The counts for b = 0, 1, …, 9 are 0, 2, 4, 6, 8, 9, 7, 5, 3, 1, which add to 45.","difficulty":"very-hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-352","question":"Two fair dice are thrown. What is the probability that the total is a multiple of 3 or a multiple of 4?","options":["5/9","7/12","1/2","11/18"],"answer":0,"explanation":"Multiples of 3 (3, 6, 9, 12): 2 + 5 + 4 + 1 = 12 outcomes. Multiples of 4 (4, 8, 12): 3 + 5 + 1 = 9. Both (12): 1. So 12 + 9 − 1 = 20, P = 20/36 = 5/9.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-353","question":"Four points are chosen independently and uniformly at random on a circle. What is the probability that the quadrilateral they form contains the centre of the circle?","options":["1/2","1/4","1/8","3/4"],"answer":0,"explanation":"The centre is outside exactly when all 4 points lie in some semicircle. For n points that probability is n/2ⁿ⁻¹ = 4/8 = 1/2, so the quadrilateral contains the centre with probability 1/2. (For a triangle it is 1/4.)","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-354","question":"In a lottery, 2 prizes are drawn from 10 tickets (2 different winning tickets). Raju holds 3 of the tickets. What is the probability that he wins at least one prize?","options":["3/5","8/15","3/10","7/15"],"answer":1,"explanation":"P(no prize) = C(7, 2)/C(10, 2) = 21/45 = 7/15, so P(at least one) = 8/15. 3/5 wrongly adds 3/10 twice.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-355","question":"A box has 10 bulbs, 3 of them defective. 4 bulbs are picked at random without replacement. What is the expected number of defective bulbs picked?","options":["1","3/4","6/5","2"],"answer":2,"explanation":"Each of the 4 picked bulbs is defective with probability 3/10, so by linearity E = 4 × 3/10 = 6/5 = 1.2, whether or not the picks are replaced.","difficulty":"hard","source":"TCS NQT Advanced · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-356","question":"Two numbers a and b are chosen independently and uniformly from 1 to 20 (they may be equal). What is the probability that gcd(a, b) = 1?","options":["3/5","6/π²","51/80","1/2"],"answer":2,"explanation":"Ordered coprime pairs: for each larger value n there are φ(n) partners below or equal, and Σφ(1..20) = 128, so 2 × 128 − 1 = 255 pairs (the pair (1, 1) is counted once). P = 255/400 = 51/80. 6/π² ≈ 0.61 is only the large-range limit.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-357","question":"10 people sit around a round table. Everyone shakes hands with everyone else except the two people sitting next to them. How many handshakes take place?","options":["45","25","40","35"],"answer":3,"explanation":"All pairs: C(10, 2) = 45. The neighbour pairs around the table are 10 (one per gap). So 45 − 10 = 35 handshakes.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-358","question":"Five cards are dealt from a pack of 52. What is the expected number of suits that do NOT appear in the hand?","options":["1","1/4","3/4","2109/2380"],"answer":3,"explanation":"A particular suit is missing when all 5 cards come from the other 39: C(39, 5)/C(52, 5) ≈ 0.2215. By linearity, the expected number of missing suits is 4 × C(39, 5)/C(52, 5) = 2109/2380 ≈ 0.886.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-359","question":"Two 2-element subsets of {1, 2, 3, 4, 5, 6} are chosen independently at random (they may be the same). What is the probability that they are disjoint?","options":["2/5","1/5","3/5","1/3"],"answer":0,"explanation":"Whatever the first subset is, the second must avoid both its elements, i.e. be one of C(4, 2) = 6 of the C(6, 2) = 15 subsets: P = 6/15 = 2/5.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-360","question":"In how many ways can 6 people be split into 3 teams of 2, if two particular people, Asha and Bina, must NOT be in the same team?","options":["15","9","6","12"],"answer":3,"explanation":"All splits into 3 unlabelled pairs: 5 × 3 × 1 = 15. Splits with Asha and Bina together: the other 4 form pairs in 3 ways. So 15 − 3 = 12.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-361","question":"A fair die is rolled until two DIFFERENT faces have appeared. What is the expected number of rolls?","options":["11/5","2","7/2","12/5"],"answer":0,"explanation":"The first roll gives one face; after that each roll shows a new face with probability 5/6, taking 6/5 rolls on average. E = 1 + 6/5 = 11/5 = 2.2.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-362","question":"How many ordered triples (a, b, c) with each of a, b, c in {1, 2, …, 6} satisfy a < b and c < b?","options":["21","35","55","70"],"answer":2,"explanation":"For a fixed middle value b, a and c can each be any of the b − 1 smaller values: (b − 1)². Sum over b = 1..6: 0 + 1 + 4 + 9 + 16 + 25 = 55.","difficulty":"very-hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-363","question":"How many 4-digit numbers greater than 5000 can be formed from the digits 0, 5, 6, 7, 8 if no digit is repeated?","options":["120","96","72","95"],"answer":1,"explanation":"The first digit must be 5, 6, 7 or 8 (4 ways), and every such number exceeds 5000 because 5000 itself needs repeated zeros. The other three places take 4 × 3 × 2 = 24 orders of the remaining digits: 96.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-364","question":"Three cards are drawn together from a pack of 52. What is the probability that both colours (red and black) appear among them?","options":["1/2","4/17","13/17","3/4"],"answer":2,"explanation":"P(all one colour) = 2 × C(26, 3)/C(52, 3) = 2 × 2600/22100 = 4/17. So both colours appear with probability 13/17.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-365","question":"From 8 married couples, one man and one woman are to be chosen who are NOT married to each other. In how many ways can this be done?","options":["64","56","112","120"],"answer":1,"explanation":"Choose the man (8 ways) and then any woman except his wife (7 ways): 56. 64 includes the 8 married pairs.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-366","question":"A drawer has 6 red and 4 blue socks. Socks are drawn one at a time without replacement. What is the probability that the first blue sock appears on the third draw?","options":["1/6","2/15","4/15","1/5"],"answer":0,"explanation":"The first two must be red and the third blue: (6/10)(5/9)(4/8) = 120/720 = 1/6.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-367","question":"The digits 1, 2, 3, 4, 5 are arranged at random to form a 5-digit number. What is the probability that the number is divisible by 4?","options":["1/4","1/5","2/5","1/10"],"answer":1,"explanation":"Divisibility by 4 depends on the last two digits: from these digits the valid endings are 12, 24, 32, 52 (4 of the 20 ordered pairs). P = 4/20 = 1/5.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-368","question":"A point (x, y) is chosen uniformly at random in the square 0 ≤ x, y ≤ 1. What is the probability that y > x²?","options":["1/3","2/3","1/2","3/4"],"answer":1,"explanation":"The area under y = x² on [0, 1] is ∫x² dx = 1/3, so the area above it is 1 − 1/3 = 2/3.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-369","question":"Three fair dice are rolled. What is the probability that the sum is even AND the product is a multiple of 3?","options":["1/2","19/27","19/54","7/27"],"answer":2,"explanation":"Even sums: 108 outcomes. Remove those with no 3 or 6: dice from {1, 2, 4, 5}, where half of the 4³ = 64 outcomes have an even sum (32). So 108 − 32 = 76, P = 76/216 = 19/54.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-370","question":"Six people A, B, C, D, E, F stand in a row. In how many arrangements is A somewhere to the left of B, and C somewhere to the left of D (not necessarily next to each other)?","options":["360","120","240","180"],"answer":3,"explanation":"By symmetry, A is left of B in half of the 720 arrangements, and independently C is left of D in half of those: 720/4 = 180.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-371","question":"How many of the line segments joining two corners of a cube pass through the interior of the cube?","options":["12","16","28","4"],"answer":3,"explanation":"C(8, 2) = 28 segments: 12 edges and 12 face diagonals lie on the surface, leaving 4 space diagonals that pass through the inside.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-372","question":"Four letters are put at random into their four addressed envelopes, one per envelope. What is the probability that at least two letters reach the right envelope?","options":["1/4","11/24","7/24","3/8"],"answer":2,"explanation":"Exactly 2 right: C(4, 2) × 1 (the other two swapped) = 6; exactly 3 right is impossible; all 4 right: 1. So 7 of 24 arrangements: 7/24.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-373","question":"A permutation of 1, 2, …, 6 is chosen at random. What is the probability that no number is in its own position AND the number 2 is in position 1?","options":["53/600","1/6","265/720","53/720"],"answer":3,"explanation":"Of the D₆ = 265 derangements, the first position is equally likely to hold any of 2, …, 6, so 265/5 = 53 have 2 first. P = 53/720.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-374","question":"How many 4-letter arrangements can be made from the letters of BANANA?","options":["38","60","24","36"],"answer":0,"explanation":"By letter content: AAAN and AAAB give 4 each; AANN gives 4!/(2! 2!) = 6; AANB and ANNB give 12 each. Total 4 + 4 + 6 + 12 + 12 = 38.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-375","question":"The 60 distinct arrangements of the letters of BANANA are listed in dictionary order. What is the position of BANANA?","options":["31","34","35","37"],"answer":2,"explanation":"Words starting with A: 5!/(2! 2!) = 30. Among B-words: BAA… (3!/2! = 3 words) come first, then BANAAN (1 word), then BANANA. 30 + 3 + 1 = 34 words come before it, so it is 35th.","difficulty":"very-hard","source":"CAT · TCS Digital"},
  {"id":"apt-pnc-probability-376","question":"A committee of 3 is chosen from 4 doctors, 3 engineers and 2 lawyers. In how many ways can it include at least one doctor and at least one engineer?","options":["48","84","36","54"],"answer":3,"explanation":"All committees: C(9, 3) = 84. No doctor: C(5, 3) = 10. No engineer: C(6, 3) = 20. Neither: C(2, 3) = 0. So 84 − 10 − 20 + 0 = 54.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-377","question":"Two different numbers are chosen at random from 1, 2, …, 30. What is the probability that they differ by at least 10?","options":["2/3","1/3","14/29","7/15"],"answer":2,"explanation":"Pairs a < b with b − a ≥ 10: subtract 9 from b and the condition becomes b' > a with both in 1..21, i.e. C(21, 2) = 210 pairs, out of C(30, 2) = 435. P = 14/29.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-378","question":"How many ordered pairs (x, y) of positive integers satisfy x + y ≤ 10?","options":["55","45","36","100"],"answer":1,"explanation":"Add a slack s ≥ 0: x + y + s = 10 with x, y ≥ 1 is the same as x' + y' + s = 8 with all ≥ 0: C(10, 2) = 45. (Or 1 + 2 + … + 9 = 45.)","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-379","question":"How many solutions in non-negative integers does x + y + z = 10 have with x ≤ y ≤ z?","options":["66","22","14","12"],"answer":2,"explanation":"These are the partitions of 10 into at most 3 parts: for x = 0, (y, z) with y ≤ z: 6; x = 1: 4; x = 2: 3; x = 3: 1. Total 14. 66 counts ordered solutions.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-380","question":"A, B and C take turns tossing a fair coin in that order (A, B, C, A, …). The first to toss a head wins. What is the probability that B wins?","options":["1/3","2/7","1/4","4/7"],"answer":1,"explanation":"Within each round of three tosses the chances of A, B, C winning are 1/2, 1/4, 1/8, in the ratio 4 : 2 : 1, so P(B) = 2/7. (A gets 4/7.)","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-381","question":"A fair die is thrown 4 times. What is the probability of getting at least one six?","options":["2/3","1/1296","671/1296","125/324"],"answer":2,"explanation":"P(no six in 4 throws) = (5/6)⁴ = 625/1296, so P(at least one) = 671/1296 ≈ 0.518. Adding 4 × 1/6 = 2/3 overcounts.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-382","question":"A fair coin is tossed 3 times and X is the number of heads. What is the expected value of X²?","options":["3","9/4","3/2","5/2"],"answer":0,"explanation":"E[X²] = Var(X) + (E[X])² = 3/4 + (3/2)² = 3/4 + 9/4 = 3. Squaring the mean gives the trap 9/4. (Check: (0·1 + 1·3 + 4·3 + 9·1)/8 = 24/8.)","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-383","question":"Two fair dice are thrown. What is the variance of the sum of the two numbers?","options":["35/6","35/12","7","49/6"],"answer":0,"explanation":"One die has variance E[X²] − (E[X])² = 91/6 − 49/4 = 35/12. The dice are independent, so the variances add: 35/12 × 2 = 35/6.","difficulty":"hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-384","question":"Two fair dice are thrown and the total is at least 9. What is the probability that at least one die shows a 6?","options":["7/10","11/36","1/2","3/5"],"answer":0,"explanation":"Totals ≥ 9: (3,6), (4,5), (5,4), (6,3), (4,6), (5,5), (6,4), (5,6), (6,5), (6,6) — 10 outcomes, 7 of which contain a 6. P = 7/10.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-385","question":"Bag A has 3 white and 2 black balls; bag B has 2 white and 3 black. A ball is moved at random from A to B, and then a ball drawn from B turns out to be white. What is the probability that the moved ball was white?","options":["3/5","9/13","1/2","13/30"],"answer":1,"explanation":"Moved white (3/5): B has 3W 3B, P(white) = 1/2. Moved black (2/5): B has 2W 4B, P(white) = 1/3. P(white drawn) = 3/10 + 2/15 = 13/30, and P(moved white | white) = (3/10)/(13/30) = 9/13.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-386","question":"How many subsets of {1, 2, …, 10} (including the empty set) have an odd sum?","options":["1023","256","341","512"],"answer":3,"explanation":"Pair each subset with the one obtained by adding or removing the element 1: this switches the parity of the sum, so exactly half of the 2¹⁰ = 1024 subsets have an odd sum: 512.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-387","question":"How many subsets of {1, 2, …, 10} (including the empty set) have a sum divisible by 3?","options":["341","344","342","352"],"answer":1,"explanation":"Elements by remainder: 0 → {3, 6, 9}, 1 → {1, 4, 7, 10}, 2 → {2, 5, 8}. With ω a cube root of unity, the count is (2¹⁰ + 2 Re[2³(1 + ω)⁴(1 + ω²)³])/3 = (1024 + 8)/3 = 344. The naive 1024/3 ≈ 341 is close but not exact because the remainder classes are unequal.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-388","question":"Five people sit in a row of 8 chairs. In how many ways can they sit if chairs 1 and 8 (the two end chairs) must stay empty?","options":["6720","120","56","720"],"answer":3,"explanation":"Only chairs 2 to 7 (six chairs) may be used: 6P5 = 720 ways. 6720 = 8P5 ignores the rule.","difficulty":"moderate","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-389","question":"Three identical black beads and five identical white beads are placed on a circular ring at equally spaced positions. Two arrangements are the same if one can be rotated into the other. How many different arrangements are there?","options":["56","7","8","6"],"answer":1,"explanation":"There are C(8, 3) = 56 placements. Since gcd(3, 8) = 1, no rotation other than the identity maps an arrangement to itself, so the 56 split into orbits of exactly 8: 56/8 = 7.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-390","question":"Four fair coins are tossed. Given that at least one shows heads, what is the probability that the numbers of heads and tails are equal?","options":["2/5","3/8","1/2","1/4"],"answer":0,"explanation":"Outcomes with at least one head: 16 − 1 = 15. Exactly 2 heads: C(4, 2) = 6. P = 6/15 = 2/5. 3/8 ignores the condition.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-391","question":"A fair die is rolled 3 times. What is the probability that the results never decrease (each roll is at least the previous one)?","options":["5/54","7/27","1/6","1/2"],"answer":1,"explanation":"Non-decreasing triples correspond to choosing 3 values from 6 with repetition: C(8, 3) = 56. P = 56/216 = 7/27. 5/54 = 20/216 is the strictly increasing case.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-392","question":"How many 3-digit numbers have at least one digit equal to 0?","options":["171","180","100","81"],"answer":0,"explanation":"3-digit numbers with no zero: 9 × 9 × 9 = 729. So 900 − 729 = 171 contain a 0. 180 = 9 × 10 × 2 counts numbers like 100 twice.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-393","question":"In how many ways can the letters of the word INTERNET be arranged so that the two T's are not together AND the two N's are not together?","options":["2880","5040","2520","2160"],"answer":0,"explanation":"INTERNET has E, N, T twice each: 8!/(2!)³ = 5040. TT together: 7!/(2! 2!) = 1260; NN together: 1260; both: 6!/2! = 360. 5040 − 2520 + 360 = 2880.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-394","question":"In how many ways can 6 different balls be put into 3 different boxes so that each box gets exactly 2 balls?","options":["15","729","540","90"],"answer":3,"explanation":"Choose 2 balls for box 1, 2 of the remaining 4 for box 2, and the last 2 go to box 3: C(6, 2) × C(4, 2) = 15 × 6 = 90. 15 would be the count if the boxes were identical.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-395","question":"In how many ways can 6 different balls be split into 3 identical boxes so that each box gets exactly 2 balls?","options":["90","30","45","15"],"answer":3,"explanation":"With labelled boxes it would be 6!/(2! 2! 2!) = 90; the 3 boxes are interchangeable, so divide by 3! = 6: 15. (Equivalently 5 × 3 × 1 pairings.)","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-396","question":"Five cards are dealt from a standard pack. How many 5-card hands contain at least one card of every suit?","options":["685464","2856100","1370928","28561"],"answer":0,"explanation":"With 5 cards and 4 suits, exactly one suit appears twice. Choose that suit (4), its 2 cards (C(13, 2) = 78), and one card from each of the other three suits (13³): 4 × 78 × 2197 = 685464. Picking one card of each suit (13⁴) and then any fifth card (48) gives 1370928, which counts every hand twice.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-397","question":"Five cards are dealt from a well-shuffled pack. What is the probability that all five are of the same suit?","options":["33/16660","1/4⁴","1/2548","11/4165"],"answer":0,"explanation":"Choose the suit (4) and 5 of its 13 cards: 4 × 1287 = 5148 hands, out of 2598960: P = 33/16660 ≈ 0.002. (1/4)⁴ = 1/256 treats the draws as independent with replacement.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-398","question":"A pair of dice is thrown twice. What is the probability that the total on the second throw is greater than the total on the first?","options":["1/2","5/12","73/648","575/1296"],"answer":3,"explanation":"P(both totals equal) = Σ (ways for total k)²/1296 = (1 + 4 + 9 + 16 + 25 + 36 + 25 + 16 + 9 + 4 + 1)/1296 = 146/1296. By symmetry the rest splits evenly: (1 − 146/1296)/2 = 575/1296.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-399","question":"A 2-digit number (10 to 99) is chosen at random. What is the probability that its two digits differ by exactly 3?","options":["13/90","7/45","1/6","2/15"],"answer":0,"explanation":"Tens digit 1 → 4; 2 → 5; 3 → 0, 6; 4 → 1, 7; 5 → 2, 8; 6 → 3, 9; 7 → 4; 8 → 5; 9 → 6. That is 13 numbers: P = 13/90.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-400","question":"Three people are chosen at random. Assuming each is equally likely to be born on any day of the week, what is the probability that they were born on three different days?","options":["5/7","30/49","1/7","20/49"],"answer":1,"explanation":"The first can be any day, the second must differ (6/7), the third must differ from both (5/7): (6/7)(5/7) = 30/49.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-401","question":"Five people are chosen at random. Each is equally likely to be born on any of the 7 days of the week. What is the expected number of pairs of people born on the same day?","options":["5/7","10/7","1","5/49"],"answer":1,"explanation":"There are C(5, 2) = 10 pairs, and each pair shares a day with probability 1/7. By linearity, the expected number of matching pairs is 10/7 ≈ 1.43.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-402","question":"A team of 11 is chosen from 15 players. Two particular players must be in the team and one particular player must be left out. In how many ways can the team be chosen?","options":["1365","286","220","495"],"answer":2,"explanation":"Put the 2 in and remove the 1: 9 more players are chosen from the remaining 12: C(12, 9) = C(12, 3) = 220. 1365 = C(15, 11) ignores the conditions.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-403","question":"How many positive divisors does 12! have?","options":["540","792","396","1584"],"answer":1,"explanation":"12! = 2¹⁰ × 3⁵ × 5² × 7 × 11 (powers of 2: 6 + 3 + 1 = 10; of 3: 4 + 1 = 5). Divisors: 11 × 6 × 3 × 2 × 2 = 792.","difficulty":"hard","source":"CAT · Infosys SP"},
  {"id":"apt-pnc-probability-404","question":"How many ODD positive divisors does 12! have?","options":["72","396","66","144"],"answer":0,"explanation":"Odd divisors use no factor 2: from 3⁵ × 5² × 7 × 11 there are 6 × 3 × 2 × 2 = 72.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-405","question":"3 different maths books, 2 different physics books and 4 different chemistry books are put on a shelf. In how many arrangements are the maths books together, the physics books together and the chemistry books together?","options":["288","1728","362880","864"],"answer":1,"explanation":"Arrange the 3 subject blocks (3! = 6), then the books inside each block: 3! × 2! × 4! = 288. Total 6 × 288 = 1728. 288 forgets to order the blocks.","difficulty":"moderate","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-406","question":"3 different maths books, 2 different physics books and 4 different chemistry books are put on a shelf. In how many arrangements are the 3 maths books together (the others may be anywhere)?","options":["5040","1728","30240","60480"],"answer":2,"explanation":"Glue the 3 maths books into one block: 1 block + 6 other books = 7 units, arranged in 7! = 5040 ways, and the block's inside in 3! = 6 ways: 30240.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-407","question":"Five fair dice are thrown. What is the probability that the total is exactly 6?","options":["1/7776","5/7776","1/1296","6/7776"],"answer":1,"explanation":"Each die shows at least 1, so a total of 6 means four dice show 1 and one die shows 2: 5 outcomes (which die shows the 2). P = 5/6⁵ = 5/7776.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-408","question":"Ten points lie in a plane; exactly 4 of them are on one straight line and no other three are collinear. How many quadrilaterals can be formed with vertices among these points?","options":["210","209","185","195"],"answer":2,"explanation":"A choice of 4 points fails if 3 or 4 of them lie on the line: C(4, 4) + C(4, 3) × C(6, 1) = 1 + 24 = 25. So 210 − 25 = 185. Removing only the 1 all-collinear choice gives 209.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-409","question":"In how many arrangements of the letters of LEADER are the three vowels (E, A, E) NOT all together?","options":["288","72","360","240"],"answer":0,"explanation":"Total arrangements: 6!/2! = 360. Vowels together: treat EAE as a block with L, D, R: 4! × 3!/2! = 72. So 360 − 72 = 288.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-410","question":"Two players play a best-of-5 match (first to 3 wins); each game is a fair 50–50. Given that Kunal lost the first game, what is the probability that he wins the match?","options":["1/2","3/8","5/16","11/32"],"answer":2,"explanation":"Kunal now needs 3 wins before his rival gets 2 more. Imagine 4 more games: he must win at least 3 of them: (C(4, 3) + C(4, 4))/16 = 5/16.","difficulty":"hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-411","question":"All 27 three-digit numbers whose digits come from {1, 2, 3} (repetition allowed) are written down. What is their sum?","options":["1998","5994","666","6000"],"answer":1,"explanation":"Each digit appears 9 times in each place, so each place adds 9 × (1 + 2 + 3) = 54. Sum = 54 × 111 = 5994.","difficulty":"very-hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-412","question":"How many integers from 1 to 10000 are perfect squares or perfect cubes?","options":["121","100","117","125"],"answer":2,"explanation":"Squares: 100 (1² to 100²). Cubes: 21 (1³ to 21³ = 9261). Both are sixth powers: 1, 64, 729, 4096 (4). So 100 + 21 − 4 = 117. Forgetting the overlap gives 121.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-413","question":"A student guesses all 5 questions of a test, each with 4 options and one correct answer. What is the probability of exactly 3 correct answers?","options":["45/512","9/1024","1/64","15/128"],"answer":0,"explanation":"Binomial: C(5, 3)(1/4)³(3/4)² = 10 × 9/1024 = 90/1024 = 45/512. 9/1024 forgets the C(5, 3) ways to place the correct answers.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-414","question":"A 4-digit number is formed from the digits 1 to 9 with no digit repeated, all such numbers equally likely. What is the probability that it is divisible by 5?","options":["1/5","1/4","2/9","1/9"],"answer":3,"explanation":"Divisible by 5 means the last digit is 5 (0 is not available). By symmetry the last digit is equally likely to be any of the 9 digits, so P = 1/9.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-415","question":"Each cell of a 3 × 3 grid is filled with 0 or 1. In how many fillings does every row AND every column have an odd sum?","options":["64","8","512","16"],"answer":3,"explanation":"Fill the top-left 2 × 2 block freely (2⁴ = 16 ways); the last entry of each of the first two rows and columns is then forced, and the corner cell works out consistently for both its row and column. So 16. Only the rows odd would give 4³ = 64.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-416","question":"8 people sit around a round table. In how many seatings do three particular people sit together (in any order)? (Rotations count as the same.)","options":["4320","240","720","1440"],"answer":2,"explanation":"Glue the 3 into one block: 6 units around the table in (6 − 1)! = 120 ways, and the block in 3! = 6 internal orders: 720.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-417","question":"4 married couples stand in a row so that every husband stands next to his own wife. How many arrangements are possible?","options":["384","24","96","40320"],"answer":0,"explanation":"Treat each couple as a block: 4! = 24 orders of blocks, and each couple can stand in 2 orders: 2⁴ = 16. Total 384. 24 forgets the order inside each couple.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-418","question":"Two cards are drawn one after another without replacement from a pack of 52. Given that the first card is a face card (J, Q or K), what is the probability that the second card is a king?","options":["11/153","1/13","4/51","3/51"],"answer":0,"explanation":"If the first face card is a king (4 of 12 cases) only 3 kings remain; if it is a J or Q (8 of 12) all 4 remain: (4/12)(3/51) + (8/12)(4/51) = (12 + 32)/612 = 11/153. 4/51 forgets the first case.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-419","question":"Three vertices of a regular octagon are chosen at random. What is the probability that they form an isosceles triangle?","options":["1/2","2/7","4/7","3/7"],"answer":3,"explanation":"Each vertex is the apex of 3 isosceles triangles (equal sides 1, 2 or 3 steps; 4 steps would make the base vertices coincide), so 8 × 3 = 24, and none is equilateral since 3 does not divide 8. P = 24/56 = 3/7.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-420","question":"In how many ways can 3 different numbers be chosen from 1, 2, …, 9 so that their sum is 10?","options":["8","4","6","3"],"answer":1,"explanation":"List with a < b < c: (1, 2, 7), (1, 3, 6), (1, 4, 5), (2, 3, 5). That is 4.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-421","question":"Two different numbers are chosen from 1, 2, …, 50. In how many ways can they be chosen so that their product is a perfect square?","options":["21","36","44","52"],"answer":2,"explanation":"ab is a square exactly when a and b have the same square-free part. Group 1..50 by it: k = 1 (7 squares) → C(7, 2) = 21; k = 2 (2, 8, 18, 32, 50) → 10; k = 3 (3, 12, 27, 48) → 6; k = 5 (5, 20, 45) → 3; k = 6, 7, 10, 11 (two numbers each) → 1 each. Total 21 + 10 + 6 + 3 + 4 = 44. 21 counts only pairs of squares.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-422","question":"A fair die is rolled until each of the three even faces 2, 4 and 6 has appeared at least once. What is the expected number of rolls?","options":["7","33/2","11","6"],"answer":2,"explanation":"While k of the three even faces are still missing, a roll hits a new one with probability k/6, taking 6/k rolls on average: 6/3 + 6/2 + 6/1 = 2 + 3 + 6 = 11.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-423","question":"Three fair dice are rolled. What is the probability that all three numbers are different AND their sum is 10?","options":["1/8","5/72","1/24","1/12"],"answer":3,"explanation":"Sets of three different numbers with sum 10: {1, 3, 6}, {1, 4, 5}, {2, 3, 5}. Each can appear in 3! = 6 orders: 18 outcomes. P = 18/216 = 1/12. 1/8 = 27/216 is the chance of a sum of 10 without the 'different' condition.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-424","question":"How many 6-digit numbers contain the digit 7 exactly twice?","options":["98415","91125","72900","131220"],"answer":1,"explanation":"First digit 7: one more 7 among the other 5 places (5 ways) and 9⁴ for the rest: 32805. First digit not 7 (1–9 except 7: 8 ways): two 7's among the other 5 places (C(5, 2) = 10) and 9³ for the rest: 58320. Total 91125.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-425","question":"8 identical coins are given to 4 children so that exactly one child gets nothing. In how many ways can this be done?","options":["21","165","56","84"],"answer":3,"explanation":"Choose the child who gets nothing (4 ways); the other 3 must each get at least 1, so x + y + z = 8 in positive integers: C(7, 2) = 21. Total 84.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-426","question":"In how many ways can 3 different numbers be chosen from 1, 2, …, 15 so that their sum is 24?","options":["19","25","30","21"],"answer":1,"explanation":"List by the smallest number a (a < b < c ≤ 15): a = 1 → (8, 15) … (11, 12), 4 ways; a = 2 → 4; a = 3 → 5; a = 4 → 5; a = 5 → 4; a = 6 → 2; a = 7 → (8, 9) only, 1. Total 25.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-427","question":"A token moves from (0, 0) to (4, 4) by unit steps right or up. How many paths touch the line y = x only at the start and the end?","options":["10","14","5","70"],"answer":0,"explanation":"After the first step the path stays strictly on one side. Paths staying strictly below until the end number C₃ = 5 (Catalan), and the same above: 10. 14 = C₄ counts paths that may touch the diagonal.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-428","question":"A biased coin shows heads with probability 1/3. It is tossed 5 times. What is the probability of at least two heads?","options":["13/16","112/243","131/243","80/243"],"answer":2,"explanation":"P(0 heads) = (2/3)⁵ = 32/243; P(1 head) = 5(1/3)(2/3)⁴ = 80/243. So P(at least 2) = 1 − 112/243 = 131/243. 13/16 is the fair-coin answer.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-429","question":"How many integers from 1 to 100 are divisible by exactly one of 2, 3 and 5?","options":["103","74","55","48"],"answer":3,"explanation":"Let N1 = 50 + 33 + 20 = 103 (single conditions), N2 = 16 + 10 + 6 = 32 (pairs: 6, 10, 15), N3 = 3 (multiples of 30). Exactly one = N1 − 2N2 + 3N3 = 103 − 64 + 9 = 48. 74 = N1 − N2 + N3 counts 'at least one'.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-430","question":"How many 5-card hands from a standard pack contain exactly 3 hearts?","options":["211926","286","741","22308"],"answer":0,"explanation":"Choose 3 of the 13 hearts (286) and 2 of the 39 non-hearts (741): 286 × 741 = 211926.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-431","question":"The letters of EQUATION are rearranged. In how many arrangements do the consonants Q, T, N appear in the same relative order as in EQUATION (Q before T before N, not necessarily together)?","options":["40320","720","6720","1440"],"answer":2,"explanation":"Of the 8! arrangements, the 3 consonants appear in each of their 3! relative orders equally often, so exactly 1/6 keep Q, T, N in order: 40320/6 = 6720.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-432","question":"Three different days are chosen at random from Monday to Sunday (one week, not wrapping round). What is the probability that no two chosen days are consecutive?","options":["2/7","1/7","3/7","4/35"],"answer":0,"explanation":"Selections of 3 from 7 in a line with no two adjacent: C(7 − 3 + 1, 3) = C(5, 3) = 10, out of C(7, 3) = 35. P = 2/7.","difficulty":"hard","source":"TCS NQT Advanced · Infosys SP"},
  {"id":"apt-pnc-probability-433","question":"7 people sit around a round table. In how many seatings are two particular people NOT next to each other? (Rotations count as the same.)","options":["240","480","600","4800"],"answer":1,"explanation":"All seatings: 6! = 720. The two together: glue them (5! = 120) × 2 orders = 240. Not together: 720 − 240 = 480.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-434","question":"3 boys and 3 girls sit in a row of 6 chairs at random. What is the probability that no two girls sit next to each other?","options":["1/20","1/10","1/5","2/5"],"answer":2,"explanation":"Seat the boys (3! ways), leaving 4 gaps; the girls take 3 of them in order: 4P3 = 24. Favourable 6 × 24 = 144 of 720: P = 1/5.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-435","question":"Four cards are drawn together from a pack of 52. Given that at least one of them is an ace, what is the probability that exactly two are aces?","options":["6768/270725","6768/76145","1/4","24/1081"],"answer":1,"explanation":"Exactly two aces: C(4, 2) × C(48, 2) = 6 × 1128 = 6768 hands. At least one ace: C(52, 4) − C(48, 4) = 270725 − 194580 = 76145. P = 6768/76145 ≈ 0.089. Dividing by all 270725 hands ignores the condition.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-436","question":"How many 3-element subsets of {1, 2, …, 12} contain at least one multiple of 3?","options":["56","120","136","164"],"answer":3,"explanation":"There are C(12, 3) = 220 subsets, and C(8, 3) = 56 of them use only the 8 non-multiples of 3. So 220 − 56 = 164. 56 is the complement itself.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-437","question":"A 3 × 3 grid of unit squares is drawn. How many rectangles in it (formed by grid lines) are NOT squares?","options":["22","36","14","18"],"answer":0,"explanation":"All rectangles: C(4, 2) × C(4, 2) = 36. Squares: 9 + 4 + 1 = 14. Non-square rectangles: 22.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-438","question":"4 balls are thrown at random into 4 boxes, each ball independently equally likely to land in any box. What is the expected number of empty boxes?","options":["1","3/4","81/64","27/64"],"answer":2,"explanation":"A given box stays empty with probability (3/4)⁴ = 81/256, so by linearity the expected number of empty boxes is 4 × 81/256 = 81/64 ≈ 1.27.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-439","question":"4 balls are thrown at random into 4 boxes, each ball independently equally likely to land in any box. What is the probability that every box gets exactly one ball?","options":["1/4","3/32","1/24","1/35"],"answer":1,"explanation":"Favourable: 4! = 24 of the 4⁴ = 256 equally likely outcomes, so 3/32. 1/35 = 1/C(7, 3) wrongly treats the identical-ball distributions as equally likely.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-440","question":"How many distinct arrangements of the letters of ASSESSMENT are there?","options":["151200","75600","37800","302400"],"answer":1,"explanation":"ASSESSMENT has 10 letters with S four times and E twice: 10!/(4! 2!) = 3628800/48 = 75600.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-441","question":"The letters of ASSESSMENT are arranged at random. What is the probability that the arrangement begins AND ends with S?","options":["4/25","1/5","4/45","2/15"],"answer":3,"explanation":"The first letter is an S with probability 4/10 and, given that, the last is one of the remaining 3 S's out of 9 letters: (4/10)(3/9) = 2/15. 4/25 = (4/10)² treats the positions as independent.","difficulty":"very-hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-442","question":"A box has 3 red, 4 green and 5 blue balls, all different. In how many ways can 2 balls of DIFFERENT colours be chosen?","options":["66","60","47","19"],"answer":2,"explanation":"Red–green 12, green–blue 20, red–blue 15: total 47. Equivalently C(12, 2) − (C(3, 2) + C(4, 2) + C(5, 2)) = 66 − 19 = 47.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-443","question":"Three balls are drawn together at random from a box with 3 red, 4 green and 5 blue balls. What is the expected number of different colours among the three?","options":["2","9/4","3","97/44"],"answer":3,"explanation":"E = Σ P(colour present). P(no red) = C(9, 3)/C(12, 3) = 84/220, P(no green) = 56/220, P(no blue) = 35/220. So E = 3 − 175/220 = 3 − 35/44 = 97/44 ≈ 2.2.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-444","question":"How many ordered triples (A, B, C) of subsets of {1, 2, 3, 4} satisfy A ∪ B ∪ C = {1, 2, 3, 4} and A ∩ B ∩ C = ∅?","options":["1296","4096","81","2401"],"answer":0,"explanation":"For each element, the sets containing it must be non-empty (union) and not all three (empty intersection): 2³ − 2 = 6 choices. Independently for 4 elements: 6⁴ = 1296.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-445","question":"How many positive integers less than 1000 have digits that add up to 5?","options":["15","35","20","21"],"answer":3,"explanation":"Write each number as a 3-digit string with leading zeros: a + b + c = 5 with digits 0–9 (no limit binds), C(7, 2) = 21 solutions, and 000 is not among them.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-446","question":"The 52 cards of a pack are dealt equally among 4 players. What is the probability that a particular player gets all four aces?","options":["1/256","1/13","4/4165","11/4165"],"answer":3,"explanation":"Her 13 cards are a random 13 of 52. Containing all 4 aces means her other 9 come from the 48 non-aces: C(48, 9)/C(52, 13) = (13 × 12 × 11 × 10)/(52 × 51 × 50 × 49) = 11/4165. 1/256 = (1/4)⁴ treats the aces as independent.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-447","question":"Two fair dice are thrown. What is the probability that the product of the two numbers is at least 15?","options":["13/36","1/3","5/18","7/18"],"answer":0,"explanation":"Products ≥ 15: (3,5), (3,6), (4,4), (4,5), (4,6), (5,3), (5,4), (5,5), (5,6), (6,3), (6,4), (6,5), (6,6) — 13 outcomes. P = 13/36.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-448","question":"In how many arrangements of 1, 2, 3, 4, 5, 6 in a row are 1 and 2 NOT next to each other and 3 and 4 NOT next to each other?","options":["240","336","480","384"],"answer":1,"explanation":"Total 720. 1, 2 together: 2 × 5! = 240; 3, 4 together: 240; both pairs together: 2 × 2 × 4! = 96. 720 − 480 + 96 = 336.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-449","question":"A permutation of 1, 2, …, 6 is written in a row. What is the expected number of places where two neighbouring entries are consecutive numbers (like 4 5 or 5 4)?","options":["5/6","1","5/3","5/2"],"answer":2,"explanation":"Each of the 5 value pairs {k, k + 1} sits side by side with probability 2 × 5!/6! = 1/3. By linearity, E = 5 × 1/3 = 5/3.","difficulty":"very-hard","source":"Goldman Sachs OA · CAT"},
  {"id":"apt-pnc-probability-450","question":"Shortest grid paths go from (0, 0) to (3, 3) by unit steps right or up. How many of them pass through (1, 1) or (2, 2) (or both)?","options":["24","16","8","20"],"answer":1,"explanation":"Through (1, 1): 2 × C(4, 2) = 12. Through (2, 2): C(4, 2) × 2 = 12. Through both: 2 × 2 × 2 = 8. Union: 12 + 12 − 8 = 16.","difficulty":"hard","source":"CAT · Amazon OA"},
  {"id":"apt-pnc-probability-451","question":"A fair coin is tossed repeatedly. What is the probability that the third head appears before the second tail?","options":["1/2","3/8","5/16","11/16"],"answer":2,"explanation":"Within the first 4 tosses either 3 heads or 2 tails must occur first. The third head comes first exactly when at least 3 of those 4 tosses are heads: (C(4, 3) + C(4, 4))/16 = 5/16.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-452","question":"How many strings of length 6 over the letters A, B, C have no two neighbouring letters equal?","options":["96","729","120","48"],"answer":0,"explanation":"The first letter has 3 choices and every later letter must differ from the one before it: 2 choices each. 3 × 2⁵ = 96.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-453","question":"A bag has 2 red balls and some blue balls. When two balls are drawn together at random, the probability that both are red is 1/15. How many blue balls are there?","options":["4","13","5","3"],"answer":0,"explanation":"P(both red) = 1/C(n + 2, 2) = 1/15, so C(n + 2, 2) = 15 and n + 2 = 6: n = 4 blue balls. 13 comes from wrongly using n + 2 = 15.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-454","question":"40% of a firm's staff are engineers. Half of the engineers and a quarter of the others attended a workshop. A person who attended is chosen at random. What is the probability that this person is an engineer?","options":["2/5","1/2","4/7","2/3"],"answer":2,"explanation":"P(engineer and attended) = 0.4 × 0.5 = 0.2; P(other and attended) = 0.6 × 0.25 = 0.15. P(engineer | attended) = 0.2/0.35 = 4/7.","difficulty":"hard","source":"CAT · TCS NQT Advanced"},
  {"id":"apt-pnc-probability-455","question":"A 4-digit number (1000 to 9999) is chosen at random. What is the probability that its digits are strictly increasing from left to right?","options":["7/500","21/1000","1/24","7/450"],"answer":0,"explanation":"Strictly increasing digits cannot include 0 (it would have to lead), so each choice of 4 digits from 1 to 9 gives one number: C(9, 4) = 126. P = 126/9000 = 7/500.","difficulty":"hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-456","question":"Four friends each pick, independently and at random, one of 4 different restaurants. What is the probability that exactly two restaurants are chosen (by at least one friend each)?","options":["3/8","21/64","9/16","3/32"],"answer":1,"explanation":"Choose the 2 restaurants (C(4, 2) = 6) and map the 4 friends onto both of them: 2⁴ − 2 = 14 ways. 6 × 14 = 84 of 256: P = 21/64.","difficulty":"very-hard","source":"CAT · Goldman Sachs OA"},
  {"id":"apt-pnc-probability-457","question":"In how many ways can the letters of DAUGHTER be arranged so that the vowels (A, U, E) always come together?","options":["720","40320","1440","4320"],"answer":3,"explanation":"Treat AUE as one block: 6 units (block + D, G, H, T, R) in 6! = 720 ways, times 3! = 6 orders inside the block: 4320.","difficulty":"hard","source":"TCS NQT · Accenture"},
  {"id":"apt-pnc-probability-458","question":"In how many ways can the letters of DAUGHTER be arranged so that no two vowels (A, U, E) are next to each other?","options":["4320","14400","36000","2400"],"answer":1,"explanation":"Arrange the 5 consonants (5! = 120), creating 6 gaps; put the 3 vowels into 3 different gaps in order: 6P3 = 120. Total 14400.","difficulty":"very-hard","source":"TCS NQT Advanced · CAT"},
  {"id":"apt-pnc-probability-459","question":"A fair die is thrown twice. Given that the first throw is greater than the second, what is the probability that the first throw is a 6?","options":["1/3","1/6","1/2","5/36"],"answer":0,"explanation":"Outcomes with first > second: 15. Those with first = 6: (6, 1) … (6, 5), 5 of them. P = 5/15 = 1/3.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-460","question":"Six interns, including Tom, Riya and Sam, are to sit in a row of 6 desks. Tom insists on an end desk, and Riya and Sam refuse to sit at adjacent desks. In how many ways can the six be seated?","options":["144","240","192","72"],"answer":0,"explanation":"Tom has 2 end desks; the other 5 occupy a block of 5 consecutive desks, where Riya and Sam are adjacent in 2 × 4! = 48 of the 5! = 120 orders, leaving 72. Total = 2 × 72 = 144. 192 subtracts only one order of the adjacent pair; 72 forgets Tom's two choices.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-461","question":"Five married couples attend a reunion. Each person shakes hands once with every other person except his or her own spouse. How many handshakes take place?","options":["45","40","35","80"],"answer":1,"explanation":"All pairs of the 10 people give 10C2 = 45 handshakes; remove the 5 spouse pairs to get 40. 35 removes each couple twice, and 80 counts every handshake from both sides (10 × 8).","difficulty":"moderate","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-462","question":"At the end of a workshop, the 20 participants' ID badges are handed back in a completely random order, one badge per person. What is the expected number of participants who get their own badge back?","options":["1/20","1/e ≈ 0.37","1","20/e ≈ 7.36"],"answer":2,"explanation":"Each person gets their own badge with probability 1/20; by linearity of expectation the expected count is 20 × 1/20 = 1, whatever the number of people. 1/e ≈ 0.37 is the probability that NOBODY gets their own badge, not an expected count.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-pnc-probability-463","question":"A staircase has 8 steps. Kavya climbs it taking 1, 2 or 3 steps at a time, in any order. In how many different ways can she reach the top?","options":["34","44","149","81"],"answer":3,"explanation":"If w(n) is the number of ways for n steps, the last move is 1, 2 or 3 steps, so w(n) = w(n−1) + w(n−2) + w(n−3) with w(0) = 1: 1, 1, 2, 4, 7, 13, 24, 44, 81. 34 allows only 1- and 2-steps (Fibonacci); 44 and 149 are the neighbouring terms read off at the wrong index.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-464","question":"A 4-member committee is to be formed from 5 married couples so that it contains exactly one married couple. In how many ways can this be done?","options":["120","130","140","240"],"answer":0,"explanation":"Choose the couple (5 ways), then 2 more people from the other 4 couples who are not themselves a couple: 8C2 − 4 = 24. Total 5 × 24 = 120. 140 forgets to exclude a second couple; 130 counts 'at least one couple' (210 − 80).","difficulty":"hard","source":"Infosys · CAT"},
  {"id":"apt-pnc-probability-465","question":"Two cards are drawn together from a well-shuffled pack of 52. What is the probability that they are of the same suit or of the same rank?","options":["4/17","5/17","4/13","1/17"],"answer":1,"explanation":"Fix the first card: of the other 51, 12 share its suit and 3 share its rank, and no card can do both, so P = 15/51 = 5/17. 4/13 (= 1/4 + 1/13 − 1/52) treats the draw as with replacement; 4/17 counts only the same suit.","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-466","question":"Two fair dice are thrown and the product of the numbers is found to be even. What is the probability that their sum is also even?","options":["1/2","1/4","1/3","2/3"],"answer":2,"explanation":"Product even means not both odd: 36 − 9 = 27 outcomes. The sum is even only if both are even (both odd is excluded): 9 outcomes. So 9/27 = 1/3. 1/4 forgets to condition (9/36); 2/3 is the chance the sum is odd.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-467","question":"Call a 3-digit number a 'peak' if its middle digit is strictly greater than both its first and last digits (for example 152 or 470). How many 3-digit peaks are there?","options":["204","285","120","240"],"answer":3,"explanation":"For middle digit b, the first digit can be 1 to b − 1 (b − 1 ways) and the last 0 to b − 1 (b ways), so the total is Σ b(b − 1) for b = 2 to 9 = 2 + 6 + 12 + 20 + 30 + 42 + 56 + 72 = 240. 204 wrongly forbids a last digit 0; 285 allows a leading 0.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-468","question":"How many distinct arrangements can be made of all the letters of the word BOOKKEEPER?","options":["151200","453600","302400","604800"],"answer":0,"explanation":"10 letters with O twice, K twice and E three times: 10!/(2! × 2! × 3!) = 3628800/24 = 151200. 453600 treats E as appearing twice; 604800 divides only by 3!.","difficulty":"moderate","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-469","question":"The letters of BOOKKEEPER are arranged at random. What is the probability that the three E's come together?","options":["1/90","1/15","4/15","1/120"],"answer":1,"explanation":"The three E's occupy 3 of the 10 positions, all C(10, 3) = 120 choices equally likely, and 8 of them are consecutive blocks: 8/120 = 1/15. 1/90 (8!/10!) forgets that the other repeated letters cancel equally; 1/120 allows only one block position.","difficulty":"hard","source":"Accenture · CAT"},
  {"id":"apt-pnc-probability-470","question":"A fair die is rolled three times. What is the probability that the largest of the three numbers is exactly 4?","options":["8/27","1/8","37/216","1/6"],"answer":2,"explanation":"P(max ≤ 4) − P(max ≤ 3) = (4³ − 3³)/216 = (64 − 27)/216 = 37/216. 8/27 is P(max ≤ 4) and 1/8 is P(max ≤ 3), each only half of the subtraction.","difficulty":"moderate","source":"Infosys · Capgemini"},
  {"id":"apt-pnc-probability-471","question":"A fair die is rolled again and again until some number appears that has already appeared before. What is the expected number of rolls, counting the roll that produces the repeat?","options":["7/2","4","899/324 ≈ 2.77","1223/324 ≈ 3.77"],"answer":3,"explanation":"E = Σ P(no repeat in the first k rolls) for k = 0 to 6 = 1 + 1 + 30/36 + 120/216 + 360/1296 + 720/7776 + 720/46656 = 1223/324 ≈ 3.77. 899/324 leaves out the repeating roll itself; 4 is the roll by which a repeat becomes more likely than not (the median), not the mean.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-472","question":"A 3-person panel is picked at random from 4 senior and 6 junior engineers. Given that the panel has at least one senior engineer, what is the probability that it has exactly one?","options":["3/5","1/2","5/6","2/5"],"answer":0,"explanation":"Exactly one senior: 4 × 6C2 = 60 panels; at least one: 10C3 − 6C3 = 120 − 20 = 100. So 60/100 = 3/5. 1/2 is the unconditional 60/120; 5/6 is P(at least one senior).","difficulty":"hard","source":"Accenture · TCS NQT"},
  {"id":"apt-pnc-probability-473","question":"A 6-digit locker code (digits 0–9, leading 0 allowed) uses exactly two different digits, each appearing exactly three times, such as 727277. How many such codes are there?","options":["1800","900","450","2790"],"answer":1,"explanation":"Choose the two digits: 10C2 = 45; choose the 3 places for the smaller one: 6C3 = 20. Total 900. 1800 picks the digits as an ordered pair (double counting); 2790 = 45 × (2⁶ − 2) allows any split, not 3 and 3.","difficulty":"very-hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-474","question":"20 identical laptops are to be shared among three labs A, B and C. A lab may get none, but Lab A can store at most 5. In how many ways can the laptops be shared?","options":["120","126","111","80"],"answer":2,"explanation":"Without the cap, x + y + z = 20 has 22C2 = 231 solutions; those with A ≥ 6 number 16C2 = 120. So 231 − 120 = 111. 120 is the excluded count itself; 126 uses A ≥ 7 (i.e. a cap of 6); 80 forbids empty labs.","difficulty":"hard","source":"Capgemini · AMCAT"},
  {"id":"apt-pnc-probability-475","question":"A 4 × 4 square array of 16 dots is drawn (rows and columns equally spaced). How many triangles of non-zero area have all three vertices among these dots?","options":["528","520","560","516"],"answer":3,"explanation":"C(16, 3) = 560 triples minus collinear ones: rows 4 × 4C3 = 16, columns 16, the two long diagonals 2 × 4 = 8, and four diagonals of 3 dots 4 × 1 = 4, total 44. 560 − 44 = 516. 528 removes only rows and columns; 520 forgets the 3-dot diagonals.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-476","question":"Five offices stand around a circular courtyard, each next to two others. Each office is painted one of 4 colours so that neighbouring offices differ. In how many ways can this be done (offices are distinguishable)?","options":["240","324","216","246"],"answer":0,"explanation":"For a cycle of n regions and k colours the count is (k − 1)ⁿ + (−1)ⁿ(k − 1) = 3⁵ − 3 = 240. 324 = 4 × 3⁴ treats the offices as a row and ignores the last–first adjacency; 246 gets the sign wrong for odd n.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-477","question":"Two fair dice are thrown together repeatedly until a total of either 6 or 7 appears. What is the probability that a 7 comes first?","options":["5/11","6/11","1/2","1/6"],"answer":1,"explanation":"Throws giving neither total are irrelevant; only the relative chances matter: P(7) = 6/36, P(6) = 5/36, so 7 wins with probability 6/(6 + 5) = 6/11. 5/11 swaps the two; 1/6 is just P(7) on a single throw.","difficulty":"hard","source":"Accenture · CAT"},
  {"id":"apt-pnc-probability-478","question":"A fair coin is tossed until a head is immediately followed by a tail (the pattern HT). What is the expected number of tosses?","options":["6","3","4","8"],"answer":2,"explanation":"First wait for a head (expected 2 tosses); after that, any further heads keep you waiting and the first tail completes HT (another 2 expected). Total 4. 6 is the answer for HH, where a failure (a tail) destroys progress; 8 misapplies 2ⁿ⁺¹.","difficulty":"very-hard","source":"Product company OA · CAT"},
  {"id":"apt-pnc-probability-479","question":"The odds in favour of A solving a puzzle are 3 : 5 and the odds against B solving it are 7 : 2. If they work independently, what is the probability that the puzzle gets solved?","options":["43/72","35/72","1/12","37/72"],"answer":3,"explanation":"P(A) = 3/8 and P(B) = 2/9, so P(neither) = 5/8 × 7/9 = 35/72 and P(solved) = 37/72. 43/72 simply adds the two probabilities; 1/12 is P(both solve it).","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-480","question":"A 4-digit number with all four digits different is chosen at random. What is the probability that it is even?","options":["41/81","1/2","5/9","32/81"],"answer":0,"explanation":"There are 9 × 9 × 8 × 7 = 4536 such numbers. Ending in 0: 9 × 8 × 7 = 504; ending in 2, 4, 6 or 8: 4 × 8 × 8 × 7 = 1792. (504 + 1792)/4536 = 41/81. 1/2 ignores that a 0 at the end frees the first digit; 32/81 forgets the numbers ending in 0.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-pnc-probability-481","question":"A plant has 5 independent machines, each working on a given day with probability 0.9. What is the probability that exactly 3 of them work?","options":["0.00729","0.0729","0.9914","0.729"],"answer":1,"explanation":"5C3 × 0.9³ × 0.1² = 10 × 0.729 × 0.01 = 0.0729. 0.00729 forgets the 5C3 choices of which machines work; 0.9914 is P(at least 3).","difficulty":"moderate","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-482","question":"Three different numbers are chosen at random from 1, 2, …, 20. What is the probability that, arranged in increasing order, they form an arithmetic progression?","options":["3/19","1/76","3/38","9/76"],"answer":2,"explanation":"For common difference d the smallest term can be 1 to 20 − 2d, so there are Σ (20 − 2d) for d = 1 to 9 = 90 such sets, out of 20C3 = 1140: 90/1140 = 3/38. 3/19 counts each progression twice (up and down); 9/76 uses 20 − d starts instead of 20 − 2d.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-483","question":"How many 4-letter arrangements (no letter repeated) can be made from the letters of ALGORITHM that begin with a vowel, end with a consonant and contain the letter M?","options":["756","180","216","306"],"answer":3,"explanation":"Vowels are A, O, I. If M is last: 3 × 7 × 6 = 126. If M is in place 2 or 3: 3 (vowel) × 5 (last consonant other than M) × 2 (M's place) × 6 (the remaining slot) = 180. Total 306. 756 ignores the M condition; 180 forgets that M itself can be the final consonant.","difficulty":"hard","source":"Accenture · TCS NQT"},
  {"id":"apt-pnc-probability-484","question":"Nine trainees are to be split into three groups: two groups of 2 and one group of 5 (the groups are not named). In how many ways can this be done?","options":["378","756","126","1512"],"answer":0,"explanation":"Choose the 5: 9C5 = 126; split the other 4 into two unnamed pairs: 4C2/2! = 3. Total 378. 756 forgets that the two pairs are interchangeable; 126 divides by 3! as if all three groups were the same size.","difficulty":"very-hard","source":"CAT · Capgemini"},
  {"id":"apt-pnc-probability-485","question":"A help desk's morning, evening and night shifts handle 50%, 30% and 20% of its calls, and mishandle 2%, 3% and 5% of their calls respectively. A call picked at random turns out to have been mishandled. What is the probability that it came in during the night shift?","options":["1/2","10/29","1/5","9/29"],"answer":1,"explanation":"P(mishandled) = 0.5 × 0.02 + 0.3 × 0.03 + 0.2 × 0.05 = 0.010 + 0.009 + 0.010 = 0.029, so P(night | mishandled) = 0.010/0.029 = 10/29. 1/2 compares the error rates alone (5 out of 2 + 3 + 5) and ignores how many calls each shift takes.","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-486","question":"All distinct arrangements of the letters of SCHOOL are listed in dictionary order. What is the position of the word SCHOOL itself?","options":["243","183","303","58"],"answer":2,"explanation":"Words starting with C, H or L: 3 × 5!/2! = 180; with O: 5! = 120; so 300 come before S. Then SCH is the earliest start; after it only SCHLOO and SCHOLO precede SCHOOL. Rank = 300 + 2 + 1 = 303. 243 divides the O-branch by 2! as well; 58 counts from the end of the list.","difficulty":"very-hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-487","question":"A 3-digit number (100 to 999) is chosen at random. What is the probability that it is divisible by 7 or by 11, but not by both?","options":["11/50","209/900","13/100","187/900"],"answer":3,"explanation":"Multiples of 7: 128; of 11: 81; of 77: 11. 'Exactly one' = 128 + 81 − 2 × 11 = 187, so 187/900. 11/50 (= 198/900) is 'divisible by 7 or 11', subtracting the overlap only once; 209/900 never subtracts it.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-pnc-probability-488","question":"Five friends draw names from a hat for a gift exchange, and the draw is repeated until nobody has drawn his or her own name. In the final valid draw, what is the probability that the giving forms one single loop through all five (A gives to B, B to C, …, back to A)?","options":["5/11","1/5","6/11","11/30"],"answer":2,"explanation":"A valid draw is a derangement of 5: there are 44, all equally likely. Single 5-cycles number 4! = 24; the rest (20) split as a 2-cycle plus a 3-cycle. So 24/44 = 6/11. 1/5 (= 24/120) forgets to condition on the draw being valid; 11/30 is P(a draw is valid).","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-489","question":"Nine signal flags (4 identical red, 3 identical green and 2 identical blue) are hoisted one above another on a pole. In how many of the possible signals are the top and bottom flags of the same colour?","options":["910","350","315","245"],"answer":1,"explanation":"Both red: the middle 7 hold 2R, 3G, 2B: 7!/(2!3!2!) = 210. Both green: 4R, 1G, 2B: 105. Both blue: 4R, 3G: 35. Total 350. 315 forgets the blue case; 910 is the number of signals whose ends differ (1260 − 350).","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-490","question":"A 4-member review board is chosen from 6 engineers and 4 managers, and one member is made chair. The chair must be a manager and the board must have at least 2 engineers. In how many ways can the board and its chair be chosen?","options":["336","170","420","260"],"answer":3,"explanation":"3 engineers + 1 manager: 6C3 × 4 × 1 (chair) = 80. 2 engineers + 2 managers: 6C2 × 4C2 × 2 (chair) = 180. Total 260. 170 counts boards but forgets the chair choice; 420 (= 4 × 6C2 × 7) picks a 'fourth member' separately and counts boards twice.","difficulty":"hard","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-491","question":"A pack of 52 cards is shuffled and dealt face up. What is the expected number of aces that appear before the first king?","options":["4/5","2","1/2","1"],"answer":0,"explanation":"Look only at the 4 aces and 4 kings. A given ace comes before all 4 kings with probability 1/5 (it must be first among those 5 cards), so by linearity the expected number is 4 × 1/5 = 4/5. 2 uses 1/2, the chance an ace beats ONE particular king.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-492","question":"5 men and 5 women stand in a row in random order. What is the expected number of neighbouring pairs consisting of one man and one woman?","options":["50/9","5/2","5","9/2"],"answer":2,"explanation":"There are 9 neighbouring pairs; each is mixed with probability 2 × (5/10) × (5/9) = 5/9, so the expectation is 9 × 5/9 = 5. 9/2 uses 1/2 (as if positions were independent); 5/2 counts only one order (man then woman); 50/9 uses 10 pairs as in a circle.","difficulty":"very-hard","source":"Product company OA · CAT"},
  {"id":"apt-pnc-probability-493","question":"The letters of INDIANA are arranged at random. What is the probability that no two identical letters are next to each other?","options":["3/7","1/7","64/105","41/105"],"answer":3,"explanation":"Total 7!/(2!2!2!) = 630. Glueing one repeated pair: 6!/(2!2!) = 180 (three ways); two pairs: 5!/2! = 60 (three ways); all three: 4! = 24. Good = 630 − 540 + 180 − 24 = 246, and 246/630 = 41/105. 3/7 forgets the last inclusion–exclusion term; 64/105 is the complement.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-pnc-probability-494","question":"Six colleagues share two different cabs, each of which can carry at most 4 of them. In how many ways can the six be split between the two cabs?","options":["50","64","25","57"],"answer":0,"explanation":"Cab 1 must take 2, 3 or 4 people (otherwise cab 2 gets 5 or more): 6C2 + 6C3 + 6C4 = 15 + 20 + 15 = 50. 64 ignores the capacity; 57 checks the capacity of only one cab; 25 treats the cabs as identical.","difficulty":"hard","source":"Infosys · Wipro"},
  {"id":"apt-pnc-probability-495","question":"A number is picked at random from 1 to 50. What is the probability that it has exactly three positive divisors?","options":["7/50","2/25","3/50","1/10"],"answer":1,"explanation":"Exactly three divisors means n = p² for a prime p: 4, 9, 25, 49, so 4/50 = 2/25. 7/50 counts every perfect square; 3/50 misses 49; 1/10 also counts 1.","difficulty":"moderate","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-496","question":"Two fair dice are thrown. What is the probability that one of the two numbers is a multiple of the other? (Equal numbers count, since each is a multiple of the other.)","options":["7/9","4/9","11/18","7/18"],"answer":2,"explanation":"Ordered pairs (a, b) with b a multiple of a: 6 + 3 + 2 + 1 + 1 + 1 = 14; with a a multiple of b, also 14; the 6 equal pairs are in both, so 14 + 14 − 6 = 22 and 22/36 = 11/18. 7/18 counts one direction only; 7/9 double-counts the equal pairs; 4/9 drops them.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-pnc-probability-497","question":"In a group of 60 trainees, 35 drink tea, 30 drink coffee and 10 drink neither. One trainee is picked at random. What is the probability that he or she drinks exactly one of the two?","options":["1/4","5/6","11/12","7/12"],"answer":3,"explanation":"Those drinking at least one: 60 − 10 = 50, so both = 35 + 30 − 50 = 15 and exactly one = 50 − 15 = 35: 35/60 = 7/12. 1/4 is 'both'; 5/6 is 'at least one'; 11/12 forgets the 10 who drink neither (both = 5).","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-498","question":"A bag has 4 red and 6 blue balls. Two balls are drawn together and turn out to be of the same colour. What is the probability that they are red?","options":["2/7","2/5","4/13","2/15"],"answer":0,"explanation":"Both red: 4C2 = 6 pairs; both blue: 6C2 = 15. Given 'same colour', P(red) = 6/21 = 2/7. 2/5 is just the share of red balls; 4/13 uses draws with replacement (16/(16 + 36)); 2/15 is the unconditional P(both red).","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-499","question":"How many 5-digit numbers have their digits in strictly increasing order from left to right and contain the digit 5?","options":["126","70","56","210"],"answer":1,"explanation":"0 can never appear (it cannot lead and nothing smaller can precede it), so choose 5 digits from 1–9 including 5: 8C4 = 70, each giving one number. 126 = 9C5 drops the 'contains 5' condition; 56 counts those without 5; 210 wrongly lets 0 in.","difficulty":"hard","source":"Infosys · CAT"},
  {"id":"apt-pnc-probability-500","question":"Seven different beads are strung on a bracelet, which can be turned over as well as rotated. In how many distinct bracelets are two particular beads next to each other?","options":["240","60","120","360"],"answer":2,"explanation":"Glue the two beads into one unit: 6 units on a bracelet give (6 − 1)!/2 = 60, and the pair can be ordered 2 ways: 120. 240 forgets that turning the bracelet over gives the same piece; 60 forgets the order inside the pair.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-501","question":"Three different numbers are chosen at random from 1, 2, …, 10. What is the probability that the middle one of the three (the median) is 5?","options":["1/5","3/10","1/8","1/6"],"answer":3,"explanation":"One number from 1–4 (4 ways), the 5, and one from 6–10 (5 ways): 20 sets out of 10C3 = 120, so 1/6. 1/5 lets the larger number come from 5–10; 3/10 is only P(5 is chosen); 1/8 assumes the median is equally likely to be any of 2 to 9.","difficulty":"hard","source":"Accenture · CAT"},
  {"id":"apt-pnc-probability-502","question":"Two numbers are picked one after the other, with replacement, from 1, 2, …, 10. What is the probability that their product is a perfect square?","options":["9/50","1/10","4/25","14/55"],"answer":0,"explanation":"10 equal pairs, plus the unequal pairs {1, 4}, {1, 9}, {4, 9} and {2, 8}, each in 2 orders: 10 + 8 = 18 of 100, so 9/50. 1/10 counts only equal pairs; 4/25 misses {2, 8}; 14/55 counts unordered pairs, which are not equally likely here.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-503","question":"A number is chosen at random from 1 to 1000. What is the probability that it is a multiple of 3 or ends in the digit 3?","options":["433/1000","399/1000","2/5","73/200"],"answer":1,"explanation":"Multiples of 3: 333. Ending in 3: 100. Both: 10k + 3 is divisible by 3 exactly when k is, k = 0, 3, …, 99, i.e. 34 numbers. 333 + 100 − 34 = 399. 433/1000 ignores the overlap; 2/5 uses an overlap of 33; 73/200 removes the overlap twice ('exactly one').","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-504","question":"A café offers 4 starters, 5 main courses and 3 desserts. A customer may order at most one item from each course but must order something. How many different orders are possible?","options":["120","60","119","12"],"answer":2,"explanation":"Each course offers its items or 'none': 5 × 6 × 4 = 120 combinations, minus the empty order: 119. 120 forgets to remove the empty order; 60 forces one item from every course.","difficulty":"moderate","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-505","question":"How many squares (made of whole cells) on an 8 × 8 chessboard contain the centre point of the board strictly inside them, not on their boundary?","options":["84","140","204","44"],"answer":3,"explanation":"The centre is the grid point (4, 4). A k × k square with corner (a, b) needs a < 4 < a + k and 0 ≤ a ≤ 8 − k, and likewise for b. Sizes 1 to 8 give 0, 1, 4, 9, 16, 9, 4, 1 squares: 44. 84 also allows the centre on the boundary; 140 = 1² + … + 7² ignores the board's edges.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-506","question":"Asha and Bunty take turns, Asha first. On her turn Asha rolls a fair die and wins if it shows 6; on his turn Bunty tosses a fair coin and wins if it shows heads. They continue until someone wins. What is the probability that Asha wins?","options":["2/7","5/7","1/6","1/4"],"answer":0,"explanation":"A full round with no winner has probability (5/6)(1/2) = 5/12, so P(Asha) = (1/6)/(1 − 5/12) = (1/6)/(7/12) = 2/7. 1/4 compares the single-turn chances (1/6 against 1/2) as if both played at once; 5/7 is Bunty's chance.","difficulty":"very-hard","source":"Accenture · CAT"},
  {"id":"apt-pnc-probability-507","question":"How many 4-digit numbers have digits whose product is 24?","options":["60","64","120","52"],"answer":1,"explanation":"Digit multisets with product 24: {1,1,3,8}, {1,1,4,6}, {1,2,2,6} (12 orders each), {1,2,3,4} (24 orders) and {2,2,2,3} (4 orders). Total 36 + 24 + 4 = 64. 60 misses {2,2,2,3}; 120 gives every multiset 4! orders.","difficulty":"hard","source":"Infosys · TCS NQT"},
  {"id":"apt-pnc-probability-508","question":"A 4-player relay squad is to be picked from 2 sprinters, 3 middle-distance runners and 4 long-distance runners, with at least one runner of each type. In how many ways can the squad be picked?","options":["144","55","72","91"],"answer":2,"explanation":"All squads: 9C4 = 126. Without sprinters: 7C4 = 35; without middle-distance: 6C4 = 15; without long-distance: 5C4 = 5; squads lacking two types: only the all-long-distance one, 1. Allowed = 126 − 55 + 1 = 72. 144 (= 2 × 3 × 4 × 6) picks one of each and then 'any one more', counting squads twice.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-509","question":"Each interior angle of a regular polygon is 150°. How many diagonals does it have?","options":["66","108","35","54"],"answer":3,"explanation":"Each exterior angle is 30°, so there are 360/30 = 12 sides and 12 × 9/2 = 54 diagonals. 66 = 12C2 also counts the sides; 108 forgets to halve; 35 belongs to a decagon (exterior 36°, interior 144°).","difficulty":"moderate","source":"AMCAT · Wipro"},
  {"id":"apt-pnc-probability-510","question":"A fair charges ₹10 a turn. You roll two fair dice and are paid, in rupees, the product of the two numbers. What is your expected gain per turn?","options":["₹2.25 gain","₹12.25 gain","₹3 loss","No gain or loss (a fair game)"],"answer":0,"explanation":"The dice are independent, so E[product] = 3.5 × 3.5 = 12.25, and the expected gain is 12.25 − 10 = ₹2.25. ₹12.25 forgets the fee; '₹3 loss' uses the expected SUM (7) in place of the product.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-pnc-probability-511","question":"In how many ways can two squares of an 8 × 8 chessboard be chosen so that a knight could move from one to the other in a single move?","options":["336","168","256","84"],"answer":1,"explanation":"Every knight move joins opposite corners of a 3 × 2 or 2 × 3 block of squares. Each block shape fits 6 × 7 = 42 places and holds 2 such moves, so 2 × 2 × 42 = 168 unordered pairs. 336 counts each pair from both ends; 256 assumes every square has 8 knight moves.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-512","question":"Three vertices of a regular 10-sided polygon are joined to form a triangle. How many of these triangles are obtuse-angled?","options":["80","100","60","40"],"answer":2,"explanation":"Of the 10C3 = 120 triangles, 40 are right-angled (a diameter through two opposite vertices: 5 diameters × 8 third points). Acute ones contain the centre: 20. Obtuse = 120 − 40 − 20 = 60. 80 lumps the acute ones in; 100 lumps in everything that is not acute.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-513","question":"How many 3-digit numbers have digits that are either strictly increasing or strictly decreasing from left to right (for example 147 or 950)?","options":["168","240","120","204"],"answer":3,"explanation":"Increasing: 0 cannot be used, so 9C3 = 84. Decreasing: 0 may be the last digit, so 10C3 = 120. Total 204. 168 doubles 84 and misses decreasing numbers ending in 0; 240 doubles 120 and wrongly allows increasing numbers starting with 0.","difficulty":"very-hard","source":"TCS NQT · CAT"},
  {"id":"apt-pnc-probability-514","question":"3 of 10 shareholders are chosen at random to sit on an audit panel. What is the probability that two particular shareholders, Xavier and Yamini, are either both on the panel or both off it?","options":["8/15","1/15","7/15","1/2"],"answer":0,"explanation":"Both on: the third member is any of the other 8: 8 panels. Both off: 8C3 = 56 panels. (8 + 56)/120 = 64/120 = 8/15. 1/15 and 7/15 are the two cases on their own.","difficulty":"hard","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-515","question":"A stick is broken at two points chosen independently and uniformly at random along its length. What is the probability that the three pieces can form a triangle?","options":["1/2","1/4","1/8","3/4"],"answer":1,"explanation":"The pieces form a triangle exactly when every piece is shorter than half the stick. The events 'piece i is at least half' are disjoint and each has probability 1/4, so P = 1 − 3/4 = 1/4. 3/4 is the complement; 1/8 = (1/2)³ wrongly treats the pieces as independent.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-516","question":"A family of six travels in a car with a driver's seat, one front passenger seat and four back seats. Only the two parents can drive, and the youngest child may not sit in either front seat. In how many ways can the six be seated?","options":["240","192","720","144"],"answer":1,"explanation":"Driver: 2 ways (a parent). Front passenger: any of the remaining 5 except the youngest child: 4 ways. Back seats: 4! = 24. Total 2 × 4 × 24 = 192. 240 ignores the child's restriction; 144 also keeps the other parent out of the front passenger seat.","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-517","question":"A fair die is rolled twice and the two numbers add up to 8. What is the probability that the second number is larger than the first?","options":["1/2","5/12","2/5","1/18"],"answer":2,"explanation":"Sum 8: (2,6), (3,5), (4,4), (5,3), (6,2), five equally likely outcomes; the second is larger in (2,6) and (3,5): 2/5. 1/2 ignores the tie (4,4); 5/12 is the unconditional P(second > first); 1/18 = 2/36 forgets to condition.","difficulty":"moderate","source":"Accenture · Wipro"},
  {"id":"apt-pnc-probability-518","question":"A fair die is rolled 5 times. What is the probability of getting at least two sixes?","options":["4651/7776","625/3888","3125/7776","763/3888"],"answer":3,"explanation":"P(no six) = (5/6)⁵ = 3125/7776 and P(exactly one six) = 5 × (1/6)(5/6)⁴ = 3125/7776, so P(at least two) = 1 − 6250/7776 = 1526/7776 = 763/3888. 4651/7776 is 'at least one'; 625/3888 is 'exactly two'.","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-pnc-probability-519","question":"A basket holds 3 identical apples, 4 identical oranges and 2 mangoes of different varieties (so the mangoes can be told apart). In how many ways can a selection of at least one fruit be made?","options":["79","59","80","511"],"answer":0,"explanation":"Apples: 0–3 (4 choices); oranges: 0–4 (5 choices); each mango in or out (2 × 2 = 4). 4 × 5 × 4 − 1 (the empty selection) = 79. 59 treats the mangoes as identical (3 choices); 511 = 2⁹ − 1 treats all nine fruits as different.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-520","question":"A vending machine accepts ₹1, ₹2, ₹5 and ₹10 coins, and a customer has plenty of each. How many different collections of exactly 5 coins can she put in, if only the number of coins of each value matters?","options":["1024","56","126","625"],"answer":1,"explanation":"Counting c₁ + c₂ + c₅ + c₁₀ = 5 in non-negative integers: (5 + 3)C3 = 56. 1024 = 4⁵ counts ordered sequences of coins; 126 = 9C4 mixes up the two numbers in the stars-and-bars formula.","difficulty":"moderate","source":"Infosys · Wipro"},
  {"id":"apt-pnc-probability-521","question":"A 3-digit number (100 to 999) is chosen at random. What is the probability that exactly one of its digits is 7?","options":["27/100","3/10","1/4","9/100"],"answer":2,"explanation":"7 first: 1 × 9 × 9 = 81. 7 in the middle or last: 8 × 9 for the first digit (not 0 or 7) and 9 for the other: 72 each. (81 + 72 + 72)/900 = 225/900 = 1/4. 27/100 lets the first digit be 0 when it is not the 7; 3/10 simply adds 1/10 three times.","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-522","question":"In how many arrangements of the letters of MISSISSIPPI are no two S's next to each other?","options":["34650","1575","176400","7350"],"answer":3,"explanation":"Arrange M, I, I, I, I, P, P first: 7!/(4! 2!) = 105. This leaves 8 gaps (including both ends), from which choose 4 for the identical S's: 8C4 = 70. 105 × 70 = 7350. 1575 uses only the 6 inner gaps; 34650 is the total number of arrangements; 176400 treats the S's as different.","difficulty":"hard","source":"TCS NQT · CAT"},
  {"id":"apt-pnc-probability-523","question":"The numbers 1 to 8 are arranged in a row at random. What is the probability that the odd numbers appear in increasing order and the even numbers in decreasing order (reading left to right, not necessarily next to each other)?","options":["1/576","1/24","1/144","1/70"],"answer":0,"explanation":"The odd numbers' relative order is one of 4! equally likely orders, the even numbers' independently another: (1/24)(1/24) = 1/576. 1/24 handles only one of the two conditions; 1/70 = 1/8C4 confuses it with the choice of which places hold the odd numbers.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-524","question":"Meera takes the bus on 2/3 of days and walks on the rest. She is late on 1/4 of the days she takes the bus and on 1/10 of the days she walks. Today she was late. What is the probability that she took the bus?","options":["2/3","5/6","5/7","1/6"],"answer":1,"explanation":"P(bus and late) = 2/3 × 1/4 = 1/6; P(walk and late) = 1/3 × 1/10 = 1/30. P(bus | late) = (1/6)/(1/6 + 1/30) = 5/6. 2/3 is the prior; 5/7 compares the lateness rates alone; 1/6 is the joint probability.","difficulty":"hard","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-525","question":"A fair coin is tossed until both a head and a tail have appeared. What is the expected number of tosses?","options":["2","4","3","7/2"],"answer":2,"explanation":"The first toss gives one face; after that you wait for the other face, which takes 2 tosses on average (probability 1/2 each toss). 1 + 2 = 3. 2 assumes the second toss always differs; 4 adds two full waits of 2.","difficulty":"hard","source":"Infosys · Product company OA"},
  {"id":"apt-pnc-probability-526","question":"Three fair dice are rolled. What is the probability that the total is at most 5?","options":["1/54","5/54","5/18","5/108"],"answer":3,"explanation":"Totals 3, 4 and 5 arise in 1, 3 and 6 ways (the number of ways for total s is (s − 1)C2), so 10/216 = 5/108. 1/54 stops at total 4; 5/54 includes total 6; 5/18 uses 36 as the denominator.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-527","question":"How many numbers between 3000 and 8000 that are divisible by 5 can be formed with the digits 0–9 if no digit is repeated?","options":["504","560","280","448"],"answer":0,"explanation":"The first digit is 3–7 and the last is 0 or 5. Ending in 0: 5 × 8 × 7 = 280. Ending in 5: the first digit is 3, 4, 6 or 7 (4 ways), so 4 × 8 × 7 = 224. Total 504. 560 lets 5 be both first and last digit; 280 forgets numbers ending in 5.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-pnc-probability-528","question":"A lot of 20 bearings has 4 defective ones. An inspector tests 5 bearings chosen at random and accepts the lot only if none of the 5 is defective. What is the probability that the lot is accepted?","options":["232/323","91/323","1024/3125","455/969"],"answer":1,"explanation":"All 5 must come from the 16 good bearings: 16C5/20C5 = 4368/15504 = 91/323 (about 0.28). 1024/3125 = (4/5)⁵ treats the draws as with replacement; 455/969 is P(exactly one defective); 232/323 is P(rejected).","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-529","question":"The six faces of a cube are to be painted with six different colours, one colour per face. Two colourings are the same if one cube can be rotated to look like the other. How many different cubes can be made?","options":["720","120","30","15"],"answer":2,"explanation":"There are 6! = 720 paintings and the cube has 24 rotations; with all colours different, no rotation fixes a painting, so 720/24 = 30. Equivalently: fix colour 1 on top, choose the bottom (5 ways), then arrange the other 4 around the side up to rotation (3! = 6): 30. 120 divides only by 6; 15 also counts mirror images as the same.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-530","question":"Three fair dice are rolled and at least one of them shows a 6. What is the probability that exactly one of them shows a 6?","options":["25/72","91/216","16/91","75/91"],"answer":3,"explanation":"At least one six: 216 − 125 = 91 outcomes. Exactly one six: 3 × 5 × 5 = 75. So 75/91. 25/72 (= 75/216) does not condition; 16/91 is the chance of two or three sixes.","difficulty":"hard","source":"Accenture · Infosys"},
  {"id":"apt-pnc-probability-531","question":"Five people A, B, C, D, E stand in a queue. A must be somewhere ahead of B, and C must stand immediately behind A. How many queues are possible?","options":["12","24","60","48"],"answer":0,"explanation":"Glue A and C into the block 'AC' (in that order): 4 units, 4! = 24 orders. In exactly half of them the block is ahead of B: 12. 24 drops the A-before-B condition; 60 drops the C condition; 48 allows the block in either order.","difficulty":"hard","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-532","question":"What is the least number of employees a company must have to be sure that at least two of them were born in the same month AND on the same day of the week?","options":["13","85","20","8"],"answer":1,"explanation":"There are 12 × 7 = 84 (month, weekday) combinations, so by the pigeonhole principle 85 people guarantee a repeat. 20 adds 12 + 7 + 1 instead of multiplying; 13 and 8 handle only one of the two conditions.","difficulty":"moderate","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-533","question":"Five fair dice are rolled. What is the probability that exactly three different numbers appear among them?","options":["5/8","245/648","125/324","125/1944"],"answer":2,"explanation":"Choose the 3 values (6C3 = 20), then count rolls using all three: 3⁵ − 3 × 2⁵ + 3 = 150. 20 × 150 = 3000 and 3000/7776 = 125/324. 5/8 (20 × 3⁵) lets some of the three values be missing; 245/648 forgets to add back the 3 one-value rolls.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-534","question":"Consider the statements:\n(i) 5 different balls can be put into 3 different boxes in 3⁵ ways.\n(ii) 5 identical balls can be put into 3 different boxes in 5³ ways.\n(iii) 5 identical balls can be put into 3 identical boxes, with no box empty, in 2 ways.\nWhich of them are correct?","options":["(i) and (ii) only","(iii) only","(i), (ii) and (iii)","(i) and (iii) only"],"answer":3,"explanation":"(i) Each ball picks a box: 3⁵ = 243, correct. (ii) Identical balls: x + y + z = 5 has 7C2 = 21 solutions, not 125, so wrong. (iii) The splits are 3+1+1 and 2+2+1, so 2 ways, correct.","difficulty":"hard","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-535","question":"Consider two claims:\nI. The probability of at least one six in 4 throws of a fair die is more than 1/2.\nII. The probability of at least one double six in 24 throws of a pair of fair dice is more than 1/2.\nWhich is true?","options":["I only","II only","Both I and II","Neither I nor II"],"answer":0,"explanation":"I: 1 − (5/6)⁴ = 671/1296 ≈ 0.518 > 1/2, true. II: 1 − (35/36)²⁴ ≈ 0.491 < 1/2, false. The naive scaling (4/6 = 24/36) suggests they should match, but 'at least once' probabilities do not scale linearly.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-536","question":"How many ordered pairs (a, b), with a and b each from 1 to 20, have no common factor other than 1?","options":["128","255","243","145"],"answer":1,"explanation":"For each b, the a ≤ b coprime to b number φ(b), and Σ φ(b) for b = 1 to 20 is 128. These are the pairs with a ≤ b; doubling and removing the double-counted (1, 1) gives 2 × 128 − 1 = 255. 128 counts only a ≤ b; 243 is the rough estimate 400 × 6/π²; 145 counts the pairs that are NOT coprime.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-537","question":"All 120 five-digit numbers formed by arranging 1, 2, 3, 4, 5 (no repetition) are listed in increasing order. What is the position of 35142?","options":["62","53","68","72"],"answer":2,"explanation":"Starting with 1 or 2: 2 × 4! = 48. Starting 31, 32 or 34: 3 × 3! = 18 (total 66). Then 351.. : 35124 comes first, then 35142, so it is 66 + 2 = 68th. 62 forgets the numbers starting 34; 53 counts from the top of the list.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-538","question":"10 identical chocolates are shared among 4 children so that every child gets at least 1 and nobody gets more than 4. In how many ways can this be done?","options":["84","40","4","44"],"answer":3,"explanation":"With everyone getting at least 1: 9C3 = 84 ways. A child getting 5 or more: give that child 4 extra and share the rest freely: 5C3 = 10 ways each, 40 in all (two children cannot both exceed 4). 84 − 40 = 44. The option 4 (= 84 − 80) comes from wrongly removing every case where a child gets 4 or more instead of 5 or more.","difficulty":"very-hard","source":"Capgemini · CAT"},
  {"id":"apt-pnc-probability-539","question":"What is the sum of all the 4-digit numbers that can be formed from the digits 1, 2, 3, 4, 5 if no digit is repeated?","options":["399960","99990","199980","533280"],"answer":0,"explanation":"There are 5P4 = 120 numbers; each digit appears in each place 4P3 = 24 times, so each place sums to 24 × 15 = 360 and the total is 360 × 1111 = 399960. 99990 uses 3! = 6 appearances per place; 199980 uses 12.","difficulty":"hard","source":"Infosys · Wipro"},
  {"id":"apt-pnc-probability-540","question":"Three of the eight corners of a cube are chosen at random. What is the probability that all three lie on one face of the cube?","options":["3/28","3/7","4/7","6/7"],"answer":1,"explanation":"Each of the 6 faces has 4C3 = 4 triples, and a triple of corners cannot lie on two faces, so 24 of the 8C3 = 56 triples: 3/7. 3/28 counts faces, not triples; 6/7 also counts the six diagonal rectangles through opposite edges, which are not faces.","difficulty":"hard","source":"CAT · Accenture"},
  {"id":"apt-pnc-probability-541","question":"How many solutions in non-negative integers does x + y + z = 10 have in which x, y and z are all different?","options":["60","66","48","8"],"answer":2,"explanation":"All solutions: 12C2 = 66. x = y: 2x + z = 10 gives 6 solutions, and likewise for y = z and x = z; all three equal is impossible (10 is not a multiple of 3), so 18 have a repeat and 66 − 18 = 48. 60 removes only one equal pair; 8 counts unordered sets.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-542","question":"Three different numbers are chosen at random from 1, 2, …, 20. What is the probability that their product is divisible by 4?","options":["17/19","61/76","23/76","53/76"],"answer":3,"explanation":"The product fails only if all three are odd (10C3 = 120) or exactly one is even and that one is 2 mod 4 — 2, 6, 10, 14 or 18 — with two odd numbers (5 × 10C2 = 225). P = 1 − 345/1140 = 53/76. 17/19 assumes any even factor suffices; 61/76 forgets the all-odd case.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-543","question":"How many 7-digit numbers have digits that add up to 61?","options":["28","21","7","49"],"answer":0,"explanation":"The maximum digit sum is 63, so the digits must fall short of all-9s by 2 in total: either one digit is 7 (7 ways) or two digits are 8 (7C2 = 21 ways). 28 in all. 21 and 7 count only one of the two cases.","difficulty":"very-hard","source":"CAT · TCS NQT"},
  {"id":"apt-pnc-probability-544","question":"In a league, each of 8 teams plays every other team twice (home and away). The top 4 then play two semi-finals and a final. How many matches are played in all?","options":["31","115","63","59"],"answer":3,"explanation":"League: each pair meets twice, 2 × 8C2 = 56 matches; play-offs: 2 semi-finals + 1 final = 3. Total 59. 31 plays each pair only once; 115 counts 8 × 7 × 2 = 112, counting every fixture from both teams' sides.","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-545","question":"Two different tickets are drawn at random from tickets numbered 1 to 20. What is the probability that the larger number is at least twice the smaller?","options":["10/19","9/19","5/19","1/2"],"answer":0,"explanation":"If the smaller number is a, the larger can be 2a to 20: 21 − 2a choices for a = 1 to 10, i.e. 19 + 17 + … + 1 = 100 pairs out of 20C2 = 190: 10/19. 9/19 reads 'more than twice' (drops b = 2a); 5/19 divides by ordered pairs (380).","difficulty":"hard","source":"Infosys · Capgemini"},
  {"id":"apt-pnc-probability-546","question":"In how many ways can three different numbers be chosen from 1, 2, …, 21 so that their sum is even?","options":["665","670","120","550"],"answer":1,"explanation":"There are 11 odd and 10 even numbers. Even sum: three evens (10C3 = 120) or two odds and one even (11C2 × 10 = 550). Total 670. 665 assumes exactly half of the 21C3 = 1330 triples, which fails because odds and evens are not equally many.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-547","question":"A courier goes from corner (0, 0) to corner (4, 3) of a street grid, always moving one block east or one block north. The one-block stretch going north from (2, 1) to (2, 2) is closed. How many routes are possible?","options":["17","35","26","9"],"answer":2,"explanation":"All routes: 7C3 = 35. Routes using the closed stretch: (0,0)→(2,1) in 3C1 = 3 ways and (2,2)→(4,3) in 3C1 = 3 ways, so 9. 35 − 9 = 26. 17 wrongly bans every route through the junction (2, 1), including those that leave it eastwards.","difficulty":"hard","source":"Accenture · Infosys"},
  {"id":"apt-pnc-probability-548","question":"In how many ways can two different numbers be chosen from 1, 2, …, 50 so that their difference is a multiple of 7?","options":["147","308","175","154"],"answer":3,"explanation":"The difference is a multiple of 7 when both numbers leave the same remainder on division by 7. Remainder 1 has 8 numbers (1, 8, …, 50) and each other remainder has 7: 8C2 + 6 × 7C2 = 28 + 126 = 154. 147 assumes all seven classes have 7 numbers; 175 assumes exactly 1/7 of all 1225 pairs.","difficulty":"hard","source":"CAT · TCS NQT"},
  {"id":"apt-pnc-probability-549","question":"A coin is tossed. On heads one fair die is rolled; on tails two fair dice are rolled. The total shown is 6. What is the probability that the coin showed heads?","options":["6/11","1/2","11/72","5/11"],"answer":0,"explanation":"P(heads and total 6) = 1/2 × 1/6 = 6/72; P(tails and total 6) = 1/2 × 5/36 = 5/72. So P(heads | 6) = 6/11. 11/72 is P(total 6) itself; 5/11 is the tails share.","difficulty":"hard","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-550","question":"The letters of the word ACCOUNT are arranged at random. What is the probability that the two C's are at the two ends?","options":["2/21","1/21","1/42","1/7"],"answer":1,"explanation":"The two C's occupy 2 of the 7 places, all 7C2 = 21 pairs of places equally likely, and only one pair is (first, last): 1/21. 2/21 counts the 'two orders' of identical C's; 1/42 treats the C's as distinct in the total (7!) but not in the favourable count (5!).","difficulty":"moderate","source":"TCS NQT · Wipro"},
  {"id":"apt-pnc-probability-551","question":"A 4-member team is chosen from 8 candidates A, B, C, D, E, F, G, H. A and B refuse to be in the team together, and C will join only if D is also in the team. How many teams are possible?","options":["55","35","39","50"],"answer":2,"explanation":"Teams without A and B together: 8C4 − 6C2 = 70 − 15 = 55. Remove those with C but not D: choose 3 from {A, B, E, F, G, H} (20 ways) minus those with both A and B (4 ways) = 16. 55 − 16 = 39. 35 subtracts all 20 without removing the A-and-B overlap, double-counting it.","difficulty":"hard","source":"Infosys · Accenture"},
  {"id":"apt-pnc-probability-552","question":"A box holds three ₹10 notes and two ₹50 notes. Two notes are taken out at random. What is the expected total value of the two notes?","options":["₹26","₹60","₹40","₹52"],"answer":3,"explanation":"Each note drawn has expected value (30 + 100)/5 = ₹26, and expectation adds even without replacement: 2 × 26 = ₹52. ₹26 counts only one note; ₹60 assumes a typical draw is one note of each kind.","difficulty":"moderate","source":"Capgemini · AMCAT"},
  {"id":"apt-pnc-probability-553","question":"Five cards are dealt from a well-shuffled pack of 52. What is the probability that both red and black cards appear among them?","options":["4745/4998","15/16","31/32","9743/9996"],"answer":0,"explanation":"Complement: all red or all black, 2 × 26C5 = 131560 of 52C5 = 2598960 hands, about 0.0506; so P = 4745/4998 ≈ 0.949. 15/16 = 1 − 2(1/2)⁵ treats the cards as dealt with replacement; 9743/9996 removes only the all-red hands.","difficulty":"hard","source":"Accenture · CAT"},
  {"id":"apt-pnc-probability-554","question":"In a test of 10 four-option questions, Rohit knows the answers to 6 and guesses the other 4 at random. What is the probability that he scores at least 9 correct answers?","options":["3/64","13/256","67/256","1/256"],"answer":1,"explanation":"He needs at least 3 of the 4 guesses right: 4C3 (1/4)³(3/4) + (1/4)⁴ = 12/256 + 1/256 = 13/256. 3/64 (= 12/256) is exactly 9; 67/256 is at least 8 correct (2 or more guesses).","difficulty":"hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-555","question":"How many integers from 1 to 1000 are neither perfect squares, nor perfect cubes, nor perfect fifth powers?","options":["956","962","960","969"],"answer":2,"explanation":"Squares 31, cubes 10, fifth powers 3 (1, 32, 243). Overlaps: sixth powers 3 (1, 64, 729), tenth powers 1, fifteenth powers 1, thirtieth powers 1. Union = 31 + 10 + 3 − 3 − 1 − 1 + 1 = 40, so 960. 956 forgets the overlaps; 962 ignores fifth powers altogether.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-556","question":"A fair die is rolled once; if it shows k, a fair coin is then tossed k times. What is the probability that no head appears?","options":["1/12","63/64","1/64","21/128"],"answer":3,"explanation":"P = (1/6)(1/2 + 1/4 + … + 1/64) = (1/6)(63/64) = 21/128. 1/12 considers only k = 1; 1/64 assumes 6 tosses every time; 63/64 forgets the 1/6 weighting.","difficulty":"hard","source":"Accenture · Capgemini"},
  {"id":"apt-pnc-probability-557","question":"The four aces and four kings of a pack are laid in a row. In how many arrangements are no two aces next to each other?","options":["2880","576","120","5760"],"answer":0,"explanation":"Arrange the kings (4! = 24); they leave 5 gaps, of which 4 receive one ace each in 5C4 × 4! = 120 ways. 24 × 120 = 2880. 576 forgets the choice of gaps; 120 forgets to arrange the kings.","difficulty":"hard","source":"TCS NQT · AMCAT"},
  {"id":"apt-pnc-probability-558","question":"4 boys and 4 girls are paired off at random into 4 pairs for a project. What is the probability that every pair has one boy and one girl?","options":["1/16","8/35","1/105","12/35"],"answer":1,"explanation":"There are 7 × 5 × 3 × 1 = 105 pairings, and 4! = 24 of them match each boy with a girl: 24/105 = 8/35. Step by step: (4/7)(3/5)(2/3) = 8/35. 1/16 treats each pair as an independent 50–50; 1/105 is one specific pairing.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-559","question":"How many of the integers 1, 2, …, 100 can be written as x² − y² with x and y non-negative integers?","options":["50","25","75","100"],"answer":2,"explanation":"x² − y² = (x − y)(x + y), and the two factors have the same parity, so the result is odd or a multiple of 4; every such n works (odd n = 2k + 1 = (k+1)² − k², 4m = (m+1)² − (m−1)²). Only numbers of the form 4k + 2 fail: 25 of them, leaving 75. 50 counts only odd numbers.","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-560","question":"Seven points lie on one straight line and five on another line parallel to it. How many triangles have their vertices among these 12 points?","options":["220","185","105","175"],"answer":3,"explanation":"Every triangle takes two points from one line and one from the other: 7C2 × 5 + 5C2 × 7 = 105 + 70 = 175 (or 12C3 − 7C3 − 5C3). 185 removes only the collinear triples on the 7-point line; 105 counts only one of the two cases.","difficulty":"moderate","source":"TCS NQT · Capgemini"},
  {"id":"apt-pnc-probability-561","question":"How many rectangles of area exactly 8 square units, with sides along the grid lines, are there on an 8 × 8 chessboard?","options":["86","70","43","78"],"answer":0,"explanation":"Shapes 1 × 8 and 8 × 1: 8 each. 2 × 4: 7 × 5 = 35 positions, and 4 × 2 also 35. 8 + 8 + 35 + 35 = 86. 70 misses the 1 × 8 strips; 43 counts each shape in one orientation only.","difficulty":"very-hard","source":"CAT · Product company OA"},
  {"id":"apt-pnc-probability-562","question":"How many 4-digit numbers (1000 to 9999) use exactly two different digits, such as 3383 or 7000?","options":["630","567","504","576"],"answer":1,"explanation":"Two non-zero digits: 9C2 = 36 pairs, each giving 2⁴ − 2 = 14 strings: 504. A non-zero digit a with 0: a must lead, and the other 3 places use a or 0 but not all a: 2³ − 1 = 7, so 9 × 7 = 63. Total 567. 630 ignores the leading-zero problem; 576 allows 'aaaa' in the second case.","difficulty":"very-hard","source":"CAT · TCS NQT"},
  {"id":"apt-pnc-probability-563","question":"A number from 1 to 100 is chosen at random, and it turns out not to be divisible by 5. What is the probability that it is divisible by 2 or by 3?","options":["67/100","27/40","2/3","27/50"],"answer":1,"explanation":"80 numbers are not multiples of 5. Multiples of 2 or 3 up to 100: 50 + 33 − 16 = 67; of these, multiples of 10 or 15: 10 + 6 − 3 = 13 are multiples of 5. So 54/80 = 27/40. 67/100 ignores the condition; 27/50 keeps 100 as the denominator.","difficulty":"hard","source":"Infosys · AMCAT"},
  {"id":"apt-pnc-probability-564","question":"Two players each roll a fair die; the higher number wins, and on a tie both roll again. What is the expected number of rounds needed to get a winner?","options":["6","5/6","6/5","7/6"],"answer":2,"explanation":"A round ends the game with probability 1 − 1/6 = 5/6, so the expected number of rounds is 1/(5/6) = 6/5. 6 inverts the tie probability instead; 7/6 allows at most one replay.","difficulty":"hard","source":"Accenture · Product company OA"},
  {"id":"apt-pnc-probability-565","question":"A point is chosen at random inside a square of side 2 units. What is the probability that it lies within 1 unit of the centre of the square?","options":["π/2","π/16","1/2","π/4"],"answer":3,"explanation":"The favourable region is a circle of radius 1 (area π) that fits inside the square of area 4: π/4 ≈ 0.785. π/2 divides by the wrong area; π/16 takes the radius to be 1/2.","difficulty":"hard","source":"Capgemini · CAT"},
  {"id":"apt-pnc-probability-566","question":"How many 5-digit numbers have digits that alternate between odd and even (for example 52741 or 21036)?","options":["5625","6250","3125","2500"],"answer":0,"explanation":"Odd-even-odd-even-odd: 5⁵ = 3125. Even-odd-even-odd-even: the leading even digit cannot be 0, so 4 × 5⁴ = 2500. Total 5625. 6250 lets the number start with 0.","difficulty":"very-hard","source":"TCS NQT · Infosys"},
  {"id":"apt-pnc-probability-567","question":"A box has 2 white and 3 black balls. All five are drawn one by one without replacement. What is the probability that the last ball drawn is white?","options":["1/2","2/5","3/5","1/10"],"answer":1,"explanation":"Every ball is equally likely to be the last one, so P = 2/5, exactly as for the first draw. 1/2 thinks of 'white or black' as equally likely; 1/10 is the chance that both whites come last.","difficulty":"hard","source":"Accenture · AMCAT"},
  {"id":"apt-pnc-probability-568","question":"A fair die is rolled repeatedly until the running total of all the rolls is at least 2. What is the expected number of rolls?","options":["2","1","7/6","11/6"],"answer":2,"explanation":"One roll suffices unless it shows 1 (probability 1/6); then exactly one more roll is needed, since any roll brings the total to 2 or more. E = 1 + 1/6 = 7/6. 2 assumes a second roll is always needed; 11/6 uses 5/6 for the chance of needing it.","difficulty":"very-hard","source":"Product company OA · CAT"},
  {"id":"apt-pnc-probability-569","question":"How many 6-digit numbers that use each of the digits 1, 2, 3, 4, 5, 6 exactly once are divisible by 11?","options":["36","72","48","0"],"answer":3,"explanation":"Divisible by 11 needs (sum of odd-place digits) − (sum of even-place digits) to be a multiple of 11. The total is 21 (odd), so the difference is odd and cannot be 0; it would have to be ±11, meaning sums 16 and 5, but three different digits add up to at least 6. So no such number exists. 72 assumes an equal split exists (2 × 3! × 3!).","difficulty":"very-hard","source":"CAT · Infosys"},
  {"id":"apt-pnc-probability-570","question":"A fair die is rolled three times. What is the probability that the three numbers can be the side lengths of a non-degenerate triangle?","options":["13/18","17/28","1/2","37/72"],"answer":3,"explanation":"Count ordered triples where the largest is less than the sum of the other two: 111 of the 216, so 111/216 = 37/72. 13/18 also counts flat 'triangles' with a + b = c; 17/28 counts unordered multisets as if equally likely.","difficulty":"very-hard","source":"CAT · Product company OA"},
];

export default questions;
